// Secondary prompts for the 2026-2027 cycle, collected from each school's Student Doctor Network thread (MD Oct 31, DO Nov 1, 2026).
// Regenerate from the catalogue; keep school names stable (added schools are matched by name).
window.PROMPT_LIBRARY = {"cycle":"2026-2027","updated":"2026-11-01","source":"Student Doctor Network school threads","schools":[{"name":"A.T. Still University - Kirksville College of Osteopathic Medicine (ATSU-KCOM)","state":"MO","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-a-t-still-university-kirksville-college-of-osteopathic-medicine-atsu-kcom.1518385/","prompts":[{"p":"Describe one or more significant life experiences that have meaningfully shaped your development as a potential future physician. What did you come to understand about yourself, and how has that insight altered your perspective or behavior?","limit":500,"unit":"words","fam":"diversity"},{"p":"Describe your experiences with osteopathic medicine and how they have influenced your decision to pursue a career as an osteopathic physician.","limit":500,"unit":"words","fam":"osteo"},{"p":"If yes, detail below what has changed since your last application.","limit":0,"unit":"words","fam":"other"}]},{"name":"A.T. Still University - School of Osteopathic Medicine in Arizona (ATSU-SOMA)","state":"AZ","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-a-t-still-university-school-of-osteopathic-medicine-in-arizona-atsu-soma.1518386/","prompts":[{"p":"What particular qualities do you feel that you can bring to ATSU SOMA?","limit":0,"unit":"words","fam":"diversity"},{"p":"Discuss a situation in which you had to persevere despite facing obstacles or setbacks. How did you maintain your motivation and keep moving forward towards your goals?","limit":0,"unit":"words","fam":"challenge"},{"p":"Tell us about a mistake you made that had consequences for yourself or others. How did you respond in the moment, what responsibility did you take, and what did you learn about accountability and integrity from the experience?","limit":0,"unit":"words","fam":"challenge"},{"p":"Is there anything else you would like to share with the SOMA Admissions Committee about your application?","limit":0,"unit":"words","fam":"anything"}]},{"name":"Alabama College of Osteopathic Medicine (ACOM)","state":"AL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-alabama-college-of-osteopathic-medicine-acom.1518387/","prompts":[],"none":"No written essays reported"},{"name":"Albany Medical College","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-albany-medical-college.1517671/","prompts":[{"p":"Describe yourself","limit":1000,"unit":"chars","fam":"diversity"},{"p":"Please explain any inconsistencies in your university, graduate, or professional school academic performance and/or MCAT scores. If the question does not apply to you, please put N/A in the box provided","limit":1000,"unit":"chars","fam":"other"},{"p":"Has your college or university, graduate or professional school attendance been interrupted for any reason? If yes, please explain. Also, please explain any extended gaps in activity/employment in your post-graduate history. If the question does not apply to you, please put N/A in the box provided","limit":1000,"unit":"chars","fam":"gap"},{"p":"Please describe your personal experiences with the structural and social determinants of health in your life and community, how they shaped your engagement with medicine and your future ideas for doctoring","limit":1000,"unit":"chars","fam":"service"},{"p":"Tell us about a community with which you identify and how you are involved with it","limit":1000,"unit":"chars","fam":"diversity"},{"p":"Is there anything else you would like the admissions committee to know when reviewing your application? If so, please use the space provided","limit":1000,"unit":"chars","fam":"anything"},{"p":"In the \"Work and Activities\" section on your AMCAS application, you provided the following list of experiences. Please select the experience that you feel has been the most meaningful in influencing your desire to pursue a career in medicine, explain why, and also describe what aspect of that experience best equips you to make an impact in the medical profession.","limit":1000,"unit":"chars","fam":"other"},{"p":"Describe a significant challenge that has prepared you for the MD career path.","limit":1000,"unit":"chars","fam":"challenge"}]},{"name":"Albert Einstein College of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-albert-einstein-in-college-of-medicine.1517672/","prompts":[{"p":"What unique life experiences, personal attributes and/or perspectives will you bring as part of the incoming class? Are there particular challenges or successes that you have encountered? If you do not wish to write anything, please write “NA.”","limit":3000,"unit":"chars","fam":"diversity","opt":1},{"p":"Please use this space to tell us anything about yourself that you would like us to know. If you do not wish to write anything, please write “NA.”","limit":3000,"unit":"chars","fam":"anything","opt":1}]},{"name":"Alice L Walton School of Medicine","state":"AR","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-alice-l-walton-school-of-medicine.1517670/","prompts":[{"p":"Describe how AWSOM’s mission and values align with your personal and professional goals. Please include how you believe AWSOM will help you develop into the kind of person and physician you hope to become.","limit":1500,"unit":"chars","fam":"why"},{"p":"The Admissions Committee evaluates a range of student qualities, characteristics, and life experiences that complement demonstrated academic excellence. What unique qualities or individual lived experiences do you possess that make you uniquely suited to become a physician?","limit":1500,"unit":"chars","fam":"diversity"},{"p":"Describe your experiences engaging in the community, and how those experiences have prepared you for a future as a physician.","limit":1500,"unit":"chars","fam":"service"},{"p":"Trust and rapport are essential in your day-to-day interactions with people. How do you cultivate a relationship with a person who may be very different from you?","limit":1500,"unit":"chars","fam":"diversity"},{"p":"Whole health considers the needs of the whole person with the goal of preventing disease, improving health outcomes, and sustaining wellness. How do you practice whole health in your personal life, and how do you aspire to incorporate whole health principles when caring for the community?","limit":1500,"unit":"chars","fam":"other"},{"p":"Optional: Gap Year(s) if applicable: If you are taking time off between college graduation and medical school matriculation, please tell us why you made this decision and what you will be doing or have done during this gap time.","limit":1500,"unit":"chars","fam":"gap","opt":1},{"p":"Optional: Is there any additional information not included elsewhere in your application you would like the admissions committee to know?","limit":1500,"unit":"chars","fam":"anything","opt":1}]},{"name":"Arizona College of Osteopathic Medicine of Midwestern University (MWU-AZCOM)","state":"AZ","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-arizona-college-of-osteopathic-medicine-of-midwestern-university-mwu-azcom.1518388/","prompts":[],"none":"No written essays reported"},{"name":"Arkansas College of Osteopathic Medicine (ARCOM)","state":"AR","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-arkansas-college-of-osteopathic-medicine-arcom.1518390/","prompts":[{"p":"How do you plan to fulfill the ARCOM Mission in your practice as a physician?","limit":0,"unit":"words","fam":"why"},{"p":"What challenges do you expect to personally face most in the next 10 years as a healthcare professional?","limit":0,"unit":"words","fam":"challenge"},{"p":"How do you expect to overcome these challenges?","limit":0,"unit":"words","fam":"challenge"},{"p":"Describe an experience where you interacted with a person or people from a different background than you (ability, religion, gender, race, age, socioeconomic status, citizenship/ nationality, sexual orientation).","limit":0,"unit":"words","fam":"diversity"},{"p":"How did that interaction impact your mindset of the role of a physician?","limit":0,"unit":"words","fam":"diversity"},{"p":"If you are in a difficult basic science class and feel you are not fully grasping the information given in lecture, how would you alter your study habits or techniques to better understand the material and complete the course successfully?","limit":0,"unit":"words","fam":"other"},{"p":"What is a recent book or movie you've read or watched that impacted the way you think about today's world?","limit":0,"unit":"words","fam":"other"},{"p":"Please explain how this book impacted the way you think about today's world.","limit":0,"unit":"words","fam":"other"}]},{"name":"ASU John Shufeldt School of Medicine and Medical Engineering","state":"AZ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-asu-school-of-medicine-and-engineering.1517673/","prompts":[{"p":"Innovation in medicine is most powerful when it centers the human experience. Describe a time when you challenged an existing approach, such as clinical, educational, technological, or social, to better serve patients, communities, or learners. What motivated your approach, and what did you learn?","limit":350,"unit":"words","fam":"other"},{"p":"Medicine often operates in uncertainty, ambiguity, and complexity. Describe a moment when no clear “right answer” existed. How did you navigate ambiguity, and how did that experience influence your approach to decision-making or care?","limit":350,"unit":"words","fam":"ethics"},{"p":"The mission of the Arizona State University’s John Shufeldt School of Medicine and Medical Engineering is to transform healthcare delivery, produce healthcare leaders, and address health challenges facing Arizona and beyond, by integrating medicine, engineering, technology, and the humanities.” Please describe the role(s) you would like to play in helping ASU John Shufeldt School of Medicine and Medical Engineering to achieve its mission.","limit":350,"unit":"words","fam":"why"},{"p":"Optional: Please share any additional information that you wish the Admissions Committee to know. Essays can focus on your current activities if you are not currently pursuing a degree, your connection to ASU or the greater Phoenix area, any academic disruptions you would like to clarify, or other information that provides insight on your candidacy.","limit":350,"unit":"words","fam":"anything","opt":1}]},{"name":"Baptist Health Sciences University College of Osteopathic Medicine (BUCOM)","state":"TN","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-baptist-health-sciences-university-college-of-osteopathic-medicine-bucom.1518391/","prompts":[],"none":"No prompts posted yet"},{"name":"Baylor College of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-baylor-college-of-medicine.1517674/","prompts":[{"p":"In addition to training as a competent physician, please select up to two additional areas of interest from the items below that you may want to pursue during your medical studies. Your responses will have no bearing on applications to joint degrees or special programs to which you might also apply. [Clinical Research; Healthcare/disparities/medical underserved communities; Academic Medicine; Community Health; Simulation in medical education; Health systems science; Telehealth; Advocacy] What knowledge, skills and attitudes have you developed that have prepared you for this career path?","limit":1000,"unit":"chars","fam":"career","group":"Choose up to 2 of 8 areas"},{"p":"Are you planning to matriculate into medical school immediately after completing your undergraduate education? If not, please explain what activities and/or careers you have pursued in the time between your college education and your application.","limit":0,"unit":"words","fam":"gap"},{"p":"Indicate any special experiences, unusual factors or other information you feel would be helpful in evaluating you, including, but not limited to, education, employment, extracurricular activities, prevailing over adversity. You may expand upon but not repeat TMDSAS or AMCAS application information.","limit":2000,"unit":"chars","fam":"anything"}]},{"name":"Boston University Chobanian & Avedisian School of Medicine","state":"MA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-boston-university.1517675/","prompts":[{"p":"Do you hope to attend medical school immediately after earning your undergraduate degree? If no, describe how you've spent your time leading up to applying to medical school. This may include attending a post-baccalaureate program or other education, gap year activities such as employment or travel, or other relevant pursuits.","limit":300,"unit":"words","fam":"gap"},{"p":"Provide a timeline or narrative highlighting any notable aspects of your educational journey that you believe are especially relevant or significant to us better understanding who you are. Section not required but...this is an opportunity to describe any learning experience(s) that are not covered in other sections of your supplemental application or AMCAS application. For example, have you lived in another country or experienced a culture unlike your own? Worked in a field that contributed to your understanding of people unlike yourself? Do you have advanced training in art, music, or sports, etc.?","limit":300,"unit":"words","fam":"diversity","opt":1},{"p":"Why BU Chobanian & Avedisian SOM? Boston Medical Center is the largest safety net hospital in New England, serving primarily people who are publicly insured, people of color, immigrants, and low-income people in the Greater Boston Area. Why are you specifically interested in beginning your medical education in this environment, and how do you feel that your previous experiences will prepare you for this unique learning environment?","limit":300,"unit":"words","fam":"why"},{"p":"[OPTIONAL] Use this space to provide any additional information you feel will provide us with a comprehensive understanding of your strengths as a candidate for a career in medicine. Do not include information already provided in your AMCAS application or other sections of the supplemental application. Most students leave this blank.","limit":300,"unit":"words","fam":"anything","opt":1}]},{"name":"Brown University Warren Alpert Medical School","state":"RI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-brown-university-warren-alpert-medical-school.1517676/","prompts":[{"p":"(Optional) Premed competencies alternatives. If you believe that you have demonstrated competence in these disciplines in an alternate manner, please describe in the text box below that relevant coursework, individualized study, research, or employment. If you believe that you have fulfilled competency through a standardized examination such as Advanced Placement or the SAT II, please list the name, date and score of the exam(s) in the text box below that you wish to substitute in lieu of a premedical course.","limit":500,"unit":"chars","fam":"other","opt":1},{"p":"(Optional) Do you have significant limitations on your interview availability? NOTE: Interviews occur on Thursday’s and/or Friday’s beginning in mid-September and finishing in February. Please detail any significant limitations on your availability during this time, such as international travel, work or courses. You may use the text box below to explain your limited availability. (if none, leave blank)","limit":500,"unit":"chars","fam":"other","opt":1},{"p":"Summarize your activities during this academic year. Describe how your activities are preparing you for a medical career.","limit":2000,"unit":"chars","fam":"gap"},{"p":"How will your unique attributes, life experiences, and interests add to The Warren Alpert Medical School community?","limit":2000,"unit":"chars","fam":"diversity"},{"p":"Reflect on a non-academic situation when you had to change course, and how you did so.","limit":3000,"unit":"chars","fam":"challenge"}]},{"name":"Burrell College of Health Sciences School of Osteopathic Medicine (BCSOM)","state":"NM","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-burrell-college-of-health-sciences-school-of-osteopathic-medicine-bcsom.1518392/","prompts":[{"p":"In what area of medicine do you see yourself practicing, and in what type of setting?","limit":300,"unit":"words","fam":"career"},{"p":"Reflect on a previous experience where you interacted with individuals from a different background than your own. What challenges did this present, if any? How did you demonstrate openness to their perspective? How will the experience influence your approach to patient care in the future?","limit":300,"unit":"words","fam":"diversity"},{"p":"If you could strengthen one area of your application, what would it be? What have you done, or what do you plan to do, to address it and improve going forward?","limit":300,"unit":"words","fam":"other"}]},{"name":"Burrell College of Health Sciences School of Osteopathic Medicine - Melbourne (BCSOM-Melbourne)","state":"FL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-burrell-college-of-health-sciences-school-of-osteopathic-medicine-melbourne-burrell-com-melbourne.1518393/","prompts":[],"none":"No prompts posted yet"},{"name":"BYU School of Medicine","state":"UT","deg":"MD","url":"https://forums.studentdoctor.net/threads/byus-new-md-medical-school-got-approval-theyre-now-accepting-applications-for-this-cycle.1522087/","prompts":[],"none":"No prompts posted yet"},{"name":"California Health Sciences University College of Osteopathic Medicine (CHSU-COM)","state":"CA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-california-health-sciences-university-college-of-osteopathic-medicine-chsu-com.1518394/","prompts":[{"p":"CHSU values a student body that embraces our University’s mission. Please explain how you would personally contribute to advancing CHSU’s mission.","limit":1500,"unit":"chars","fam":"why"},{"p":"Please share why are you interested in Osteopathic Medicine and why you want to be trained as an osteopathic physician.","limit":1500,"unit":"chars","fam":"osteo"}]},{"name":"California Northstate University College of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-california-northstate-university.1517690/","prompts":[],"none":"No prompts posted yet"},{"name":"California University of Science and Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-california-university-of-science-and-medicine.1517689/","prompts":[{"p":"Diversity comes in many forms. How do you think you might contribute to the diversity of the class?","limit":150,"unit":"words","fam":"diversity"},{"p":"Describe the last time you were criticized by a peer or supervisor. How did you handle it?","limit":150,"unit":"words","fam":"challenge"},{"p":"Give an example of when you had to work with someone who was difficult to get along with. Why was this person difficult? How did you handle that person?","limit":150,"unit":"words","fam":"team"},{"p":"What would be the best example that shows you are a person of integrity?","limit":150,"unit":"words","fam":"ethics"},{"p":"If given the opportunity to attend medical school, where would you see yourself in ten years?","limit":150,"unit":"words","fam":"career"},{"p":"If you were enrolled in fewer than 12 units/credits for more than 1 semester/2 quarters during your undergraduate education, please provide a brief explanation below. (If not applicable, please enter N/A in the box below)","limit":150,"unit":"words","fam":"other"}]},{"name":"Campbell University Jerry M. Wallace School of Osteopathic Medicine (CUSOM)","state":"NC","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-campbell-university-jerry-m-wallace-school-of-osteopathic-medicine-cusom.1518395/","prompts":[{"p":"Which person in your life has contributed most to your choice of a career in medicine and describe how that individual influenced your decision to be a physician?","limit":0,"unit":"words","fam":"other"},{"p":"The MISSION of Campbell University School of Osteopathic Medicine (CUSOM) is to educate and prepare community–based osteopathic physicians in a Christian environment to care for the rural and under-served populations in North Carolina, the Southeastern United States, and the nation. Briefly describe how your career goals align with the CUSOM Mission","limit":4000,"unit":"chars","fam":"why"},{"p":"Identify three of your core values, and discuss how these values align with the CUSOM Mission","limit":4000,"unit":"chars","fam":"why"}]},{"name":"Carle Illinois College of Medicine","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-carle-illinois-college-of-medicine.1517691/","prompts":[],"none":"No written essays reported"},{"name":"Case Western Reserve University School of Medicine","state":"OH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-case-western-reserve-university.1517692/","prompts":[],"none":"No prompts posted yet"},{"name":"Central Michigan University College of Medicine","state":"MI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-central-michigan-university.1517693/","prompts":[{"p":"(If you select any affiliation) Please provide a brief summary of your affiliation with any County selected:","limit":0,"unit":"words","fam":"other","opt":1},{"p":"(If taking a gap year) Describe what activities you have engaged in since degree completion.","limit":0,"unit":"words","fam":"gap","opt":1},{"p":"Describe your motivation for applying to the Covenant HealthCare College of Medicine at Central Michigan and your future career in medicine. Finally, describe how your preparation and background will contribute to the mission of the College of Medicine.","limit":1000,"unit":"words","fam":"why"},{"p":"[REAPP ONLY]: If you have applied to any medical school in previous cycles, what have you done since your last application to prepare yourself for a career in medicine? If you have not applied to medical school previously, write “N/A” in the box.","limit":0,"unit":"words","fam":"other","opt":1}]},{"name":"Charles R. Drew University College of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-charles-r-drew-university.1517694/","prompts":[{"p":"CDU's vision is \"Excellent health and wellness for all in a world without health disparities.\" Using a specific experience from your background — clinical, community, research, or personal — describe how this vision has already shaped your path and how you plan to advance it as a CDU physician.","limit":0,"unit":"words","fam":"why"},{"p":"Beyond stating your commitment, illustrate it: describe a specific moment when you took meaningful action to address the health needs of an underserved or underrepresented community. What did you do, what did you learn, and how has it shaped the physician you intend to become?","limit":0,"unit":"words","fam":"service"},{"p":"What draws you to CDU specifically — not medicine generally? Identify concrete elements of CDU's mission, curriculum, community, or location that align with your goals and are not easily found elsewhere. Be specific about why CDU is the right fit for you.","limit":0,"unit":"words","fam":"why"},{"p":"Describe a specific instance in which you experienced or witnessed discrimination. What was the impact on you or others involved? How did this experience shape your understanding of equity, and how will it inform your practice as a physician?","limit":0,"unit":"words","fam":"diversity"},{"p":"Describe a concrete vision for your post-residency impact: Which community do you intend to serve, what unmet need will you address, and what specific role — clinical, advocacy, research, or policy — do you see yourself playing? Be as specific as possible about place, population, and purpose.","limit":0,"unit":"words","fam":"career"},{"p":"How will you use your personal experience with poverty and housing insecurity as a physician? Describe how it has shaped your perspective on health, access to care, or the doctor-patient relationship. How will this lived experience inform the way you approach patients facing similar circumstances?","limit":800,"unit":"chars","fam":"diversity"}]},{"name":"Chicago College of Osteopathic Medicine of Midwestern University (MWU-CCOM)","state":"IL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-chicago-college-of-osteopathic-medicine-of-midwestern-university-mwu-ccom.1518413/","prompts":[],"none":"No written essays reported"},{"name":"Chicago Medical School at Rosalind Franklin","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-chicago-medical-school-at-rosalind-franklin.1517695/","prompts":[{"p":"Chicago Medical School values service, interprofessional collaboration, and community engagement. Describe an experience that reflects one or more of these values and how you hope to continue this work during your time in medical school.","limit":150,"unit":"words","fam":"service"},{"p":"Which specific programs, opportunities, or aspects of Chicago Medical School at Rosalind Franklin University motivated you to apply, and how do they align with your career goals?","limit":150,"unit":"words","fam":"why"},{"p":"What interests you about training in the Chicago/North Chicago region, and how might this environment shape your medical education and future career as a physician?","limit":150,"unit":"words","fam":"why"},{"p":"If you joined the Chicago Medical School community, how would you contribute to the learning environment through initiatives, organizations, or areas of involvement that interest you?","limit":150,"unit":"words","fam":"diversity"},{"p":"Describe a time when you received difficult or unexpected feedback about your academic performance or behavior. How did you respond to that feedback, and what changes did you make as a result?","limit":150,"unit":"words","fam":"challenge"}]},{"name":"Cleveland Clinic Lerner College of Medicine","state":"OH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-cleveland-clinic-lerner-college-of-medicine.1517696/","prompts":[],"none":"No prompts posted yet"},{"name":"Columbia Vagelos College of Physicians and Surgeons","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-columbia-vagelos-university-college-of-physicians-and-surgeons.1518230/","prompts":[{"p":"Did you work for compensation during your undergraduate studies (either during the academic year or summers)?","limit":0,"unit":"words","fam":"other"},{"p":"Optional: What did you do? How many hours a week did you work?","limit":0,"unit":"words","fam":"other","opt":1},{"p":"Required: Please briefly summarize what you have done since graduating from your undergraduate institution:","limit":300,"unit":"words","fam":"gap"},{"p":"Required: Please describe your most meaningful leadership position(s):","limit":300,"unit":"words","fam":"team"},{"p":"Required: The Columbia University Vagelos College of Physicians and Surgeons values a wide array of experiences and perspectives. How will you contribute to this important value of our institution, and how will it inform your future role as a physician?","limit":300,"unit":"words","fam":"diversity"},{"p":"Optional: Is there anything else you would like us to know?","limit":400,"unit":"words","fam":"anything","opt":1}]},{"name":"Cooper Medical School of Rowan University","state":"NJ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-cooper-medical-school-of-rowan-university.1517697/","prompts":[{"p":"Please describe your anticipated educational, employment, volunteer, or other activities between completing your AMCAS application and matriculating to medical school.","limit":1500,"unit":"chars","fam":"gap"},{"p":"We are a mission-aligned education program, please describe how CMSRU will help you fulfill your mission?","limit":1500,"unit":"chars","fam":"why"},{"p":"Medical school involves hard work and can be stressful at times. Tell us about activities that you use to help maintain a work-life balance and respond to stress.","limit":1500,"unit":"chars","fam":"other"},{"p":"Optional: Please share with us something unique about your pathway to medical school, including any obstacles you may have faced.","limit":1500,"unit":"chars","fam":"challenge","opt":1}]},{"name":"Creighton University School of Medicine","state":"NE","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-creighton-university-school-of-medicine.1517698/","prompts":[{"p":"Please state your reasons for applying to Creighton University School of Medicine.","limit":2000,"unit":"chars","fam":"why"},{"p":"Using an example or examples, describe the effect that your experience(s) engaging with disadvantaged and/or underserved populations have had on you own growth and development. Reflect on how this/these experience(s) will impact your career as a future physician.","limit":2000,"unit":"chars","fam":"service"},{"p":"Describe how you have dealt with a personal challenge or major obstacle that you have overcome. Focus on what you learned about yourself and how it will help you during the challenges you might face in medical school.","limit":2000,"unit":"chars","fam":"challenge"},{"p":"Medicine requires individuals to uphold professional standards even in difficult situations. Describe a personal experience that influenced your understanding of professionalism and explain how it will guide your conduct in medical school.","limit":2000,"unit":"chars","fam":"ethics"},{"p":"Please reflect on your entire application, is there anything you would like to further share with the Admissions Committee? Gap(s) in your education, personal and/or academic challenges, etc.","limit":2000,"unit":"chars","fam":"anything","opt":1},{"p":"Please describe your current activities/employment if you are not currently enrolled as a fulltime student.","limit":0,"unit":"words","fam":"gap","opt":1},{"p":"\"Women and Men for and with Others\" is a fundamental Jesuit value and an important part of the Creighton University School of Medicine mission. Reflect on a meaningful service experience or community engagement activity that shaped your understanding of serving others. What did you learn about yourself, others, and your role in the community through this experience?","limit":2000,"unit":"chars","fam":"service"}]},{"name":"D'Youville University College of Osteopathic Medicine (DYUCOM)","state":"NY","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-dyouville-university-college-of-osteopathic-medicine.1520534/","prompts":[],"none":"No written essays reported"},{"name":"Dartmouth Geisel School of Medicine","state":"NH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-dartmouth-geisel-school-of-medicine.1517699/","prompts":[{"p":"Please indicate your plans for 2026-2027. If in school, list the courses you will be taking. If working, tell us about your job. If your plans or courses change, subsequently, please inform the Admissions Office by email at … For course changes, we only need to be notified about changes related to prerequisite courses.","limit":250,"unit":"words","fam":"gap","cut":1},{"p":"Please reflect on your primary application and share something not addressed in your experiences or personal statement that would be helpful to the Admissions Committee as we review your file.","limit":300,"unit":"words","fam":"anything"},{"p":"Are there specific aspects of the Geisel School of Medicine that draw you to apply? What are the characteristics and strengths you will bring to our program, and how will you contribute to our community?","limit":300,"unit":"words","fam":"why"},{"p":"Dartmouth values a culture of inquiry and respect and encourages dialogues that harness diversity and openness of thought. Reflect on a situation where you felt different from those around you, or one where your perspective differed from others.","limit":250,"unit":"words","fam":"diversity"}]},{"name":"Dell Medical School","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-dell-medical-school.1517700/","prompts":[],"none":"No written essays reported"},{"name":"Des Moines University College of Osteopathic Medicine (DMU-COM)","state":"IA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-des-moines-university-college-of-osteopathic-medicine-dmu-com.1518415/","prompts":[],"none":"No written essays reported"},{"name":"Drexel University College of Medicine","state":"PA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-drexel-university-college-of-medicine.1517701/","prompts":[{"p":"Tell us about yourself and why you feel like you may be a good fit for Drexel University College of Medicine.","limit":1500,"unit":"chars","fam":"why"},{"p":"We recognize that each applicant’s journey is unique. If there were any extenuating circumstances that limited your involvement in service, academic, or other preparatory experiences—including MCAT preparation/taking—please share them here. If none, simply type “N/A” in the response area.","limit":1500,"unit":"chars","fam":"challenge"},{"p":"If you have applied to medical school before, reflect on any meaningful experiences, growth, or updates that you feel have enhanced your application since the last time you applied. If this is your first application cycle, simply type “N/A” in the response area.","limit":1500,"unit":"chars","fam":"other"},{"p":"Why are you interested in the Philadelphia/West Reading campus specifically?","limit":250,"unit":"words","fam":"why","opt":1}]},{"name":"Duke University School of Medicine","state":"NC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-duke-university-school-of-medicine.1517702/","prompts":[{"p":"Share with us your story.","limit":400,"unit":"words","fam":"diversity"},{"p":"Trust and rapport are essential in your day-to-day interactions with people. How do you build a relationship with a person who may be very different from you?","limit":400,"unit":"words","fam":"diversity"},{"p":"Describe a situation in which you chose to advocate for someone or for a cause different than yours. Define your view of advocacy. What risks, if any, might be associated with your choice to be an advocate?","limit":400,"unit":"words","fam":"service"},{"p":"Describe a time when you received feedback following a setback. What did you do to implement change?","limit":400,"unit":"words","fam":"challenge"},{"p":"What do you value most as a leader and as a contributor? What attributes do you possess as a leader and as a team member and how do you apply them on a daily basis?","limit":400,"unit":"words","fam":"team"},{"p":"Critical thinking involves a number of characteristics. Describe any research experience or similar experience in which you utilized critical thinking. How will critical thinking be important in your future career?","limit":400,"unit":"words","fam":"career"},{"p":"Drawing from your clinical experiences, how have you fostered a connection with people?","limit":400,"unit":"words","fam":"other"},{"p":"Which personal quality or skill of yours have you found to be the most beneficial in building relationships within your community?","limit":400,"unit":"words","fam":"service"},{"p":"Please let us know any additional information that you would like us to consider while reviewing your application.","limit":400,"unit":"words","fam":"anything"}]},{"name":"Duquesne University College of Osteopathic Medicine (DUQCOM)","state":"PA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-duquesne-university-college-of-osteopathic-medicine-duqcom.1518416/","prompts":[{"p":"Why do you want to become a physician, and how are you a good fit for DUQCOM's mission?","limit":500,"unit":"words","fam":"why"},{"p":"Can you describe an experience where you faced and overcame adversity?","limit":500,"unit":"words","fam":"challenge"},{"p":"How have your experiences and understanding of social determinants of health influenced your perspective on patient care and your approach to practicing medicine?","limit":500,"unit":"words","fam":"service","group":"Choose 1 of 2"},{"p":"Can you share an example of an altruistic experience you've had and explain how it influenced your desire to pursue a career in medicine?","limit":500,"unit":"words","fam":"service","group":"Choose 1 of 2"}]},{"name":"East Carolina University Brody School of Medicine","state":"NC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-east-carolina-university-brody-school-of-medicine.1517704/","prompts":[],"none":"No prompts posted yet"},{"name":"East Tennessee State University Quillen College of Medicine","state":"TN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-east-tennessee-state-university-quillen-college-of-medicine.1517705/","prompts":[{"p":"Why have you chosen to apply to Quillen College of Medicine? How do your personal and professional goals align with Quillen’s mission and values?","limit":1500,"unit":"chars","fam":"why"},{"p":"Quillen College of Medicine’s curriculum is designed to foster excellence in clinical practice through active, in-person participation and peer co-learning. This approach requires individual preparation, engagement in participatory class sessions, and a commitment to mutual coaching among peers. We believe that meaningful learning extends beyond academics and can be found in all areas of life. To help us understand how you will thrive in our community, please reflect on the significance of this learning model in your personal and professional development. In your response, consider the following: Describe a time when you navigated a challenging group learning experience. What was your role, and how did you contribute to the group’s success? Discuss the value you find in learning through teaching and coaching your peers. How does this approach enhance your understanding and application of material? You are encouraged to draw from both academic and non-academic experiences to illustrate your points.","limit":1500,"unit":"chars","fam":"team"},{"p":"Choose one of the following: a. As a physician, you will have the unique opportunity to foster positive change within your patients and community. Reflect on how your life experiences have shaped your values and attitudes towards others, especially those from different backgrounds or with differing values. How have these experiences prepared you to treat all patients with respect, care, compassion, and dignity, even when their beliefs differ from your own …","limit":1500,"unit":"chars","fam":"diversity","group":"Choose 1 of N (only option a posted)","cut":1}]},{"name":"Eastern Virginia Medical School at Old Dominion","state":"VA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-eastern-virginia-medical-school-at-old-dominion.1517706/","prompts":[{"p":"Briefly describe your exposure to medicine.","limit":2000,"unit":"chars","fam":"other"},{"p":"What do you think you will like best about being a physician?","limit":2000,"unit":"chars","fam":"career"},{"p":"What do you think you will like least about being a physician?","limit":2000,"unit":"chars","fam":"career"},{"p":"Describe yourself and your medical career as you see it ten years from now.","limit":2000,"unit":"chars","fam":"career"},{"p":"Please indicate your reasons for applying to VHS-EVMS at ODU.","limit":2000,"unit":"chars","fam":"why"},{"p":"VHS-EVMS at ODU is dedicated to inclusivity and supporting patients and students from diverse backgrounds. Feel free to share your personal experience or ties to communities from diverse backgrounds. If you wish to respond, please explain in detail. Some examples include but are not limited to race/ethnicity, culture, LGBTQ+, differently-abled/disabled, etc.","limit":2000,"unit":"chars","fam":"diversity","opt":1},{"p":"If you would like to discuss how your individual background, perspective, or experience, including any societal or other barriers, have affected your life, through discrimination, inspiration or otherwise, feel free to share your experiences, obstacles overcome, and how this impacted your education and road to applying to medical school.","limit":3000,"unit":"chars","fam":"challenge","opt":1}]},{"name":"Edward Via College of Osteopathic Medicine - Auburn Campus (VCOM-Auburn)","state":"AL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-edward-via-college-of-osteopathic-medicine-auburn-campus-vcom-auburn.1518417/","prompts":[],"none":"No prompts posted yet"},{"name":"Edward Via College of Osteopathic Medicine - Carolinas Campus (VCOM-Carolinas)","state":"SC","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-edward-via-college-of-osteopathic-medicine-carolinas-campus-vcom-carolinas.1518418/","prompts":[],"none":"No prompts posted yet"},{"name":"Edward Via College of Osteopathic Medicine - Louisiana Campus (VCOM-Louisiana)","state":"LA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-edward-via-college-of-osteopathic-medicine-louisiana-campus-vcom-louisiana.1518419/","prompts":[],"none":"No prompts posted yet"},{"name":"Edward Via College of Osteopathic Medicine - Virginia Campus (VCOM-Virginia)","state":"VA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-edward-via-college-of-osteopathic-medicine-virginia-campus-vcom-virginia.1518420/","prompts":[{"p":"Describe a significant challenge you have experienced in your life. Please share the strategies you employed to overcome the challenge, and what you learned from the experience.","limit":500,"unit":"words","fam":"challenge"},{"p":"How do your professional ambitions align with osteopathic medicine? What influenced your decision to apply to VCOM?","limit":500,"unit":"words","fam":"why"}]},{"name":"Emory University School of Medicine","state":"GA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-emory-university-school-of-medicine.1517707/","prompts":[{"p":"List your entire curriculum plan for the 2026-2027 academic year. If you are not in school, please briefly describe your plans for the coming year.","limit":200,"unit":"words","fam":"gap"},{"p":"Briefly describe your health-related experiences. Be sure to include important experiences that are in your AMCAS application, as well as any recent experiences.","limit":200,"unit":"words","fam":"other"},{"p":"Briefly describe your interest in Emory and the Emory degree program you have selected.","limit":200,"unit":"words","fam":"why"},{"p":"Emory School of Medicine is committed to recruiting and educating medical students who will help deliver quality health care and will promote the health of our patients. In our community, this includes learning about and addressing the health care needs of our most under-served populations. Please describe any of your activities that have been in service to under-served communities.","limit":200,"unit":"words","fam":"service"},{"p":"If you have any updates or new information to report since you have submitted your AMCAS primary application, please briefly describe below.","limit":200,"unit":"words","fam":"anything","opt":1}]},{"name":"Florida Atlantic University Schmidt College of Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-florida-atlantic-university-schmidt-college-of-medicine.1517708/","prompts":[{"p":"Use this area to justify and/or explain any academic hardships on your transcripts (any failed and/or repeated courses due to any reason","limit":1600,"unit":"chars","fam":"other"},{"p":"Use this area to explain exceptions to these prerequisites at your institution","limit":0,"unit":"words","fam":"other"},{"p":"Will you be enrolled as a student this year? Whether or not you will be a full-time student, please provide details of your activities/employment for the application year.","limit":1200,"unit":"chars","fam":"gap"},{"p":"Describe why you would like to attend the Charles E. Schmidt College of Medicine at FAU. What values, skills, talents, and life experiences would you contribute to our community?","limit":1600,"unit":"chars","fam":"why"},{"p":"Community engagement often requires humility, collaboration, and a willingness to learn from others. Describe a community service experience that significantly influenced your perspective. What did you learn about the community you served, about yourself, and how this experience has shaped the physician you hope to become?","limit":1600,"unit":"chars","fam":"service"},{"p":"Medical students and physicians rely on many personal qualities beyond academic achievement. Reflect on an experience from employment, volunteering, research, athletics, military service, or other meaningful activity that helped you develop qualities you believe are essential for success in medicine. How have these qualities prepared you for the challenges of medical school?","limit":1600,"unit":"chars","fam":"other"},{"p":"Leadership is demonstrated through initiative, service, and the ability to positively influence others. Describe a time when you identified a need or opportunity or took action to create positive change. What was your role, how did you work with others to affect change, and what did you learn from the experience?","limit":1600,"unit":"chars","fam":"team"},{"p":"If you are a reapplicant for medical school, please share examples of personal or professional experiences that you believe have strengthened your application, contributed to your growth, and have better prepared you for the rigors of medical school since your initial application.","limit":1600,"unit":"chars","fam":"other"}]},{"name":"Florida International University Herbert Wertheim College of Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-florida-international-university-herbert-wertheim-college-of-medicine.1517711/","prompts":[{"p":"Please explain what you have been doing, or will be doing since graduation prior to your planned matriculation to medical school. (Only if taking a gap year with no limit)","limit":0,"unit":"words","fam":"gap","opt":1},{"p":"Describe how your experiences and background have influenced the way you approach patient care and communication.","limit":1200,"unit":"chars","fam":"diversity"},{"p":"Why did you choose to apply to FIU Herbert Wertheim College of Medicine?","limit":1200,"unit":"chars","fam":"why"},{"p":"Describe a time you put another person's needs before your own. What did you do, and what motivated your actions?","limit":1200,"unit":"chars","fam":"service"},{"p":"Describe a meaningful clinical or hands-on care experience. What did it teach you about the realities of patient care, including any challenges or limitations you observed?","limit":1200,"unit":"chars","fam":"other"},{"p":"Use this area to explain any exception to the prerequisites at your institution.","limit":1000,"unit":"chars","fam":"other"},{"p":"Is there any additional information about your academic record that you would like the Admissions Committee to know? Please include any academic difficulties or course withdrawals.","limit":1000,"unit":"chars","fam":"other"}]},{"name":"Florida State University College of Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-florida-state-university-college-of-medicine.1517712/","prompts":[{"p":"Please provide a description of your family.","limit":500,"unit":"words","fam":"diversity"},{"p":"Please describe the geographic, economic, and social environment in which you were raised. How did these aspects of your upbringing shape who you are today or influence your goals?","limit":500,"unit":"words","fam":"diversity"},{"p":"Tell us what you do for fun and diversion (hobbies, special interests, etc.).","limit":500,"unit":"words","fam":"other"},{"p":"What is a unique trait, experience, or interest that we would not normally learn about you?","limit":500,"unit":"words","fam":"diversity"},{"p":"Were you employed during your college years? (Yes/No). If yes, describe why employment was necessary, how it impacted your college experience, and approximately how many hours per week you worked.","limit":500,"unit":"words","fam":"challenge"},{"p":"Is there anything in your academic record that you feel requires further explanation or context for the Admissions Committee? If applicable, please include information about any academic challenges, course withdrawals, or grades lower than a B.","limit":500,"unit":"words","fam":"anything","opt":1},{"p":"Why are you choosing to apply to the FSU College of Medicine? Please be specific describing what is particularly attractive about FSU COM and why you believe FSU COM is right for you.","limit":500,"unit":"words","fam":"why"},{"p":"What do you feel are your personal and scholastic qualifications for the study of medicine?","limit":500,"unit":"words","fam":"other"},{"p":"How do you feel you will contribute to the success of the FSU College of Medicine and our unique mission?","limit":500,"unit":"words","fam":"why"},{"p":"If you are planning to take a gap year, are currently in a gap year, or have taken time off between college and medical school, please describe how you have spent (or are spending) this time. If you are have applied previously, we ask that you describe any specific steps you have taken to strengthen your application.","limit":500,"unit":"words","fam":"gap"},{"p":"Medical school requires significant personal commitment, including long hours, emotional challenges, and limited personal time. How have you prepared for these demands, and what strategies will you use to maintain a healthy work-life balance during your training? Please also share how your personal support system—family, friends, mentors, or others—will help you during this journey","limit":500,"unit":"words","fam":"other"},{"p":"In what field/specialty of medicine do you envision yourself working ten years from now? Please LIST no more than three (3) specialties. Please do not include a narrative; simply list the specialties.","limit":0,"unit":"words","fam":"career"},{"p":"Write a short statement explaining how you envision using the specialty or specialties you listed above to advance the mission of the FSU College of Medicine. Please describe the patient population or community you are most passionate about serving and how your goals align with the College's commitment to underserved and rural populations.","limit":0,"unit":"words","fam":"career"},{"p":"The FSU College of Medicine has 6 regional campus locations and 2 rural training sites across the state of Florida, serving multifaceted populations. Describe a time when you engaged with people from backgrounds different from your own. What did you learn from that experience, and how has it influenced the way you interact with populations that have differing values, customs, and life histories?","limit":0,"unit":"words","fam":"diversity","opt":1},{"p":"Please describe a community service experience, outside of direct patient care, in which you served an underserved or marginalized population. What drew you to this experience, and how did it contribute to your personal growth and learning? What aspects of your involvement did you find most meaningful or fulfilling?","limit":0,"unit":"words","fam":"service","opt":1}]},{"name":"Frist College of Medicine at Belmont University","state":"TN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-frist-college-of-medicine-at-belmont-university.1517713/","prompts":[{"p":"At FCoM, our mission, vision, and values shape our purpose, set our aspirations, and inform our decisions. Please select which value you find most energizing and why. Discuss how this value has impacted your life.","limit":2000,"unit":"chars","fam":"why"},{"p":"Our curriculum centers around a whole-person approach to healing in a community of service learning, inspired by the love and grace of Christ. Discuss how your spiritual experiences, faith, or personal beliefs have influenced your life and your decision to pursue medicine as a career.","limit":2000,"unit":"chars","fam":"other"},{"p":"As a newer medical school, our students will help shape a new culture and build lasting community. Reflect on a time when you embraced ambiguity, sharing specific examples where you contributed to creating a culture of growth, collaboration, and adaptability.","limit":2000,"unit":"chars","fam":"team"},{"p":"Reapplicants only – Describe the changes to your application from previous cycles - include developments to your academics, experiences, and/or personal attributes. You are welcome to submit this essay if you consider yourself a medical school reapplicant.","limit":2000,"unit":"chars","fam":"other","opt":1}]},{"name":"Geisinger Commonwealth School of Medicine","state":"PA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-geisinger-commonwealth-school-of-medicine.1520397/","prompts":[{"p":"Do you plan to apply for the Abigail Geisinger Scholars Program? (Y/N). Abigail Geisinger Scholars If yes, which specialty are you interested in? Please share with the Admissions Committee what primary care means to you, and why you believe you are a good fit for the Abigail Geisinger Scholars Program. If no, Given Geisinger Commonwealth School of Medicine’s unique mission and values, please tell us why you believe you are a good fit for our institution.","limit":1500,"unit":"chars","fam":"why"},{"p":"List the five most important attributes you believe a physician should possess. Please choose one that you believe you embody and describe a personal experience that demonstrates this trait.","limit":1500,"unit":"chars","fam":"other"},{"p":"GCSOM prioritizes the delivery of evidence-based medicine through compassionate and culturally humble care for all patients, particularly for the communities of Northeast and Central Pennsylvania. How will you contribute to these priorities?","limit":1500,"unit":"chars","fam":"service"},{"p":"If you have previously applied to medical school, please describe your significant experiences between this year’s application and your previous application. If you are not a previous applicant, please type, “N/A” in the response area.","limit":1500,"unit":"chars","fam":"gap"}]},{"name":"George Washington University School of Medicine","state":"DC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-george-washington-university-school-of-medicine.1517714/","prompts":[{"p":"If you selected regional medical campus preferred or regional medical campus only in question 6, please explain in detail your interest in regional medical campus and how it will be a good fit for your clinical education.","limit":1750,"unit":"chars","fam":"why"},{"p":"Please provide the Admissions Committee with a brief summary of your activities, academics, employment, or other occupations to account for full-time activity (approx. 30-40 hours/week) from the point of application through matriculation in 2027.","limit":750,"unit":"chars","fam":"gap"},{"p":"The MD Program includes substantial content in Clinical Public Health (population health, health systems science, health policy, and community health) to prepare GW graduates for an expanded scope of practice required to be successful 21st century physicians. What are your specific interests and experiences related to that aspect of the MD Program?","limit":350,"unit":"chars","fam":"career"},{"p":"What makes you a unique individual? What challenges have you faced? What have you learned from your experiences?","limit":750,"unit":"chars","fam":"diversity"},{"p":"What is your specific interest in the MD Program at GW? What opportunities would you take advantage of as a student here? Why?","limit":1750,"unit":"chars","fam":"why"},{"p":"Have you previously interacted directly with the MD Admissions Office through events, tours, fairs, webinars, or interviews? If yes, please explain","limit":250,"unit":"chars","fam":"other"}]},{"name":"Georgetown University School of Medicine","state":"DC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-georgetown-university-school-of-medicine.1517715/","prompts":[{"p":"The Georgetown University School of Medicine (GUSOM) strives to ensure that its students become respectful physicians, with cultural humility, who embrace all dimensions of caring for the whole person. With our Jesuit values of Cura Personalis, being Men and Women for Others, and Unity in Community, we are steadfast in our commitment to provide care for all. Please describe how your perspectives, values, and individual life experiences will contribute to these GUSOM priorities.","limit":1000,"unit":"chars","fam":"diversity"},{"p":"Is there any further information that you would like the Committee on Admissions to be aware of when reviewing your file that you were not able to notate in another section of this or the AMCAS Application?","limit":1000,"unit":"chars","fam":"anything"},{"p":"Why have you chosen to apply to the Georgetown University School of Medicine and how do you think your education at Georgetown will prepare you to become a physician for the future?","limit":3000,"unit":"chars","fam":"why"}]},{"name":"Hackensack Meridian School of Medicine","state":"NJ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-hackensack-meridian-school-of-medicine.1517716/","prompts":[{"p":"Why are you interested in attending the Hackensack Meridian School of Medicine?","limit":500,"unit":"words","fam":"why"},{"p":"Describe a time when you engaged with a perspective, culture, or experience different from your own. What did you learn, and how did it influence your personal or professional development?","limit":500,"unit":"words","fam":"diversity"},{"p":"Describe your experience with the field of medicine (or a related field) that has prepared you for advanced study in this area. Specifically, how have your life experiences prepared you to pursue a degree in medicine, including: coursework, clinical work, experiences in overcoming adversity, work opportunity, volunteer activities, and/or research experiences?","limit":500,"unit":"words","fam":"other"}]},{"name":"Harvard Medical School","state":"MA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-harvard-medical-school.1517717/","prompts":[{"p":"If you have already graduated, briefly (4000 characters maximum) summarize your activities since graduation.","limit":4000,"unit":"chars","fam":"gap","group":"Conditional: graduates only"},{"p":"If there is an important aspect of your experience not addressed elsewhere in the application that may illuminate how you could contribute to the medical school and that you would like to share with the Committee, we invite you to do so here. Examples might include significant challenges in access to education, unusual socioeconomic factors, ideological perspectives, or other experiences that help place your prior academic achievements in context or provide further insight into your motivation for a career in medicine or the perspective you might bring to the medical school community.","limit":0,"unit":"words","fam":"diversity"},{"p":"The HST MD program draws on the combined resources of Harvard and MIT to provide a distinct preclinical education tailored to preparing students for careers as transformative physicians who will shape the future practice of medicine. Our students come from the full spectrum of disciplines including biological, physical, engineering and social sciences. HST classes are small, commonly include graduate students and have an emphasis on quantitative and analytic approaches. The unique HST pre-clinical curriculum prepares students well for the HMS clinical education while also emphasizing disease mechanisms and preparing students to solve critical unmet needs in medicine and healthcare (ranging from novel diagnostics and therapeutics to applications of ‘big data’ and systems engineering). Please focus on how your interests, experiences and aspirations have prepared you for HST (rather than identifying specific HST faculty or research opportunities).","limit":4000,"unit":"chars","fam":"why","group":"Conditional: HST applicants only"}]},{"name":"Howard University College of Medicine","state":"DC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-howard-university-college-of-medicine.1517718/","prompts":[{"p":"What were your SAT and/or ACT scores? (Please respond providing your total score on the 400-1600 scale or the 200-800 scale depending on whether you took the old SATs versus the new SATs AND/OR the ACT Composite score on a 1-36 scale) Please indicate below or type N/A if you did not take either.","limit":0,"unit":"words","fam":"other"},{"p":"Have you lived in communities which are medically underserved, or where the majority of the population is economically and/or educationally disadvantaged? (Please indicate, Yes or No and then explain/describe briefly in 250 words or less)","limit":250,"unit":"words","fam":"diversity"},{"p":"Have you worked (volunteer or paid employment) with medically underserved, economically disadvantaged and/or educationally disadvantaged populations? (Please indicate, Yes or No and then explain/describe briefly in 250 words or less)","limit":250,"unit":"words","fam":"service"},{"p":"After residency, do you plan to practice medicine in an underserved or disadvantaged community? (Please indicate, Yes or No and then explain/describe briefly in 250 words or less)","limit":250,"unit":"words","fam":"career"},{"p":"Please provide below any additional information you believe is important in evaluating your application (e.g. additional coursework, problems with academic record; disadvantaged, etc.) (Please indicate, Yes or No and then explain/describe briefly in 250 words or less)","limit":250,"unit":"words","fam":"anything"},{"p":"Did you work at least 20 hours a week for at least one academic year during your undergraduate/graduate program? (Y/N) - no explanation.","limit":0,"unit":"words","fam":"other"},{"p":"Did COVID-19 impact you preparing your AMCAS application for fall 2027? (i.e. volunteer/work experience, financially, course registration, MCAT testing, etc.) [Please respond Yes or No and then explain/describe briefly in 250 words or less, indicate N/A if not applicable]","limit":250,"unit":"words","fam":"challenge"},{"p":"Why Howard University College of Medicine?","limit":2500,"unit":"chars","fam":"why"}]},{"name":"Icahn School of Medicine at Mount Sinai","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-icahn-school-of-medicine-at-mount-sinai.1517720/","prompts":[{"p":"If you are currently not a full-time student, please briefly describe the activities you are participating in this academic year.","limit":100,"unit":"words","fam":"gap"},{"p":"If you are committed to a particular community or if there is an important aspect of your background not addressed elsewhere in the application, we invite you to do so here. Briefly explain how such factors have influenced your motivation for a career in medicine.","limit":150,"unit":"words","fam":"diversity","opt":1},{"p":"What is the toughest feedback you ever received? How did you handle it, and what did you learn from it?","limit":250,"unit":"words","fam":"challenge"},{"p":"Describe a situation that you have thought to be unfair or unjust, whether towards yourself or others. How did you address the situation, if at all?","limit":250,"unit":"words","fam":"ethics"},{"p":"Were there any adverse circumstances in your premedical preparatory journey?","limit":100,"unit":"words","fam":"challenge","opt":1},{"p":"Are there significant gaps in time that are unaccounted for in your application? Yes/No If yes, please explain (100 word text box)","limit":100,"unit":"words","fam":"gap","opt":1}]},{"name":"Idaho College of Osteopathic Medicine (ICOM)","state":"ID","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-idaho-college-of-osteopathic-medicine-icom.1518421/","prompts":[],"none":"No written essays reported"},{"name":"Illinois College of Osteopathic Medicine (ILCOM)","state":"IL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-illinois-college-of-osteopathic-medicine-ilcom.1518428/","prompts":[],"none":"No prompts posted yet"},{"name":"Indiana University of Pennsylvania College of Osteopathic Medicine (IUPCOM)","state":"PA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-indiana-university-of-pennsylvania-college-of-osteopathic-medicine-iup-com.1520612/","prompts":[{"p":"What motivates your interest in pursuing medicine in rural or underserved communities, particularly in Pennsylvania?","limit":250,"unit":"words","fam":"service"},{"p":"Describe a challenge you have faced and explain how it has shaped qualities or skills that will help you succeed as a future physician.","limit":0,"unit":"words","fam":"challenge"},{"p":"What do you see as one significant healthcare challenge facing rural communities today, and how do you think physicians can help address it?","limit":0,"unit":"words","fam":"service"},{"p":"How would you approach building trust and effective partnerships within a close-knit community that may be hesitant to seek medical care?","limit":0,"unit":"words","fam":"service"},{"p":"How would training in a medical program focused on rural and underserved communities support your long-term personal and professional goals?","limit":0,"unit":"words","fam":"career"}]},{"name":"Indiana University School of Medicine","state":"IN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-indiana-university-school-of-medicine.1517721/","prompts":[],"none":"No written essays reported"},{"name":"Johns Hopkins University School of Medicine","state":"MD","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-johns-hopkins-university-school-of-medicine.1517722/","prompts":[{"p":"Briefly describe a specific challenge you faced and how you overcame it. What was your approach, what did you learn from the process, and how do you see those skills translating to a career in medicine?","limit":250,"unit":"words","fam":"challenge"},{"p":"Describe an interaction that required you to understand or engage with a perspective different from your own. How did you respond and what was the outcome?","limit":250,"unit":"words","fam":"diversity"},{"p":"Please review the Johns Hopkins Medicine Website. Is there an area of medicine or a particular medical specialty at Johns Hopkins that interests you and why?","limit":250,"unit":"words","fam":"career"},{"p":"Every future physician has a story. What's yours? Share the experience, insight, or connection that first made you see yourself in medicine—and how it continues to shape your path.","limit":300,"unit":"words","fam":"other"},{"p":"What draws you to Johns Hopkins School of Medicine? Reflect on how our mission, culture, and academic community align with your values, experiences, and aspirations as a future physician. In your response, please highlight specific aspects of both the Hopkins community (academic, research, and/or extracurricular opportunities) and the Baltimore community, particularly the patients and families that we serve. Elaborate on how you intend to actively engage with and contribute to both of these communities as you pursue your medical education.","limit":300,"unit":"words","fam":"why"},{"p":"Would you like to share any additional information with the Admissions Committee about yourself that cannot be found elsewhere in your application? This space can also address any extenuating circumstances (e.g., unexplained gaps in work experience, choice of recommenders, inconsistent or questionable academic performance, areas of weakness, etc.) that you would like the Admissions Committee to consider.","limit":300,"unit":"words","fam":"anything","opt":1},{"p":"Please describe what you have been doing since graduation and your plans for the upcoming year","limit":300,"unit":"words","fam":"gap"}]},{"name":"Kaiser Permanente Tyson School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-kaiser-permanente-tyson-school-of-medicine.1517723/","prompts":[{"p":"During your career as a physician, you will likely encounter obstacles, and be required to overcome challenges. Please describe your experience with a situation that had an unfavorable outcome, including your reaction, how you might have responded differently, and what you learned about yourself.","limit":250,"unit":"words","fam":"challenge"},{"p":"Kaiser Permanente Bernard J. Tyson School of Medicine is dedicated to graduating courageous leaders who lead change through inquiry and innovation in medical education, the profession, and the healthcare system. How do your values align with this mission?","limit":250,"unit":"words","fam":"why"},{"p":"Lifelong learning is an essential process for continued professional development. This includes reflection and being open and responsive to constructive feedback. Please tell us about an area of intellectual exploration you’re passionate about, and your approach to exploring this area.","limit":250,"unit":"words","fam":"other"},{"p":"Drawing from your lived experiences, how do you think knowledge of the social drivers of health can be leveraged to engage in community health advocacy?","limit":250,"unit":"words","fam":"service"},{"p":"Have you previously applied to medical school? If yes, please describe your accomplishments since you last applied that would promote your acceptance?","limit":250,"unit":"words","fam":"other","opt":1},{"p":"Which components of your application best demonstrate your alignment with KPSOM's mission?","limit":0,"unit":"words","fam":"why"}]},{"name":"Kansas City University College of Osteopathic Medicine (KCU-Kansas-City)","state":"MO","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-kansas-city-university-college-of-osteopathic-medicine-kcu-kansas-city.1518429/","prompts":[{"p":"Reflecting on your past experiences, how have you successfully navigated challenging academic or personal situations, and how will those strategies help you maintain confidence and success in medical school?","limit":0,"unit":"words","fam":"challenge"},{"p":"Reflect on a time when you identified someone in need and took action to support them. What did you observe that made you realize they needed help, and how did you provide that support? What was the outcome, and what did you learn from the experience?","limit":0,"unit":"words","fam":"service"},{"p":"Can you describe a clinical experience that deeply impacted you? What were the key takeaways, both personally and clinically? Please be specific in your response.","limit":0,"unit":"words","fam":"other"}]},{"name":"Kansas City University College of Osteopathic Medicine - Joplin (KCU-Joplin)","state":"MO","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-kansas-city-university-college-of-osteopathic-medicine-joplin-kcu-joplin.1518430/","prompts":[],"none":"No prompts posted yet"},{"name":"Kansas Health Science University - Kansas College of Osteopathic Medicine (KansasCOM)","state":"KS","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-kansas-health-science-university-kansas-college-of-osteopathic-medicine-kansascom.1518431/","prompts":[],"none":"No prompts posted yet"},{"name":"Kirk Kerkorian School of Medicine at UNLV","state":"NV","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-nevada-las-vegas.1517835/","prompts":[],"none":"No prompts posted yet"},{"name":"Lake Erie College of Osteopathic Medicine (LECOM)","state":"PA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-lake-erie-college-of-osteopathic-medicine-lecom.1518432/","prompts":[],"none":"No written essays reported"},{"name":"Lake Erie College of Osteopathic Medicine - Elmira (LECOM-Elmira)","state":"NY","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-lake-erie-college-of-osteopathic-medicine-elmira-lecom-elmira.1518433/","prompts":[],"none":"No prompts posted yet"},{"name":"Lake Erie College of Osteopathic Medicine - Seton Hill (LECOM-Seton-Hill)","state":"PA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-lake-erie-college-of-osteopathic-medicine-seton-hill-lecom-seton-hill.1518441/","prompts":[],"none":"No prompts posted yet"},{"name":"Lake Erie College of Osteopathic Medicine Bradenton Campus (LECOM-Bradenton)","state":"FL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-lake-erie-college-of-osteopathic-medicine-bradenton-campus-lecom-bradenton.1518442/","prompts":[],"none":"No prompts posted yet"},{"name":"Liberty University College of Osteopathic Medicine (LUCOM)","state":"VA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-liberty-university-college-of-osteopathic-medicine-lucom.1518443/","prompts":[],"none":"No written essays reported"},{"name":"Lincoln Memorial University - DeBusk College of Osteopathic Medicine (LMU-DCOM)","state":"TN","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-lincoln-memorial-university-debusk-college-of-osteopathic-medicine-lmu-dcom.1518444/","prompts":[],"none":"No prompts posted yet"},{"name":"Lincoln Memorial University - Debusk College of Osteopathic Medicine - Knoxville (LMU-DCOM-Knoxville)","state":"TN","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-lincoln-memorial-university-debusk-college-of-osteopathic-medicine-knoxville-lmu-dcom-knoxville.1518445/","prompts":[],"none":"No prompts posted yet"},{"name":"Loma Linda University School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-loma-linda-university-school-of-medicine.1517724/","prompts":[{"p":"What makes LLUSM particularly attractive to you?","limit":275,"unit":"words","fam":"why"},{"p":"Our medical curriculum integrates spiritual, ethical, and relational issues from the Christian perspective into the practice of medicine. Religion courses and weekly chapel services are part of this program. Please respond to the preceding statements as they relate to your personal educational and career goals.","limit":275,"unit":"words","fam":"why"},{"p":"What personal attributes make you a desirable candidate for admission to LLUSM?","limit":275,"unit":"words","fam":"diversity"},{"p":"Identify experiences in your life that illustrate your service to others.","limit":275,"unit":"words","fam":"service"},{"p":"Discuss how your spiritual origins, development, and experiences have influenced and been integrated into your daily life.","limit":275,"unit":"words","fam":"other"},{"p":"Please describe your current involvement (or reason for not being involved) with a church or religious group.","limit":275,"unit":"words","fam":"other"},{"p":"If you have already graduated, briefly describe your activities since graduation and your planned activities prior to matriculation into medical school.","limit":275,"unit":"words","fam":"gap"}]},{"name":"Loyola University Chicago Stritch School of Medicine","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-loyola-university-chicago-stritch-school-of-medicine.1517727/","prompts":[{"p":"As you consider Loyola University Chicago Stritch School of Medicine, please tell us what resonates with you regarding our mission as a Jesuit, Catholic medical school? Consider also what you may be curious about regarding our institutional mission and identity.","limit":500,"unit":"words","fam":"why"},{"p":"Considering all that you could do with your life, how have you discerned your decision to become a physician? What is particular to the practice of medicine and the vocation of a physician that draws you to apply to medical school versus another helping/caring profession? What experiences, conversations, and encounters have informed your decision to apply?","limit":500,"unit":"words","fam":"other"},{"p":"Social justice, in the Jesuit tradition, justice due to each person's inherent human dignity, is an essential dimension of education at SSOM. Describe an impactful experience working with and for under-resourced communities. Explain what you have learned about yourself through this service and/or what has hindered your efforts to serve others in these environments.","limit":500,"unit":"words","fam":"service"},{"p":"Describe a time you received feedback about your performance and disagreed with the feedback. What did you disagree with? How did you handle it?","limit":500,"unit":"words","fam":"team"},{"p":"Medical education is characterized by long hours of study, a steady cadence of course exams, subjective and objective assessment of performance, licensing exams, and sometimes demanding and stressful educational contexts in the clinical environment. How has your chosen undergraduate course of study prepared you for the rigor and demands of the medical school curriculum? What additional skills have you learned as a pre-med student to help you balance your educational and personal responsibilities, including managing your time and relieving stress?","limit":500,"unit":"words","fam":"other"},{"p":"Please indicate additional grades earned, amendments to your proposed coursework or graduation date, address changes, additions to your list of experiences, and anything else you feel we should know.","limit":0,"unit":"words","fam":"anything","opt":1},{"p":"Please explain in more detail (in less than 1500 characters) anything that would help us understand any gaps or delays in your education, academic missteps, or personal challenges not listed elsewhere.","limit":1500,"unit":"chars","fam":"challenge","opt":1},{"p":"If you have not been enrolled in coursework for over two years, please let us know what you have been doing since your coursework ended.","limit":0,"unit":"words","fam":"gap","opt":1},{"p":"Have you applied to SSOM prior to this application? If so, please list the years of your previous application submissions to SSOM and tell us how your application has improved since your previous submission.","limit":0,"unit":"words","fam":"other","opt":1},{"p":"If you did not submit an advisor or committee letter, please tell us why.","limit":0,"unit":"words","fam":"other","opt":1}]},{"name":"LSU Health New Orleans School of Medicine","state":"LA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-lsu-new-orleans.1517725/","prompts":[],"none":"No prompts posted yet"},{"name":"LSU Health Shreveport School of Medicine","state":"LA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-lsu-shreveport.1517726/","prompts":[{"p":"PLEASE ANSWER THIS QUESTION ONLY IF YOU ARE A RE-APPLICANT TO LSU HEALTH SHREVEPORT. Since your previous medical school application, what academic, employment, volunteer experiences or other progress have you made that make you a more competitive applicant?","limit":2000,"unit":"chars","fam":"other","opt":1}]},{"name":"Marian University Tom and Julie Wood College of Osteopathic Medicine (MU-WCOM)","state":"IN","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-marian-university-tom-and-julie-wood-college-of-osteopathic-medicine-mu-wcom.1518446/","prompts":[{"p":"In Indiana, 53 of our 92 counties are designated as Health Professional Shortage Areas. What experiences have you had working with these types of communities, and how has it shaped your perspective on healthcare?","limit":300,"unit":"words","fam":"service"},{"p":"What personal experiences or values have motivated you into considering an osteopathic medical education?","limit":300,"unit":"words","fam":"osteo"},{"p":"Explain your interest in attending MU-WCOM","limit":300,"unit":"words","fam":"why"},{"p":"Please indicate any new information, changes or additions that were not included in your AACOMAS application (including but not limited to, education, employment, extracurricular activities, research, military service, academic warnings, conduct violations, and/or convictions).","limit":300,"unit":"words","fam":"anything"}]},{"name":"Marshall University Joan C. Edwards School of Medicine","state":"WV","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-marshall-university.1517728/","prompts":[{"p":"How is your goal of becoming a physician aligning with the mission and values of JCESOM?","limit":5000,"unit":"chars","fam":"why"}]},{"name":"Mayo Clinic Alix School of Medicine, Arizona","state":"AZ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-mayo-clinic-arizona.1517730/","prompts":[],"none":"No prompts posted yet"},{"name":"Mayo Clinic Alix School of Medicine, Minnesota","state":"MN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-mayo-clinic-alix-minnesota.1517729/","prompts":[{"p":"At Mayo Clinic Alix School of Medicine, we seek students whose values align with our mission to put the needs of the patient first. Please share why you would like to study medicine at our school, including specifically why at the top campus track you selected.","limit":500,"unit":"words","fam":"why"},{"p":"Reflect on how your professional and lived experiences have shaped your identity. Tell us how these experiences will help you contribute to a collaborative learning environment, support your patients and colleagues, and advance Mayo Clinic’s commitment to excellence.","limit":500,"unit":"words","fam":"diversity"},{"p":"Mayo Clinic’s Bold. Forward. strategy integrates digital innovation with a deeply humanistic approach to transform healthcare. What role do you see yourself playing in shaping this future? Describe the skills, experiences, or aspirations in artificial intelligence and innovation that prepare you to contribute meaningfully to this transformation.","limit":500,"unit":"words","fam":"career"},{"p":"In the space below, write a brief paragraph (max. 500 characters) explaining why you are specifically applying to the Mayo Clinic M.D.-Ph.D. Program.","limit":500,"unit":"chars","fam":"why","group":"Conditional: MD-PhD (MSTP) applicants only"}]},{"name":"McGovern Medical School at UTHealth Houston","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-mcgovern-medical-school-at-ut-health-houston.1517858/","prompts":[{"p":"Why do you feel that McGovern Medical School is the best fit for your medical education? In what way do you see yourself adding to the McGovern community?","limit":1000,"unit":"chars","fam":"why"},{"p":"Describe the most significant experience that has prepared you thus far for life in medical school.","limit":1000,"unit":"chars","fam":"other"},{"p":"Describe a time or situation where you have been unsuccessful or failed. What did you learn from this experience and how have you applied this learning to your work and/or life?","limit":1000,"unit":"chars","fam":"challenge"},{"p":"What’s one thing a mentor taught you that you still appreciate today?","limit":1000,"unit":"chars","fam":"other"},{"p":"Why would our MD/PhD program be a good fit for your goals?","limit":1000,"unit":"chars","fam":"why"}]},{"name":"Medical College of Georgia at Augusta University","state":"GA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-medical-college-of-georgia-at-augusta-university.1517732/","prompts":[],"none":"No prompts posted yet"},{"name":"Medical College of Wisconsin","state":"WI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-medical-college-of-wisconsin.1517733/","prompts":[{"p":"At MCW, we are guided by the values of acting in caring ways, engaging in collaborative efforts, approaching our world with curiosity, advancing inclusive practices, demonstrating integrity in all that we do, and treating everyone with respect. Describe how your unique experiences, interests, and talents have embodied one or more of these values, and how they will shape the way you plan to contribute to the MCW learning community.","limit":1000,"unit":"chars","fam":"diversity"},{"p":"How will MCW uniquely prepare you for your future goals?","limit":1000,"unit":"chars","fam":"why"},{"p":"Recount a time when you made a decision you regret. How did it affect you, and what did you learn from the experience?","limit":2000,"unit":"chars","fam":"challenge"},{"p":"MCW is committed to its missions of community engagement and improving health for all. MCW medical students play an important role in advancing these missions by working with and within various communities throughout Wisconsin which requires adaptability and a willingness to learn from new experiences. Describe a time where you entered a new environment or situation, how you adapted, what you learned, and how that experience helped you grow in your ability to serve others and contribute to MCW’s missions during your education.","limit":2000,"unit":"chars","fam":"service"},{"p":"Please explain how your application has changed since your last application to MCW Medical School. How have you enhanced your preparation for medical school and future career as a physician (e.g., additional academic work, employment, volunteer experience, etc.)? You may wish to elaborate on the process you employed to critique your application’s strengths and weaknesses or share life changes or circumstances that have impacted your application.","limit":2000,"unit":"chars","fam":"other","group":"Conditional: required of reapplicants to MCW"},{"p":"Describe the experiences that have contributed to your motivation to pursue a primary care focused, community-based medical education program.","limit":2000,"unit":"chars","fam":"career","group":"Conditional: required of MCW-Central Wisconsin and/or MCW-Green Bay applicants"},{"p":"Describe the community in which you envision yourself living and practicing medicine. Address the benefits and challenges of life in your specified community.","limit":2000,"unit":"chars","fam":"career","group":"Conditional: required of MCW-Central Wisconsin and/or MCW-Green Bay applicants"}]},{"name":"Medical University of South Carolina","state":"SC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-medical-university-of-south-carolina.1517734/","prompts":[],"none":"No prompts posted yet"},{"name":"Meharry Medical College","state":"TN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-meharry-medical-college.1517735/","prompts":[{"p":"Statement of Purpose: Why do you wish to attend Meharry Medical College, School of Medicine?","limit":0,"unit":"words","fam":"why"},{"p":"Statement of Resilience: Please describe a personal situation of failure, significant challenge, or a major obstacle that you have overcome. Include a description of your coping skills and lessons you learned about yourself from that situation.","limit":0,"unit":"words","fam":"challenge"}]},{"name":"Mercer University School of Medicine","state":"GA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-mercer-university-school-of-medicine.1517736/post-25127474","prompts":[{"p":"Summarize your work and learning experiences that reflect congruence with our mission.","limit":0,"unit":"words","fam":"why"},{"p":"Based on your understanding of our mission, where and what do you envision yourself doing after completion of medical school and residency, and how does this address the critical need for primary health providers in Georgia?","limit":0,"unit":"words","fam":"career"},{"p":"Describe your body of work in service to the underserved and reflect on its importance in preparing you for the practice medicine.","limit":0,"unit":"words","fam":"service"},{"p":"Describe your personal experience with rural medicine.","limit":0,"unit":"words","fam":"service"},{"p":"Explain to the Admissions Committee experiences, attributes, or qualifications you believe are unique to you that will strengthen the educational environment at MUSM.","limit":0,"unit":"words","fam":"diversity"},{"p":"Discuss your academic readiness for the rigors of our medical school curriculum. If necessary, explain how you overcame academic difficulties.","limit":0,"unit":"words","fam":"challenge"},{"p":"Address any institutional action, including honor code or conduct code violations, from your time as an undergraduate or graduate student. Applicants may answer 'None' to this question if the action was deleted, expunged, or otherwise removed from their record by the institution.","limit":0,"unit":"words","fam":"other"},{"p":"Highlight any substantial updates to your application (e.g., volunteer experiences) that have occurred after you submitted your primary AMCAS Application.","limit":0,"unit":"words","fam":"anything"},{"p":"Highlight any experiences or attributes not covered above that would help the Admissions Committee better understand how your distance traveled to medical school and will contribute to our program or the practice of medicine in Georgia.","limit":0,"unit":"words","fam":"diversity"}]},{"name":"Meritus School of Osteopathic Medicine (MSOM)","state":"MD","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-meritus-school-of-osteopathic-medicine-msom.1518447/","prompts":[{"p":"How do your values align with MSOM’s mission of preparing physicians to be socially responsible and community-oriented?","limit":750,"unit":"chars","fam":"why"},{"p":"Have you previously applied to MSOM? If yes, please describe how your application has changed or improved since your last submission.","limit":750,"unit":"chars","fam":"other"},{"p":"If you experienced a period of notable academic distress or a gap in your education (such as multiple course failures or complete withdrawal), please explain.","limit":750,"unit":"chars","fam":"other"}]},{"name":"Methodist University Cape Fear Valley Health School of Medicine","state":"NC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-methodist-university-cape-fear-valley-health-school-of-medicine.1517737/","prompts":[{"p":"Describe a time you served a community in need. What impact did it have on you and others?","limit":200,"unit":"words","fam":"service"},{"p":"Discuss a health disparity you are passionate about addressing. What steps would you take as a medical student and future physician to make progress on this issue?","limit":200,"unit":"words","fam":"career"},{"p":"What is something you want to share with us that is not reflected on your application?","limit":200,"unit":"words","fam":"anything"},{"p":"(Optional) Please describe any connection you have to North Carolina or to the Southeastern NC region.","limit":150,"unit":"words","fam":"why","opt":1}]},{"name":"Michigan State University College of Human Medicine","state":"MI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-michigan-state-university-college-of-human-medicine.1517738/","prompts":[{"p":"How have your most meaningful experiences shaped what you envision doing in medicine 15 years from now? Describe one specific future accomplishment that would define your career’s success up to that point in time.","limit":400,"unit":"words","fam":"career"},{"p":"How have your personal experiences with, or observations of, systemic inequities shaped your perspective? Moving beyond generalities, describe how this perspective will uniquely influence your approach to patient care and your role in addressing health disparities as a future physician.","limit":400,"unit":"words","fam":"diversity"},{"p":"Each year, we review thousands of applications. Beyond what is in your primary application, what do you want the Admissions Committee to know about you as it relates to your fit for MSU CHM’s community-based mission? If you are an out-of-state applicant, we encourage you to address your interest in training and potentially practicing in Michigan.","limit":400,"unit":"words","fam":"why"}]},{"name":"Michigan State University College of Osteopathic Medicine (MSUCOM)","state":"MI","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-michigan-state-university-college-of-osteopathic-medicine-msucom.1518448/","prompts":[{"p":"The MSUCOM curriculum stresses the importance of intrapersonal competencies, including personal responsibility and adaptability. Please tell us a time when you were faced with a challenge in these areas and how that challenge impacted your professional growth.","limit":0,"unit":"words","fam":"challenge"},{"p":"Tell us about a time you stumbled in a professional setting and how you moved forward from the experience.","limit":0,"unit":"words","fam":"challenge"}]},{"name":"Michigan State University College of Osteopathic Medicine - Clinton Township (MSUCOM-Clinton-Township)","state":"MI","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-michigan-state-university-college-of-osteopathic-medicine-clinton-township-msucom-clinton-township.1518449/","prompts":[],"none":"No prompts posted yet"},{"name":"Michigan State University College of Osteopathic Medicine - Detroit (MSUCOM-Detroit)","state":"MI","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-michigan-state-university-college-of-osteopathic-medicine-detroit-msucom-detroit.1518450/","prompts":[],"none":"No prompts posted yet"},{"name":"Morehouse School of Medicine","state":"GA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-morehouse-school-of-medicine.1517739/","prompts":[{"p":"Give an example when you have shown resilience and how you would overcome academic adversity if encountered in medical school.","limit":200,"unit":"words","fam":"challenge"},{"p":"In what ways do you plan to contribute to the Morehouse School of Medicine community, both during your time as a student and beyond?","limit":200,"unit":"words","fam":"diversity"},{"p":"Imagine you’re a healthcare provider working at a community clinic with limited resources. You’re responsible for distributing a small number of free glucose monitors to patients with diabetes. You have two patients who qualify: one is highly engaged, follows care instructions, and has shown consistent improvement. The other struggles with managing their condition due to low literacy, language barriers, and unstable housing, and often misses appointments. You only have one monitor left. Who do you give it to—and why? How would you navigate this situation in a way that reflects a commitment to health equity?","limit":200,"unit":"words","fam":"ethics"}]},{"name":"New York Institute of Technology College of Osteopathic Medicine - NY (NYITCOM-Long-Island)","state":"NY","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-new-york-institute-of-technology-college-of-osteopathic-medicine-ny-nyitcom-long-island.1518477/","prompts":[],"none":"No prompts posted yet"},{"name":"New York Institute of Technology College of Osteopathic Medicine at Arkansas State University (NYITCOM-at-Arkansas)","state":"AR","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-new-york-institute-of-technology-college-of-osteopathic-medicine-at-arkansas-state-university-nyitcom-at-arkansas.1518478/","prompts":[],"none":"No written essays reported"},{"name":"New York Medical College","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-new-york-medical-college.1517740/","prompts":[],"none":"No prompts posted yet"},{"name":"Noorda College of Osteopathic Medicine (Noorda-COM)","state":"UT","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-noorda-college-of-osteopathic-medicine-noorda-com.1518479/","prompts":[],"none":"No written essays reported"},{"name":"Northeast Ohio Medical University","state":"OH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-northeast-ohio-medical-university-neomed.1517741/","prompts":[{"p":"Please complete a brief personal statement of 5,000 characters or fewer addressing the question: What do you hope to achieve from your experience as a NEOMED student?","limit":5000,"unit":"chars","fam":"why"},{"p":"Please complete a brief personal statement of 5,000 characters or fewer addressing the question below: What motivates you to apply to NEOMED using the (binding) early decision plan? In other words, what motivates you to select NEOMED as the only allopathic medical school you may attend if you are offered admission under the early decision program?","limit":5000,"unit":"chars","fam":"why"}]},{"name":"Northwestern University Feinberg School of Medicine","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-northwestern-university-feinberg-school-of-medicine.1517743/","prompts":[{"p":"Feinberg’s mission is to train future leaders who will serve their patients, communities and society. Explain which aspects of Feinberg will support your future goals in medicine and how FSM, located in Chicago, will help you achieve these professional aspirations.","limit":200,"unit":"words","fam":"why"},{"p":"Describe a favorite book, movie, album, or other work of art you would like to share with your future classmates and why.","limit":200,"unit":"words","fam":"other"},{"p":"If you have one year or more between college graduation and medical school matriculation, describe both your completed activities and anticipated plans, including the extent of your involvement.","limit":200,"unit":"words","fam":"gap","opt":1},{"p":"If you are reapplying to medical school, please address steps taken to enhance your application.","limit":200,"unit":"words","fam":"other","opt":1},{"p":"The Feinberg School of Medicine values the totality of our students’ experiences. As everyone has their own narrative, please describe how your experiences have shaped your interests, preparation for medicine, or perspective on patient care, and how they may contribute to your development with the Northwestern community.","limit":200,"unit":"words","fam":"diversity"}]},{"name":"Nova Southeastern Patel College of Allopathic Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-nova-southeastern-school-of-allopathic-medicine.1517742/","prompts":[{"p":"Please provide an example that indicates your ability to function effectively as a productive member of a team working toward a common objective. Elaborate on leadership roles you held in this capacity and how you solved problems that arose. Indicate highlights learned from this experience.","limit":4000,"unit":"chars","fam":"team"},{"p":"Please share some personal examples of problem solving in a team environment and/or leadership experience that would lead to your success in a Problem Based Learning environment.","limit":4000,"unit":"chars","fam":"team"},{"p":"At the NSU MD program, we value the unique perspective that each applicant brings. Identify any traits, life experiences, or interests that a professor or advisor would not normally know about you.","limit":4000,"unit":"chars","fam":"diversity"},{"p":"How has your academic work beyond the 'traditional' pre-medical school requirements (i.e., introductory biology, general chemistry, organic chemistry, and introductory physics) prepared you for medical school and for a career in medicine? Please highlight any service-learning activities that align with humanism in medicine.","limit":4000,"unit":"chars","fam":"other"},{"p":"Have you encountered significant personal or professional challenges that have shaped your motivation to pursue a career in medicine and service to others?","limit":4000,"unit":"chars","fam":"challenge"},{"p":"If applicable, please describe how your experience with challenges has informed your perspective, decision-making, or approach to helping others. You may include reflections on your educational path, life experiences, or other formative events. If not applicable, please type NA.","limit":4000,"unit":"chars","fam":"challenge"},{"p":"Do you have any gaps or inconsistencies in either academic or standardized test performances throughout your undergraduate, graduate, or post-graduate career? …","limit":4000,"unit":"chars","fam":"other","cut":1},{"p":"Is there a time gap between earning your last degree (baccalaureate or other) and the expected time of your medical school matriculation? …","limit":4000,"unit":"chars","fam":"gap","cut":1},{"p":"Were you employed full-time (or part-time) during your undergraduate or graduate years? …","limit":4000,"unit":"chars","fam":"other","cut":1},{"p":"Have you previously applied to any medical school (M.D., D.O., international)? …","limit":4000,"unit":"chars","fam":"other","cut":1}]},{"name":"Nova Southeastern University Dr. Kiran C. Patel College of Osteopathic Medicine (NSU-KPCOM)","state":"FL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-nova-southeastern-university-dr-kiran-c-patel-college-of-osteopathic-medicine-nsu-kpcom.1518480/","prompts":[{"p":"How did you learn about osteopathic medicine?","limit":1000,"unit":"chars","fam":"osteo"},{"p":"List and briefly describe your significant health care-related volunteer activities since graduation from high school.","limit":1000,"unit":"chars","fam":"service"},{"p":"If you were employed during the regular school year (excluding summers) while in undergraduate or graduate school, please list dates of employment beginning with your current position along with title or job description, level of responsibility, and number of hours per week.","limit":1000,"unit":"chars","fam":"other"}]},{"name":"Nova Southeastern University Dr. Kiran C. Patel College of Osteopathic Medicine in Clearwater (NSU-KPCOM-Clearwater)","state":"FL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-nova-southeastern-university-dr-kiran-c-patel-college-of-osteopathic-medicine-in-clearwater-nsu-kpcom-clearwater.1518482/","prompts":[],"none":"No prompts posted yet"},{"name":"NYU Grossman Long Island School of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-nyu-school-of-medicine-long-island.1517745/","prompts":[{"p":"Prior to the current application cycle, have you ever applied to any medical school before? If you are a re-applicant to any medical school, please describe what steps you have taken to strengthen your candidacy.","limit":400,"unit":"words","fam":"other"},{"p":"Please select your intended residency track below and discuss your reasons for this choice,…","limit":400,"unit":"words","fam":"career","group":"Choose 1 of 3 tracks (Internal Medicine, Pediatrics, OB/GYN)","cut":1},{"p":"If you have graduated from college, please tell us what you have been doing since that time up until the… If you are still in college, what factors influenced your decision to apply to NYUGLISOM directly from undergrad?…","limit":400,"unit":"words","fam":"gap","group":"Answer the part that applies (graduated vs. still in college)","cut":1},{"p":"Do you have any personal, professional, or educational ties to the Long Island, NYC-Metropolitan or Tri-State (NY, NJ, CT) Areas?","limit":400,"unit":"words","fam":"why","opt":1},{"p":"Please comment on any significant fluctuations in your academic record or inconsistencies in your MCAT score; if you took a leave of absence for any reason during college; or any application irregularities…","limit":400,"unit":"words","fam":"other","opt":1,"cut":1},{"p":"Please feel free to share any other information that you have not already included in your AMCAS application or secondary responses that you believe would be relevant for the admissions committee to know about.","limit":400,"unit":"words","fam":"anything","opt":1}]},{"name":"NYU Grossman School of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-nyu-school-of-medicine-grossman.1517744/","prompts":[{"p":"If applicable, please comment on significant fluctuations in your academic record.","limit":0,"unit":"words","fam":"other","opt":1},{"p":"If you have taken any time off from your studies - before, during, or after college - please describe what you did during that time and your reasons for doing so.","limit":0,"unit":"words","fam":"gap","opt":1},{"p":"Tell us about a long-term goal you pursued over several years. What obstacles did you encounter, and what sustained your motivation when progress was slow?","limit":2500,"unit":"chars","fam":"challenge"},{"p":"Medical training demands continuous improvement. Share an example of feedback you received that was difficult to hear. How did you act on it, and what changed as a result?","limit":2500,"unit":"chars","fam":"challenge"},{"p":"Conflicts arise daily from differences in perspectives, priorities, worldviews and traditions. How do you define respect? Describe a situation in which you found it challenging to remain respectful while facing differences?","limit":2500,"unit":"chars","fam":"diversity"},{"p":"Describe a situation in which you faced an ethical dilemma or pressure to compromise your values. How did you navigate the situation, and what guided your decision?","limit":2500,"unit":"chars","fam":"ethics"},{"p":"Some of the most meaningful achievements are non-academic in nature. Describe the personal accomplishment that makes you most proud. Why is this important to you?","limit":2500,"unit":"chars","fam":"other"}]},{"name":"Oakland University William Beaumont School of Medicine","state":"MI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-oakland-university-william-beaumont.1517751/","prompts":[{"p":"Describe a significant sacrifice you had to make for someone else. How did you respond, what help-seeking behaviors did you utilize, and how did the experience shape your resilience, self-awareness, or personal growth?","limit":400,"unit":"words","fam":"challenge"},{"p":"Describe a time when you stepped outside of your comfort zone to engage with individuals, communities, patient populations, or environments that were unfamiliar to you. What challenges did you encounter and what did you learn about yourself and others?","limit":400,"unit":"words","fam":"diversity"},{"p":"At OUWB, we believe that effective physicians must be able to navigate differing perspectives with compassion and respect. Describe a time when you worked through conflict in a team (at a workplace, classroom, service activity, personal setting). What did you learn about communication, collaboration, and professionalism?","limit":400,"unit":"words","fam":"team"},{"p":"Is there anything you want the admissions committee to know about your qualifications for medical school that are not already represented in your application materials? For example, if you have already graduated, briefly summarize your activities since graduation. (Note: This space is provided for new information only, not to promote qualifications already highlighted in your other materials (Max 400 words)","limit":400,"unit":"words","fam":"anything"},{"p":"If you're EDP: Why did you choose to apply to OUWB'S Early Decision program (EDP)? Please explain your ties to OUWB. (Please only complete this question if you applied through the Early Decision Program)","limit":0,"unit":"words","fam":"why","opt":1},{"p":"If you're MD/MPH: Reflect on the experiences that sparked your interest in public health and your decision to pursue and MPH degree. How will the knowledge and skills gained through MPH training complement your medical education to achieve your professional aspirations? (Please only complete this question if you applied through the MD/MPH combined degree program) (400 words)","limit":400,"unit":"words","fam":"career","opt":1},{"p":"Reapp: If you are a reapplicant to OUWB, please describe the improvements you have made to your current application compared to previous cycles (please include academics, experiences, etc.)","limit":0,"unit":"words","fam":"other","opt":1}]},{"name":"Ohio State University College of Medicine","state":"OH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-ohio-state-university-college-of-medicine.1517752/","prompts":[{"p":"The mission statement of The Ohio State University College of Medicine is to \"improve people's lives\" through innovation in research, medical education, and patient care. Describe experiences that best demonstrate your potential to contribute meaningfully to two of these areas. What did you learn through these experiences, and how do they shape your goals as a future physician? (250 words)","limit":250,"unit":"words","fam":"why"},{"p":"Describe an experience that shaped your understanding of health inequities in the United States. What factors were involved, and how did this experience influence your perspective or actions? (250 words)","limit":250,"unit":"words","fam":"service"}]},{"name":"Ohio University Heritage College of Osteopathic Medicine (OU-HCOM)","state":"OH","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-ohio-university-heritage-college-of-osteopathic-medicine-ou-hcom.1518483/","prompts":[],"none":"No prompts posted yet"},{"name":"Ohio University Heritage College of Osteopathic Medicine - Cleveland (OU-HCOM-Cleveland)","state":"OH","deg":"DO","url":"https://forums.studentdoctor.net/threads/1518484/","prompts":[],"none":"No prompts posted yet"},{"name":"Ohio University Heritage College of Osteopathic Medicine - Dublin (OU-HCOM-Dublin)","state":"OH","deg":"DO","url":"https://forums.studentdoctor.net/threads/1518485/","prompts":[],"none":"No prompts posted yet"},{"name":"Oklahoma State University College of Osteopathic Medicine (OSU-COM)","state":"OK","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-oklahoma-state-university-college-of-osteopathic-medicine-osu-com.1518486/","prompts":[{"p":"Which of the following Elective Programs are you interested in? Global Health/ Rural Medicine/Tribal Medicine/Urban Underserved. Please explain what interests you about this elective program?","limit":0,"unit":"words","fam":"career"},{"p":"What experiences have motivated you toward a career in osteopathic medicine? Please share a meaningful experience you have had while in the health professional field.","limit":300,"unit":"words","fam":"osteo"},{"p":"Optional: Is there any additional information you would like the college to know about you?","limit":500,"unit":"words","fam":"anything","opt":1}]},{"name":"Oklahoma State University College of Osteopathic Medicine at Cherokee Nation (OSUCOM-Tahlequah)","state":"OK","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-oklahoma-state-university-college-of-osteopathic-medicine-at-cherokee-nation-osucom-tahlequah.1518487/","prompts":[],"none":"No prompts posted yet"},{"name":"Oregon Health & Science University School of Medicine","state":"OR","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-oregon-health-and-science-university-school-of-medicine.1517753/","prompts":[{"p":"What is a moment in your life that could have or changed your trajectory?","limit":1550,"unit":"chars","fam":"challenge"},{"p":"Describe the effect of an endeavor that didn't go according to your plan.","limit":1550,"unit":"chars","fam":"challenge"},{"p":"What is an ordinary place that feels extraordinary because of what happened there?","limit":1550,"unit":"chars","fam":"other"},{"p":"Tell us about what environments allow you to thrive the most and the least.","limit":1550,"unit":"chars","fam":"other"},{"p":"Discuss your experience of recent personal feedback that was difficult to receive.","limit":1550,"unit":"chars","fam":"challenge"},{"p":"Describe a time when you had to reconsider or change a deeply held belief or perspective. What prompted this change?","limit":1550,"unit":"chars","fam":"diversity"},{"p":"Describe a time when selfishness served you well.","limit":1550,"unit":"chars","fam":"other"},{"p":"Are there any additional ties to the state of Oregon you wish to share? If yes, use the space below. If no, leave blank. Please note that this does not factor toward your consideration as an Oregon resident or Oregon Heritage.","limit":1550,"unit":"chars","fam":"why","opt":1},{"p":"In Employment/Activities History: Please use this space to explain anything on the activity timeline that may be confusing and/or for any activity gaps of 3 months or longer in your timeline above in the last 5 years.","limit":4000,"unit":"chars","fam":"gap"},{"p":"Based on your own experiences or the experiences of family and friends, do you believe that the area in which you grew up was adequately served by the available health care professionals? Were there enough physicians, nurses, hospitals, clinics, and other health care service providers and how did that affect your experience and relationship with health care? Please explain.","limit":4000,"unit":"chars","fam":"service"},{"p":"Please describe the nature of the adversity and how social, economic, academic, or other circumstances affected you and your opportunities.","limit":4000,"unit":"chars","fam":"challenge"},{"p":"We acknowledge that our application is not fully comprehensive. If there is anything additional you would like to let us know about you, please briefly state it here.","limit":0,"unit":"words","fam":"anything"}]},{"name":"Orlando College of Osteopathic Medicine (OCOM)","state":"FL","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-orlando-college-of-osteopathic-medicine-ocom.1518488/","prompts":[],"none":"No prompts posted yet"},{"name":"Pacific Northwest University of Health Sciences College of Osteopathic Medicine (PNWU-COM)","state":"WA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-pacific-northwest-university-of-health-sciences-college-of-osteopathic-medicine-pnwu-com.1518489/","prompts":[],"none":"No prompts posted yet"},{"name":"Penn State College of Medicine","state":"PA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-pennsylvania-state-university-college-of-medicine.1517755/","prompts":[{"p":"If not currently enrolled in a full-time academic program, please summarize your activities from the time of graduation from your baccalaureate program through the time of this application, as well as your plans between now and your matriculation to medical school.","limit":75,"unit":"words","fam":"gap"},{"p":"Is there a unique aspect of your application that should be considered by the admissions committee?","limit":75,"unit":"words","fam":"anything"},{"p":"Explain why you decided to apply to the Penn State College of Medicine and what meaningful ties you may have to Hershey and the central PA area.","limit":75,"unit":"words","fam":"why"},{"p":"Part of the PSCOM mission is providing excellent care to the patients of Central PA and rural communities and ultimately the nation. How will you help us fulfill this mission?","limit":250,"unit":"words","fam":"service"},{"p":"Describe your motivation to be a physician.","limit":250,"unit":"words","fam":"career"}]},{"name":"Philadelphia College of Osteopathic Medicine (PCOM)","state":"PA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-philadelphia-college-of-osteopathic-medicine-pcom.1518490/","prompts":[],"none":"No written essays reported"},{"name":"Philadelphia College of Osteopathic Medicine Georgia Campus (PCOM-Georgia)","state":"GA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-philadelphia-college-of-osteopathic-medicine-georgia-campus-pcom-georgia.1518491/","prompts":[],"none":"No written essays reported"},{"name":"Philadelphia College of Osteopathic Medicine South Georgia (PCOM-South-Georgia)","state":"GA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-philadelphia-college-of-osteopathic-medicine-south-georgia-pcom-south-georgia.1518492/","prompts":[],"none":"No prompts posted yet"},{"name":"Ponce Health Sciences University School of Medicine, Puerto Rico","state":"PR","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-ponce-health-sciences-university-puerto-rico.1517756/","prompts":[],"none":"No written essays reported"},{"name":"Ponce Health Sciences University School of Medicine, St. Louis","state":"MO","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-ponce-health-sciences-university-saint-louis-mo.1517757/","prompts":[],"none":"No written essays reported"},{"name":"Quinnipiac University Frank H. Netter MD School of Medicine","state":"CT","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-quinnipiac-university-frank-h-netter-school-of-medicine.1517758/","prompts":[{"p":"If you will not be enrolled as a full-time student, how will you be spending/intend to spend your time during your application year? If you are a re-applicant, please address steps taken to improve your application for medical school.","limit":200,"unit":"words","fam":"gap"},{"p":"Although your interests may change, how do you currently envision your specialty interests and future career in medicine and why?","limit":200,"unit":"words","fam":"career"},{"p":"Tell us about some of your experiences that you believe will help you to take better care of patients.","limit":200,"unit":"words","fam":"other"},{"p":"As a medical student and future physician, you are faced with many uncertain situations. Please describe a situation when you were asked to do something that you felt unprepared for. How did you handle it?","limit":400,"unit":"words","fam":"challenge"},{"p":"At Netter SOM, we value service to each other and others in the community. Please share how you have made efforts to work with people from a different background than you. What did you learn from these efforts?","limit":400,"unit":"words","fam":"diversity"},{"p":"If applicable, please address any withdrawals, repeated courses, leaves of absence, or breaks in your undergraduate education that are not explained in your application.","limit":250,"unit":"words","fam":"other","opt":1}]},{"name":"Rocky Vista University - Montana College of Osteopathic Medicine (RVU-MCOM)","state":"MT","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-rocky-vista-university-montana-college-of-osteopathic-medicine-rvu-mcom.1518493/","prompts":[],"none":"No prompts posted yet"},{"name":"Rocky Vista University College of Osteopathic Medicine (RVUCOM)","state":"CO","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-rocky-vista-university-college-of-osteopathic-medicine-rvucom.1518494/","prompts":[{"p":"What noteworthy characteristics, abilities, or skills do you possess that will help ensure RVU achieves new heights in medical education?","limit":0,"unit":"words","fam":"diversity"}]},{"name":"Rocky Vista University College of Osteopathic Medicine - Southern Utah Campus (RVUCOM-Southern)","state":"UT","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-rocky-vista-university-college-of-osteopathic-medicine-southern-utah-campus-rvucom-southern.1518495/","prompts":[],"none":"No prompts posted yet"},{"name":"Roseman University College of Medicine","state":"NV","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-roseman-university-college-of-medicine.1517759/","prompts":[],"none":"No written essays reported"},{"name":"Rowan-Virtua School of Osteopathic Medicine (Rowan-Virtua-SOM)","state":"NJ","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-rowan-virtua-school-of-osteopathic-medicine-rowan-virtua-som.1518496/","prompts":[{"p":"How did you learn about osteopathic medicine and why is it a good fit for you?","limit":0,"unit":"words","fam":"osteo"},{"p":"Explain why you are interested in attending Rowan-Virtua School of Osteopathic Medicine:","limit":0,"unit":"words","fam":"why"},{"p":"We seek to train physicians who can connect with diverse patient populations with whom they may not share a similar background. Tell us about an experience that has broadened your own worldview or enhanced your ability to understand those unlike yourself and what you learned from it.","limit":0,"unit":"words","fam":"diversity"},{"p":"Optional - Please describe any significant barriers or challenges you may have overcome in the pursuit of your personal/professional goals:","limit":0,"unit":"words","fam":"challenge","opt":1}]},{"name":"Rowan-Virtua School of Osteopathic Medicine Sewell Campus (Rowan-Virtua-SOM-Sewell)","state":"NJ","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-rowan-virtua-school-of-osteopathic-medicine-sewell-campus-rowan-virtua-som-sewell.1518497/","prompts":[],"none":"No prompts posted yet"},{"name":"Rush Medical College","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-rush-medical-college.1517760/","prompts":[{"p":"Rush Medical College is located on Chicago’s near west side and serves a diverse patient population. We seek to train physicians who can connect with diverse patient populations with whom they may not share a similar background. Tell us about a life experience that has broadened your own world view or enhanced your ability to understand those unlike yourself and what you learned from this experience.","limit":1000,"unit":"chars","fam":"diversity"},{"p":"Tell us about an experience within a healthcare environment that revealed the complexity of caring for others. How did your understanding evolve through reflection, observation, or continued engagement, and what did you learn about the responsibilities of medicine?","limit":1000,"unit":"chars","fam":"other"},{"p":"Some commitments grow deeper the longer we remain involved. Tell us about an experience that required sustained engagement with others. What drew you to it initially, what kept you engaged, and how did it influence the way you think about caring for others, serving communities, social responsibility, or contributing to something larger than yourself?","limit":1000,"unit":"chars","fam":"service"},{"p":"Advancing knowledge often begins with curiosity, persistence, and a willingness to question what is already known. Tell us about an experience, project, or question that demanded sustained inquiry from you. Where did it lead, and how did it shape the way you think about discovery, innovation, or lifelong learning?","limit":1000,"unit":"chars","fam":"career"},{"p":"Describe an experience that required you to persist, adapt, or rethink your approach in order to create meaningful progress. What kept you engaged, and how did the experience influence the way you approach leadership accountability, or future challenges?","limit":1000,"unit":"chars","fam":"challenge"},{"p":"If applicable, describe how the COVID-19 pandemic has impacted your application to and/or preparation for medical school. (Optional) (1000 characters max)","limit":1000,"unit":"chars","fam":"challenge","opt":1},{"p":"Use this space to provide additional information, that is non-COVID related, you would like the Committee on Admissions to be aware of when reviewing your application. (Optional) (1000 characters max)","limit":1000,"unit":"chars","fam":"anything","opt":1}]},{"name":"Rutgers New Jersey Medical School","state":"NJ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-rutgers-new-jersey-medical-school.1517761/","prompts":[{"p":"If you are re-applying to medical school, describe the steps you have taken to strengthen your candidacy and reflect on what…","limit":0,"unit":"words","fam":"other","cut":1}]},{"name":"Rutgers Robert Wood Johnson Medical School","state":"NJ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-rutgers-robert-woods-johnson-medical-school.1517762/","prompts":[{"p":"RWJMS has identified the core values below as critical to our mission and vision. We strive to matriculate learners who embody these values. R -- Respect, dignity and humanism for the diverse population we serve W -- Wellness and resilience J -- Joining learners hand in hand with care delivery M -- Making patients first with safe, compassionate, high-quality care S -- Science to advance human health In two paragraphs or less, identify which value you selected and reflect on one of your experiences to discuss how you have built a foundation for this value.","limit":0,"unit":"words","fam":"why","group":"Choose 1 of 5 values"},{"p":"RWJMS strives to matriculate a student body that supports and enriches each other and the learning environment. Please share a life experience, personal attribute, and/or perspective that will help contribute to this learning environment. (250 words or less)","limit":250,"unit":"words","fam":"diversity"},{"p":"Medical training can be stressful. What strategies have you developed to manage stress and maintain your well-being? How have these strategies evolved over time? (250 words or less)","limit":250,"unit":"words","fam":"other"},{"p":"Discuss a difficult or challenging situation you have encountered and how you dealt with it. What did you learn from this situation? (Please keep this under 250 words)","limit":250,"unit":"words","fam":"challenge"},{"p":"Describe a time when you received feedback that you did not agree with. How did you handle this situation? What did you learn from this experience? (Please keep this under 250 words)","limit":250,"unit":"words","fam":"challenge"},{"p":"Please feel free to comment on any course grades, GPA trends, or MCAT scores and what you have learned about yourself. (no limit)","limit":0,"unit":"words","fam":"other","opt":1},{"p":"Please use this space if you would like to provide additional information to the admissions committee. (no limit)","limit":0,"unit":"words","fam":"anything","opt":1}]},{"name":"Saint Louis University School of Medicine","state":"MO","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-saint-louis-university-school-of-medicine.1517763/","prompts":[{"p":"Have you or will you have taken gap time equal to a semester or more? Please describe your gap activities (past and/or future):","limit":1000,"unit":"chars","fam":"gap"},{"p":"Why did you apply to Saint Louis University School of Medicine?","limit":1000,"unit":"chars","fam":"why"},{"p":"Do you wish to include any comments (other extenuating circumstances not addressed in your primary application, updates, clarifications, etc.)? Please explain:","limit":1000,"unit":"chars","fam":"anything","opt":1},{"p":"Describe a meaningful experience that expanded your viewpoint or deepened your understanding of individuals whose backgrounds, circumstances, or life journeys differ from your own.","limit":1000,"unit":"chars","fam":"diversity"}]},{"name":"Sam Houston State University College of Osteopathic Medicine (SHSU-COM)","state":"TX","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-sam-houston-state-university-college-of-osteopathic-medicine-shsu-com.1518498/","prompts":[{"p":"How has your community and/or hometown shaped your values and your pursuit of medicine?","limit":800,"unit":"chars","fam":"diversity"},{"p":"Describe a moment when you failed to accomplish a task or let yourself down. How did you grow from this experience?","limit":800,"unit":"chars","fam":"challenge"},{"p":"What do you consider the role of physicians in medically underserved Texas communities?","limit":800,"unit":"chars","fam":"service"},{"p":"Sam Houston State University's Motto is \"The Measure of a Life is its Service.\" What is the most significant service contribution that you have made?","limit":800,"unit":"chars","fam":"service"},{"p":"Why do you want to pursue osteopathic medicine at SHSU-COM? What about osteopathic medical education interests you?","limit":800,"unit":"chars","fam":"why"},{"p":"Please share anything you would like to mention to the SHSU-COM Admissions Committee about yourself to strengthen your application.","limit":500,"unit":"chars","fam":"anything"}]},{"name":"Sidney Kimmel Medical College at Thomas Jefferson University","state":"PA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-sidney-kimmel-medical-college-at-thomas-jefferson.1517764/","prompts":[{"p":"Sidney Kimmel Medical College defines diversity as the richness in human differences. How will your own experiences allow you to contribute to the diversity of the student body and to provide equitable and inclusive care to your future patients?","limit":0,"unit":"words","fam":"diversity"},{"p":"Do you have additional information that you would like to provide at this time?","limit":0,"unit":"words","fam":"anything"}]},{"name":"Southern Illinois University School of Medicine","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-southern-illinois-university-school-of-medicine.1517777/","prompts":[{"p":"SIU School of Medicine uses a holistic approach to identify students who best fulfill its mission: to assist the people of central and southern Illinois in meeting their health care needs through education, patient care, research and service to the community. In what ways do you believe you would contribute to SIU’s mission and what barriers have you overcome in your life’s circumstances to reach this point in applying to medical school? Please limit your response to 300 words or less.","limit":300,"unit":"words","fam":"why"},{"p":"Tell us about your lived experiences that will make you a better physician? Please limit your response to 300 words or less.","limit":300,"unit":"words","fam":"diversity"},{"p":"To be successful as a student at SIU School of Medicine and as a practicing physician, you must be flexible and committed to cultivating and employing critical interactive and learning skills. Describe your experiences that demonstrate: contribution in a teamwork setting; engagement in self-directed and life-long learning (taking personal initiative to identify and address your learning goals and needs); and exposure to the small group tutorial process used in a problem-based learning environment. Please limit your answer to 500 words or less.","limit":500,"unit":"words","fam":"team"},{"p":"If you have previously applied to SIU School of Medicine, please describe how you feel you have strengthened your credentials since that application. Please limit your answer to 300 words or less.","limit":300,"unit":"words","fam":"other","opt":1}]},{"name":"Stanford University School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-stanford-university-school-of-medicine.1517778/","prompts":[{"p":"What do you see as the most likely practice scenario for your future medical career? Choose the single answer that best describes your career goals and clinical practice setting: Academic Medicine (Clinical); Academic Medicine (Physician Scientist); Health Policy; Primary Care; Public Health/Community Health; Global Health. Please describe your motivation for this practice scenario. Why do you feel you are particularly suited for this practice scenario? What knowledge, skills and attitudes have you developed that have prepared you for this career path?","limit":1000,"unit":"chars","fam":"career","group":"Choose 1 of 6 practice settings"},{"p":"How will you take advantage of the Stanford Medicine Discovery Curriculum and scholarly concentration requirement to achieve your personal career goals?","limit":1000,"unit":"chars","fam":"why"},{"p":"Describe in a short paragraph your educational and family background. E.g., I grew up in New York City, as the 3rd child of a supermarket cashier and a high school principal. I attended Mann High School where my major interests were boxing and drama.","limit":600,"unit":"chars","fam":"diversity"},{"p":"How have your life experiences shaped your perspective on medicine, health, or patient care—and how do you anticipate bringing that perspective into our learning community?","limit":2000,"unit":"chars","fam":"diversity"},{"p":"Please describe a significant contribution you've made to a community that matters to you. What role did you play, how did you influence others, and how did your actions create positive change?","limit":1000,"unit":"chars","fam":"service"},{"p":"What do you see as your greatest area for growth, and how will you address it?","limit":1000,"unit":"chars","fam":"challenge"},{"p":"Please describe a time you felt unfairly treated or judged and how you responded.","limit":1000,"unit":"chars","fam":"challenge"},{"p":"Please include anything else that will help us understand better how you may uniquely contribute to Stanford Medicine? (OPTIONAL)","limit":1000,"unit":"chars","fam":"anything","opt":1},{"p":"Describe your most significant research experience. Include the rationale, results, and conclusions, and the role you played in each of these components.","limit":2500,"unit":"chars","fam":"career","group":"Possibly PSTP/MSTP only (unclear per thread)"}]},{"name":"Stony Brook University Renaissance School of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-stony-brook-university-renaissance-school-of-medicine.1517779/","prompts":[{"p":"Will your education be continuous between college and medical school matriculation? If NO, please explain what you have done or plan to do during the gap period and why.","limit":500,"unit":"words","fam":"gap"},{"p":"Tell us how your past experiences and/or challenges have defined you:","limit":500,"unit":"words","fam":"challenge"},{"p":"Please respond to ONE of the following two questions: Please tell us about your career goals, and how you plan to achieve them.","limit":500,"unit":"words","fam":"career","group":"Choose 1 of 2"},{"p":"Please respond to ONE of the following two questions: Can you describe a time you faced an ethical/professional dilemma and how you managed it","limit":500,"unit":"words","fam":"ethics","group":"Choose 1 of 2"},{"p":"Please describe the basic and/or clinical research fields that you think you might like to explore and/or develop expertise in during your MSTP training. To the extent that you have defined potential specific future clinical interests, please describe the type(s) of medicine that you might be interested in pursuing once you have completed the MSTP.","limit":500,"unit":"words","fam":"career","group":"MSTP applicants only"}]},{"name":"SUNY Downstate College of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-suny-downstate-college-of-medicine.1517780/","prompts":[{"p":"What will be your support system while in medical school? (Limit 150 words)","limit":150,"unit":"words","fam":"other"},{"p":"Describe what personal, urban experiences prepare you to live and study in New York City (Limit 150 words)","limit":150,"unit":"words","fam":"why"},{"p":"If you had a completed application to the College of Medicine in a prior application cycle, please highlight any changes since your previous application in a list with dates. If this question does not apply to you, enter \"not applicable\" in the text box below. (Limit 150 words)","limit":150,"unit":"words","fam":"other"},{"p":"Why do believe you are a good fit for SUNY Downstate? (300 words)","limit":300,"unit":"words","fam":"why"},{"p":"What is your experience with diversity, health equity and social justice? (300 words)","limit":300,"unit":"words","fam":"diversity"},{"p":"Are there any periods longer than 3 months, from the time you graduated from high school to now, when you were not employed full time or in college full-time? If yes, please briefly describe your activities (no limit)","limit":0,"unit":"words","fam":"gap"}]},{"name":"SUNY Upstate Norton College of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-suny-upstate-norton-college-of-medicine.1517781/","prompts":[{"p":"Gap year plans (no limit)","limit":0,"unit":"words","fam":"gap"},{"p":"Which medical specialty do you currently plan to pursue? (no limit)","limit":0,"unit":"words","fam":"career"},{"p":"Are there any areas of weakness in your application that you would like to clarify for the Admissions Committee? If yes, Please describe. (1,800 characters)","limit":1800,"unit":"chars","fam":"anything"},{"p":"What experiences have you had with underserved communities/populations? What have you learned from these experiences? (1,800 characters)","limit":1800,"unit":"chars","fam":"service"},{"p":"Describe any ties or meaningful experiences you have had related to Central New York or SUNY Upstate Medical University. (1,800 characters)","limit":1800,"unit":"chars","fam":"why"},{"p":"How will you contribute to the diversity of your medical school class and The Norton College of Medicine? (1,800 characters)","limit":1800,"unit":"chars","fam":"diversity"},{"p":"The Norton College of Medicine is committed to improving the healthcare of Central New York. How do your career plans advance this mission? (1,800 characters)","limit":1800,"unit":"chars","fam":"career"}]},{"name":"TCU Burnett School of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-tcu-burnett-school-of-medicine.1517782/","prompts":[{"p":"The Burnett School of Medicine defines empathetic scholars with these eight traits: Compassion, Teachability, Altruism, Insight, Humility, Collaboration, Integrity, and Respect. (answer both parts of this prompt within 250-300 words) Which trait do you think you embody most and how will that be valuable to patient care? Which trait might you need to improve upon? How will you improve in this area and how will this be of value in your role as a physician?","limit":300,"unit":"words","fam":"why"},{"p":"Characteristics of an aspiring MD. (250 to 300 words) Describe any personal qualities and/or lived experiences that add context to your application that shape who you are as an individual and aspiring healthcare leader.","limit":300,"unit":"words","fam":"diversity"}]},{"name":"Temple University Lewis Katz School of Medicine","state":"PA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-temple-university-lewis-katz-school-of-medicine.1517783/","prompts":[{"p":"Tell us about your special interest in the first choice campus you selected.","limit":2000,"unit":"chars","fam":"why"},{"p":"Founded on a historic commitment to expanding access to education and healthcare, the Lewis Katz School of Medicine emphasizes a mission rooted in training physicians who combine scientific excellence with deep humanistic commitment. Our mission and vision highlight the importance of compassionate care, community engagement, and a drive to improve health outcomes through innovation, advocacy, and service. Please share how your experiences and/or activities reflect these values and how they shape the physician you hope to become.","limit":2000,"unit":"chars","fam":"why"},{"p":"The Admissions Committee would like to know more about you. Katz seeks an engaged student body with a wide variety of experiences, perspectives, and interests to enhance the medical school experience for everyone. Please use the space below to describe what makes you unique as an applicant, an obstacle that you had to overcome, or how you will contribute to the Katz community.","limit":2000,"unit":"chars","fam":"diversity"},{"p":"What are your plans for the current year - June 2026 until June 2027?","limit":2000,"unit":"chars","fam":"gap"},{"p":"[optional] IA explanation","limit":2000,"unit":"chars","fam":"other","opt":1}]},{"name":"Texas A&M University Naresh K. Vashisht College of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-texas-a-m-university-naresh-k-vashisht-college-of-medicine.1517784/","prompts":[{"p":"As a physician, you never know what type of patient you will serve. From your past experiences, please describe or highlight factors or situations that demonstrate your ability to work with individuals from multicultural communities.","limit":3500,"unit":"chars","fam":"diversity"},{"p":"The Texas A&M University Naresh K. Vashisht College of Medicine embraces the Aggie Core Values of Respect, Excellence, Leadership, Loyalty, Integrity and Selfless Service. Please elaborate on personal characteristics, values, accomplishments and/or any experiences that you feel will help to demonstrate your potential to contribute to the college and to the profession of medicine.","limit":3500,"unit":"chars","fam":"why"},{"p":"OPTIONAL: Describe or reflect any circumstances indicative of some degree of hardship, such as, but not limited to: personal or family illness, a medical condition, a death in the immediate family or socioeconomic disadvantages not mentioned in your primary application essays. What steps or strategies have you used to address these circumstances?","limit":3500,"unit":"chars","fam":"challenge","opt":1},{"p":"Please indicate the area(s) of medicine you are interested in and briefly describe your significant activities for each respective interest in the available text box. You may select more than one. (150 Words Each)","limit":150,"unit":"words","fam":"career","group":"Select any of 7 areas (150 words each)"}]},{"name":"Texas Tech University HSC El Paso Foster School of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-texas-tech-el-paso-foster-school-of-medicine.1517785/","prompts":[{"p":"The mission of the Texas Tech University Health Sciences Center El Paso Paul L. Foster School of Medicine is to provide an outstanding education and development opportunities for a diverse group of students, residents, faculty, and staff; advance knowledge through innovation and research; and serve the needs of our socially and culturally diverse communities and region.” Recognizing the components of this mission and that PLFSOM is located on the US/Mexico border, please describe why you are interested in applying to our school. (300 words or less)","limit":300,"unit":"words","fam":"why"},{"p":"The Foster SOM student honor code states “In my capacity as a Texas Tech University Health Sciences Center El Paso School of Medicine medical student, I will uphold the dignity of the medical profession. I will, to the best of my ability, avoid actions which might result in harm to my patients. I will protect the dignity of my patients and the deceased, and will protect their confidential information in accordance with the prevailing standards of medical practice. I will not lie, cheat, or steal. I will enter into professional relationships with my colleagues, teachers, and other health care professionals in a manner that is respectful and reflective of the high standards and expectations of my profession. I will not tolerate violations of this Code by others and will report such violations to the appropriate authorities.” Please describe past experiences or personal attributes that reflect your affinity with this honor code. (300 words or less)","limit":300,"unit":"words","fam":"ethics"},{"p":"Please describe any unique personal experiences OR disadvantage (educational, financial or otherwise) and their significance to you in your pursuit of a medical degree. (300 words or less)","limit":300,"unit":"words","fam":"diversity"}]},{"name":"Texas Tech University HSC School of Medicine, Lubbock","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-texas-tech-university-hsc-school-of-medicine-at-lubbock.1517786/","prompts":[{"p":"Select the area(s) of interest that you have experience or related activities with (please check all that apply). There is a 150-word limit for each selected area: Practice in an underserved area and/or work with an underserved population; Rural/Border health; Medical Research/Academics; Primary Care; Other (please describe below)","limit":150,"unit":"words","fam":"career","group":"Check all that apply (150 words each)"},{"p":"Have you experienced any road bumps in your academic career? (low academic performance, dropping, retaking, or failing courses, etc.) If yes, please explain your circumstance.","limit":250,"unit":"words","fam":"challenge"},{"p":"Describe a meaningful setback in your academic, professional, or personal journey. How did you respond, and how has that experience shaped the habits, skills, and mindset you have developed to succeed in medical school?","limit":0,"unit":"words","fam":"challenge"},{"p":"Describe your motivation to pursue this program at TTUHSC, be sure to include how you expect to benefit from our program.","limit":0,"unit":"words","fam":"why"},{"p":"How do you anticipate this program making you a more efficient caregiver?","limit":0,"unit":"words","fam":"career"},{"p":"Please list the highest-level math/chemistry/physics course you have taken or are currently taking.","limit":0,"unit":"words","fam":"other"},{"p":"What projects have you been involved in that require programming and or machine languages? What languages do you prefer?","limit":0,"unit":"words","fam":"other"},{"p":"What motivates you to participate in the FMAT program?","limit":200,"unit":"words","fam":"why"},{"p":"What experiences have you had that would prepare you for this intensive program?","limit":200,"unit":"words","fam":"other"},{"p":"What, in your opinion, distinguishes Family Medicine from other medical specialties?","limit":200,"unit":"words","fam":"career"},{"p":"Have you experienced any hardship or adversity; personally or professionally? If yes, please share your experience with us.","limit":200,"unit":"words","fam":"challenge"},{"p":"TTUHSC has a values-based culture. Its core values are One Team, Kindhearted, Integrity, Visionary, and Beyond Service. Choose one core value that you believe represents your greatest strength. Explain why you chose this value and how it will contribute to your success and impact in medical school.","limit":100,"unit":"words","fam":"why"},{"p":"Please share with us your ideal practice. For example: Where would you practice? Who would your patients be? What would your specialty be?","limit":100,"unit":"words","fam":"career"},{"p":"Do you consider yourself from West Texas or as having West Texas ties? If yes, what town or county did you reside in, or what other factors would you cite?","limit":100,"unit":"words","fam":"why"}]},{"name":"The Valley College of Osteopathic Medicine (TVCOM)","state":"AZ","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-the-valley-college-of-osteopathic-medicine.1520533/","prompts":[],"none":"No prompts posted yet"},{"name":"Touro College of Osteopathic Medicine - Harlem (TouroCOM-Harlem)","state":"NY","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-touro-college-of-osteopathic-medicine-harlem-tourocom-harlem.1518499/","prompts":[{"p":"This Personal Statement is different than the essay that had been submitted with your AACOMAS application. In no more than three paragraphs that will fit on this single page (if the essay creates a second page, it is too long), please discuss how your background, experience or academic program has prepared you for meeting Touro College of Osteopathic Medicine’s Mission, Goals, or Objectives.","limit":0,"unit":"words","fam":"why"}]},{"name":"Touro College of Osteopathic Medicine - Middletown (TouroCOM-Middletown)","state":"NY","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-touro-college-of-osteopathic-medicine-middletown-tourocom-middletown.1518500/","prompts":[],"none":"No prompts posted yet"},{"name":"Touro College of Osteopathic Medicine - Montana (TouroCOM-Montana)","state":"MT","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-touro-college-of-osteopathic-medicine-montana-tourocom-montana.1518501/","prompts":[],"none":"No prompts posted yet"},{"name":"Touro University College of Osteopathic Medicine - California (TUCOM-CA)","state":"CA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-touro-university-college-of-osteopathic-medicine-california-tucom-ca.1518502/","prompts":[{"p":"Please select one of the tenets of Osteopathic Medicine and explain how it might relate to one or more of your lived experiences","limit":0,"unit":"words","fam":"osteo"},{"p":"Please describe your hobbies (or non-academic pursuits) and how they will influence your success as an Osteopathic medical student and/or Osteopathic physician in the future.","limit":0,"unit":"words","fam":"other"},{"p":"Please discuss how your life experiences and personal characteristics will contribute to your future success as an outstanding osteopathic physician.","limit":0,"unit":"words","fam":"diversity"},{"p":"When considering medical schools, what criteria are important to you and how does TUCOM align with those criteria?","limit":0,"unit":"words","fam":"why"}]},{"name":"Touro University Nevada College of Osteopathic Medicine (TUNCOM)","state":"NV","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-touro-university-nevada-college-of-osteopathic-medicine-tuncom.1518503/","prompts":[{"p":"Why are you interested in pursuing this degree at Touro Nevada?","limit":500,"unit":"words","fam":"why"},{"p":"Is there anything not on the AACOMAS application that you would like the admissions committee to know about you?","limit":500,"unit":"words","fam":"anything"},{"p":"Please explain any award and accolades you have listed on your AACOMAS application.","limit":500,"unit":"words","fam":"other"},{"p":"What award(s) or recognition(s) have you received within the last five years?","limit":500,"unit":"words","fam":"other"},{"p":"What volunteer experience have you had during the last three years?","limit":500,"unit":"words","fam":"service"},{"p":"What research experience have you had during the last three years?","limit":500,"unit":"words","fam":"other"}]},{"name":"Tufts University School of Medicine","state":"MA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-tufts-university-school-of-medicine.1517787/","prompts":[{"p":"Do you wish to share a specific reason why you have chosen to apply to Tufts University School of Medicine?","limit":1000,"unit":"chars","fam":"why"},{"p":"Please briefly describe your plans for the coming year.","limit":1000,"unit":"chars","fam":"gap"},{"p":"Please tell us about your journey to medical school and how your background and experiences will positively impact your future as a medical student and physician. …","limit":1000,"unit":"chars","fam":"diversity","cut":1},{"p":"Which of your experiences with clinical medicine or healthcare has best prepared you for a future career as a physician, and why? …","limit":1000,"unit":"chars","fam":"other","cut":1},{"p":"Have you done substantial work or service that has contributed to societal good, or addressed social determinants of health, health equity, or social justice? …","limit":1000,"unit":"chars","fam":"service","cut":1},{"p":"Do you have any withdrawals or repeated coursework listed on your transcript(s)?","limit":1000,"unit":"chars","fam":"other"},{"p":"Did you take any leaves of absence or significant breaks from your undergraduate education?","limit":1000,"unit":"chars","fam":"gap"},{"p":"Please comment on any academic difficulties that you have encountered since completing high school …","limit":1000,"unit":"chars","fam":"challenge","cut":1},{"p":"Have you ever been convicted of, or pleaded guilty or no contest to, a Misdemeanor crime …","limit":1000,"unit":"chars","fam":"other","cut":1},{"p":"Do you wish to include any additional comments (beyond those already provided in your application) to the Admissions Committee at Tufts University School of Medicine? …","limit":1000,"unit":"chars","fam":"anything","opt":1,"cut":1}]},{"name":"Tulane University School of Medicine","state":"LA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-tulane-university-school-of-medicine.1517788/","prompts":[{"p":"Tulane University School of Medicine’s mission statement states: \"We improve human health and foster healthy communities through discovery and translation of the best science into clinical practice and education; to deliver the highest quality patient care and prepare the next generation of distinguished clinical and scientific leaders.\" Briefly describe how this statement resonates with your desire to attend Tulane University School of Medicine.","limit":150,"unit":"words","fam":"why"},{"p":"What disparities in health do you believe are pertinent to the New Orleans community or similar patient populations? How would you attempt to address them as a medical student at Tulane? You may support your answer by using demonstrated past involvement working with similar patient populations to compare and/or describe your interest in any student experience offered at TUSOM or in New Orleans.","limit":150,"unit":"words","fam":"service"},{"p":"Who knows you best and how would they describe you?","limit":150,"unit":"words","fam":"other"},{"p":"What have you been pursuing since you graduated?","limit":0,"unit":"words","fam":"gap"},{"p":"Please list any leadership positions (clubs, organizations, paid work) you may have held.","limit":100,"unit":"words","fam":"team"},{"p":"Please list your hobbies and major non-academic interests","limit":150,"unit":"words","fam":"other"},{"p":"Applying to medical school is a long and arduous process. Describe any ways your medical school application journey was hindered, altered or interrupted?","limit":0,"unit":"words","fam":"challenge","opt":1}]},{"name":"UC Davis School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-california-davis-school-of-medicine.1517796/","prompts":[{"p":"Briefly describe this activity and its significance. How did it prepare you for a medical career? Include any supporting information (e.g. your contribution to the project or accomplishment as well as links to any publication, etc)","limit":500,"unit":"chars","fam":"other"}]},{"name":"UC Irvine School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-california-irvine-school-of-medicine.1517797/","prompts":[{"p":"Have you demonstrated an ability to work with underserved communities? If yes, please describe.","limit":0,"unit":"words","fam":"service"},{"p":"What personal accomplishment are you most proud of and why?","limit":1500,"unit":"chars","fam":"other"},{"p":"Please describe to the Admissions Committee a challenge or disappointment you have overcome and what you learned about yourself from that experience.","limit":1500,"unit":"chars","fam":"challenge"},{"p":"Have you ever had difficulty accessing quality education or healthcare? If so, please describe how this impacted you and others in your community.","limit":1500,"unit":"chars","fam":"diversity"},{"p":"Please clarify for the Admissions Committee your activities (school, work, and/or volunteer, travel, etc.) since receiving your undergraduate degree. You may list them in chronological order or you may incorporate them into an essay, stating why you chose particular activities. If you have just received or will receive your undergraduate degree this year, please discuss your plans for current year.","limit":1500,"unit":"chars","fam":"gap"},{"p":"Please describe how you have served your community (school, neighborhood, city, etc.) and how these experiences have prepared you for PRIME-LC.","limit":1500,"unit":"chars","fam":"service","opt":1,"group":"PRIME-LC applicants only"},{"p":"Please describe the reason for your interest to be trained as a physician leader for the Latino community. In addition, explain how you intend to utilize the PRIME-LC specialized training to impact community health and health services for the Latino community.","limit":1500,"unit":"chars","fam":"career","opt":1,"group":"PRIME-LC applicants only"},{"p":"Please describe how you have served your community (school, neighborhood, church, etc.) and how these experiences have prepared you for PRIME LEAD-ABC.","limit":1500,"unit":"chars","fam":"service","opt":1,"group":"PRIME LEAD-ABC applicants only"},{"p":"What is the most important healthcare issue confronting medically under-resourced communities, in particular the ABC communities, and what would be your first steps to address this issue?","limit":1500,"unit":"chars","fam":"service","opt":1,"group":"PRIME LEAD-ABC applicants only"},{"p":"Please describe the reason(s) for your interest to be trained as a physician leader for the ABC community.","limit":1500,"unit":"chars","fam":"career","opt":1,"group":"PRIME LEAD-ABC applicants only"},{"p":"Explain how you intend to utilize the PRIME LEAD-ABC specialized training to impact community health services for the ABC community.","limit":1500,"unit":"chars","fam":"career","opt":1,"group":"PRIME LEAD-ABC applicants only"}]},{"name":"UC Riverside School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-california-riverside-school-of-medicine.1517798/","prompts":[{"p":"The mission of the UCR School of Medicine is to improve the health of the people of California and, especially, to serve Inland Southern California by training a diverse workforce of physicians and by developing innovative research and health care delivery programs that will improve the health of the medically underserved in the region and become models to be emulated throughout the state and nation. What experiences, skills, and abilities will you bring to the class to fulfill this mission?","limit":250,"unit":"words","fam":"why"},{"p":"The values of the UCR SOM are integrity, innovation, inclusion, excellence, accountability and respect. Please choose one of the values and tell us how you have displayed it in a clinical setting.","limit":250,"unit":"words","fam":"other"},{"p":"In what type of healthcare setting do you see yourself practicing medicine?","limit":250,"unit":"words","fam":"career"},{"p":"Tell us about a personal challenge you have faced in your life thus far and how you demonstrated resilience and grit to overcome it. [Please do not write about studying for or taking the MCAT.]","limit":250,"unit":"words","fam":"challenge"},{"p":"(Optional) If there is anything you would like the committee to consider about your candidacy that is not explained elsewhere in your application, please use this space to tell us.","limit":250,"unit":"words","fam":"anything","opt":1},{"p":"Please describe the reason for your interest in being trained as a physician leader for the African, Black, Caribbean community in the Inland Southern California Region.","limit":250,"unit":"words","fam":"service"},{"p":"What is the most important healthcare issue confronting African, Black, Caribbean communities in the Inland Southern California region and what would be your first steps to address this issue?","limit":250,"unit":"words","fam":"service"},{"p":"In what ways has your lived experiences, professional work, or academic studies within the African, Black, Caribbean community shaped your personal growth and deepened your commitment to the PRIME program's mission?","limit":250,"unit":"words","fam":"diversity"}]},{"name":"UC San Diego School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-california-san-diego-school-of-medicine.1517799/","prompts":[{"p":"This should be a true autobiographical statement. Topics to be included are family, childhood, primary and secondary school years, undergraduate years, and, if applicable, what you’ve done since completing your bachelor’s degree. You should also discuss the motivational factors which led you to a career in medicine including any disadvantages or obstacles which might put your accomplishments into context. A repeat of your AMCAS statement will not be acceptable.","limit":6000,"unit":"chars","fam":"other"},{"p":"If you are an out-of-state applicant, please let us know if there are specific reasons for your interest in the UCSD School of Medicine","limit":1000,"unit":"chars","fam":"why"},{"p":"Applicants indicating an interest in PRIME are required to write an additional essay detailing their qualifications and reasons for interest in the program. Please describe your interest in the PRIME-HEq program. Topics to include are longitudinal experiences that you’ve had with underserved communities, including the type of community that you’ve worked with and your level of involvement. Additionally, you should discuss the length of time that you’ve spent working in these communities.","limit":4800,"unit":"chars","fam":"service","opt":1},{"p":"Applicants interested in applying for the GHAC are required to write an additional essay detailing their qualifications and reasons for interest in this program. Please describe your interest in Global Health. The term Global Health can have many meanings; for our purposes, we find the definition provided by Koplan et. al. in their 2009 Lancet publication useful: “the area of study, research and practice that places a priority on improving health and achieving equity in health for all people worldwide”. In your essay, be sure to describe any personal or professional experiences that have shaped your interests, and how Global Health issues have influenced your decision to pursue a career in medicine.","limit":4800,"unit":"chars","fam":"career","opt":1},{"p":"Please describe your experiences with American Indian and Alaskan Native communities, including the type of community and your level of involvement. Please provide the length of time you spent working in or exposed to these communities. Be sure to detail any personal or professional experiences that have shaped your interests, and how American Indian and Alaskan Native issues have influenced your decision to pursue a career in medicine. Finally, please delineate how completion of the PRIME-TIDE program will help you obtain your medical education goals.","limit":4800,"unit":"chars","fam":"service","opt":1},{"p":"Applicants interested in being considered for CIMAC are required to write an additional essay detailing their qualifications and reasons for interest in this program. Please describe your interest in Compassion and Empathy. In your essay, be sure to describe any personal or professional experiences that have shaped your interests, and how you think your career as a physician would benefit from being in this program.","limit":4800,"unit":"chars","fam":"other","opt":1},{"p":"Do you consider yourself to be a member of a group that is marginalized in a way that systemically affects access to quality education or healthcare? Please describe how educational disparity, health disparity and/or marginalization has impacted you and your community?","limit":4800,"unit":"chars","fam":"diversity","opt":1},{"p":"Some medical school applicants are already focused on pursuing a particular career pathway in medicine. While many students will change from this pathway during medical school, knowing of your potential interests does help us to assign interviewers. Your choice below does not influence how the Admissions Committee selects students to interview. Please select from one of career pathways listed below. In addition to this selection, please provide a brief description of your future career goals:","limit":400,"unit":"chars","fam":"career"}]},{"name":"UCLA David Geffen School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-california-los-angeles-david-geffen-school-of-medicine.1517801/","prompts":[{"p":"At the David Geffen School of Medicine at UCLA, students are provided with curriculum and experiences enabling them to become an \"Outstanding Physician, AND...,\" dedicating themselves to important societal missions. What missions do you want to embrace? What have you done toward your missions?","limit":800,"unit":"chars","fam":"career"},{"p":"Describe your most unique leadership, entrepreneurial, or creative activity.","limit":800,"unit":"chars","fam":"team"},{"p":"Describe your most important volunteer work and why it was meaningful.","limit":800,"unit":"chars","fam":"service"},{"p":"Describe your most scholarly project (thesis, research or field of study in basic or clinical science or in the humanities) and provide the total number of hours, dates and advisor.","limit":800,"unit":"chars","fam":"career"},{"p":"Describe how the COVID-19 pandemic has impacted your pathway to medical school. Include any academic, personal, financial or professional barriers, as well as other relevant information.","limit":800,"unit":"chars","fam":"challenge"},{"p":"(Optional) Did you transfer from a community college to 4-year college?","limit":800,"unit":"chars","fam":"diversity","opt":1},{"p":"(Optional) Are you a first-generation college graduate? (First generation to college is defined as having parents, guardians, or extended family who have a high school education or less.)","limit":800,"unit":"chars","fam":"diversity","opt":1},{"p":"(Optional) Did you experience or are you anticipating time between graduating from college and matriculating into medical school? If you answered \"Yes\" to question 4, describe the activities in which you participated or are planning to participate. Examples include additional schooling, employment, or caring for a loved one.","limit":800,"unit":"chars","fam":"gap","opt":1},{"p":"(Optional) Do you identify as being part of a group that has been marginalized (examples include, but are not limited to, LGBTQIA, disabilities, federally recognized tribe) in terms of access to education or healthcare? If you answered \"Yes\" to question 5, describe how this inequity has impacted you or your community and how educational disparity, health disparity and/or marginalization has impacted you and your community.","limit":800,"unit":"chars","fam":"diversity","opt":1},{"p":"Please describe how your experience, community and family background impact your understanding of medically underserved/under-resourced communities.","limit":800,"unit":"chars","fam":"service"},{"p":"Other than healthcare access, what are some of the most important health care issues confronting medically underserved/under-resourced and vulnerable communities? How would you address them?","limit":800,"unit":"chars","fam":"service"}]},{"name":"UCSF School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-california-san-francisco-school-of-medicine.1517800/","prompts":[{"p":"If you wish to update or expand upon your activities, you may provide additional information below.","limit":500,"unit":"words","fam":"anything","opt":1},{"p":"If you are 2025 or earlier college graduate, please use the space below to tell us what you have done since completing your undergraduate degree.","limit":350,"unit":"words","fam":"gap"},{"p":"UCSF PRIDE values serve as a guiding light for institutional life and activities. Briefly describe how you will contribute to and support our PRIDE values consistent with your goals or life experience.","limit":500,"unit":"words","fam":"why"}]},{"name":"UMass Chan Medical School","state":"MA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-massachusetts-medical-school.1517827/","prompts":[{"p":"How will your lived experiences, your background, your identity or that which makes you unique contribute to the diverse community and learning environment at UMass Chan?","limit":200,"unit":"words","fam":"diversity"},{"p":"Describe a specific situation in which you persevered through more than usually challenging circumstances. What did you learn from that experience that you have continued to use?","limit":200,"unit":"words","fam":"challenge"},{"p":"Describe your role in a project that identified a problem, studied it, launched a solution and tested its effectiveness.","limit":200,"unit":"words","fam":"team"},{"p":"Describe a situation where you learned something important about yourself that you did not previously know. How did you use that insight to change your approach in the future?","limit":200,"unit":"words","fam":"other"},{"p":"Please describe an example of your personal and/or professional experience with and understanding of systemic inequity, exclusion, or lack of representation in health care in the United States. How did you arrive at this understanding?","limit":200,"unit":"words","fam":"diversity"},{"p":"If you have previously applied to medical school, describe how you have strengthened your candidacy. If you have not previously applied to medical school please enter \"N/A\".","limit":200,"unit":"words","fam":"other"},{"p":"Please discuss any part of your application that you believe requires further explanation such as low grades or scores or gaps in time that are not explained elsewhere.","limit":200,"unit":"words","fam":"anything","opt":1},{"p":"If applying for the PURCH Pathway at Baystate: Please describe how a focus on population health and healthcare disparities will benefit you in your training and/or career?","limit":500,"unit":"words","fam":"career","opt":1},{"p":"If applying for the LEAD@Lahey Pathway at Lahey: Based on your interests and life experiences, please describe how you might be a good fit for the LEAD@Lahey Pathway at UMass Chan Medical School? What unique experiences and perspectives might you bring to the class?","limit":250,"unit":"words","fam":"why","opt":1}]},{"name":"UNC Chapel Hill School of Medicine","state":"NC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-north-carolina-chapel-hill-school-of-medicine.1517838/","prompts":[{"p":"How will your life experiences foster a positive educational environment and benefit your future patients?","limit":250,"unit":"words","fam":"diversity"}]},{"name":"Uniformed Services University","state":"MD","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-uniformed-services-university-of-health-sciences-usuhs.1517789/","prompts":[{"p":"Medicine and Officership are time-honored professions that unite at “America’s Medical School” in rewarding and challenging ways. What are your thoughts and impressions about serving as a uniformed medical corps officer, and why do you want to pursue this career path?","limit":1500,"unit":"chars","fam":"career"},{"p":"The Uniformed Services University features a unique curriculum that prepares students to care for those in harm’s way. Please describe what in your research about our school and its values attracts you to our institution’s mission and approach.","limit":1500,"unit":"chars","fam":"why"},{"p":"Military physicians often navigate uncertain and complex environments. Describe a significant experience where your knowledge or skills were insufficient to address a challenge. What was your approach to the problem? What lessons did you learn?","limit":1500,"unit":"chars","fam":"challenge"}]},{"name":"Universidad Central del Caribe School of Medicine","state":"PR","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-universidad-central-del-caribe-school-of-medicine.1517790/","prompts":[],"none":"No prompts posted yet"},{"name":"University at Buffalo Jacobs School of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-buffalo-jacobs-school-of-medicine.1517795/","prompts":[{"p":"If your parents DO NOT work in a health care field, please list their occupation.","limit":1000,"unit":"chars","fam":"other","opt":1},{"p":"If you or your parents are active military, please describe below:","limit":5000,"unit":"chars","fam":"other","opt":1},{"p":"If you have participated in any educational program sponsored by our medical school, please list programs and dates.","limit":5000,"unit":"chars","fam":"other","opt":1},{"p":"The Jacobs School of Medicine recognizes the many options you have in choosing medical schools in which to apply. Using personal experiences or connections, in 300 words or less, explain how Western New York and/or the Jacobs School align with your values, making it a place you feel would be a good fit for you to not only complete your medical education but continue your career.","limit":300,"unit":"words","fam":"why"},{"p":"In 300 words or less, please describe a time when you observed someone being marginalized whether through a subtle remark, a dismissive comment or their perspective being overlooked. How did you respond in the moment and what informed your decision-making? How has this experience influenced your commitment to an inclusive learning environment in medical school?","limit":300,"unit":"words","fam":"diversity"},{"p":"In 300 words or less, please describe a clinical encounter that challenged your assumptions.","limit":300,"unit":"words","fam":"other"}]},{"name":"University of Alabama at Birmingham Heersink School of Medicine","state":"AL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-alabama-birmingham-heersink.1518238/","prompts":[{"p":"If you are not a resident of Alabama, please describe any ties or meaningful experiences you have had related to the state of Alabama or UAB Medical Center.","limit":0,"unit":"words","fam":"why"},{"p":"If the area you spent most of your life before college differs from where you currently consider your permanent address, please explain.","limit":0,"unit":"words","fam":"other"},{"p":"Where do you see yourself in your medical career fifteen to twenty years from now?","limit":750,"unit":"chars","fam":"career"},{"p":"Describe a patient interaction with the healthcare system.","limit":750,"unit":"chars","fam":"other"},{"p":"Describe a fulfilling or challenging community service experience and how you grew personally from the experience. Examples of community service include, but are not limited to, face-to-face activities volunteering in a healthcare setting, nursing home, school, crisis center, food bank, or shelter.","limit":750,"unit":"chars","fam":"service"},{"p":"Describe a situation where you had to adjust your behavior or response based on new information or changing conditions.","limit":750,"unit":"chars","fam":"other"},{"p":"Please share any information you want us to know about you that is not included in your AMCAS application or in this secondary application (e.g., provide an explanation of any gaps in education or work or poor academic performance, a meaningful leadership or community service experience tied to healthcare).","limit":0,"unit":"words","fam":"anything","opt":1}]},{"name":"University of Arizona College of Medicine, Phoenix","state":"AZ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-arizona-college-of-medicine-phoenix.1517792/","prompts":[{"p":"[IMPACT] What about yourself are you most proud of? How will this shape the way you care for others and contribute to the well-being of the communities you serve?","limit":1000,"unit":"chars","fam":"other"},{"p":"[SERVICE] Servant Leadership is a core value and attribute we deem essential for our students to possess. Share an example where you took initiative to support others while putting their needs ahead of your own. What personal values guided your actions, and how will those values shape the way you care for patients?","limit":1000,"unit":"chars","fam":"service"},{"p":"[ARIZONA] One of the core missions of the UA College of Medicine – Phoenix is to train physicians who will serve the people and communities of Arizona. Please share your connection to the state or, if you do not have one, what draws you to care for patients here. How do you envision contributing to the health and well-being of Arizona’s communities as a future physician?","limit":1000,"unit":"chars","fam":"why"},{"p":"[RESILIENCE] If you previously applied to any medical school (submitted a primary or secondary application), please reflect on your prior application and indicate in what ways you have grown personally, academically, and professionally. How do these changes make you a stronger applicant this cycle?","limit":1000,"unit":"chars","fam":"other"}]},{"name":"University of Arizona College of Medicine, Tucson","state":"AZ","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-arizona-college-of-medicine-tucson.1517793/","prompts":[],"none":"No written essays reported"},{"name":"University of Arkansas for Medical Sciences College of Medicine","state":"AR","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-arkansas.1518239/","prompts":[],"none":"No prompts posted yet"},{"name":"University of Central Florida College of Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-central-florida-college-of-medicine.1517803/","prompts":[{"p":"Medical school demands significant personal sacrifices, including long hours, emotional stress, and sometimes compromising personal time. Can you describe how you have prepared yourself for these sacrifices and how you plan to maintain a healthy work-life balance while managing the responsibilities of a medical student?","limit":750,"unit":"chars","fam":"other"},{"p":"Can you please recount an experience from your academic or personal life where you actively collaborated with others to achieve a common goal? How do you anticipate applying this collaborative approach in your future medical education and practice, taking into account the diverse perspectives and expertise within healthcare teams?","limit":750,"unit":"chars","fam":"team"},{"p":"We often hear that students want to pursue medicine to help people. Why did you choose medicine and not some other field where you can help others, such as nursing, physical therapy, pharmacology, psychology, education, or social work?","limit":750,"unit":"chars","fam":"other"},{"p":"Tell us about something that is integral to understanding who you are as a person that we would not automatically know from reading your application. These may be things like qualities, characteristics, or events you feel are unique to your life experience. You could address personally important and/or challenging experiences in your background that have influenced your goals and preparation for a career in medicine and service to others. These may include experiences such as the quality of your early educational environment, socioeconomic status, cultural background, or other significant events or circumstances that you feel have shaped your character and defined you as an individual.","limit":4000,"unit":"chars","fam":"diversity"},{"p":"Please share with the Admissions Committee why you are specifically interested in UCF COM.","limit":500,"unit":"chars","fam":"why"},{"p":"In this space, please briefly describe what you have done to improve your candidacy.","limit":0,"unit":"words","fam":"other","opt":1,"group":"Reapplicants only"},{"p":"Will you be a Florida Resident for tuition purposes at the time of matriculation? If you have claimed another state of residence on your AMCAS application, please review the Florida statute section 1009.21 and the State University System of Florida Board of Governors Regulation 7.005 to confirm you will be eligible to classify as a Florida resident for tuition purposes prior to selecting “yes”. If you are NOT a Florida resident, please describe any connection to UCF COM, UCF, or Florida.","limit":0,"unit":"words","fam":"why"},{"p":"Are you currently enrolled in an academic program? If you do not expect to spend the academic year enrolled in an academic program, please explain how you will use this time.","limit":0,"unit":"words","fam":"gap"}]},{"name":"University of Chicago Pritzker School of Medicine","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-chicago-pritzker-school-of-medicine.1517802/","prompts":[{"p":"Students at the Pritzker School of Medicine complete the majority of their clinical training at UChicago Medicine (UCM). UCM, nationally recognized by the AAMC for sustained commitment to community engagement, partnership, and collaboration, has a primary service area where poverty is over double the state level. Additionally, our students lead numerous community-based initiatives throughout Chicago, including six free clinics that primarily serve uninsured patients. Please share with us the personal and professional experiences that have best prepared you to work in this clinical environment.","limit":450,"unit":"words","fam":"service"},{"p":"All MD students participate in our longitudinal Scholarship & Discovery research program, which offers protected curricular time, mentoring, and funding for students to pursue their scholarly interests. Please describe your research interests and share how our research opportunities will help you advance your career goals.","limit":450,"unit":"words","fam":"career"},{"p":"Medical education requires humility and resilience as students learn to become physicians prepared to deliver exceptional care within a rapidly changing and sometimes challenging healthcare landscape. Share with us a difficult or challenging situation you have encountered and how you dealt with it. In your response, identify both the coping skills you called upon to resolve the situation, and the support person(s) from whom you sought advice.","limit":450,"unit":"words","fam":"challenge"},{"p":"Please feel free to use this space to convey any additional information that you might wish the Committee to know. For example, if you are not currently completing a degree, please share your planned or current activities for this application cycle. We suggest that you limit your text to about 300 words.","limit":300,"unit":"words","fam":"anything"},{"p":"If your school has a premedical committee or premedical advisor who composes a letter for each applicant from your school and you chose not to avail yourself of this service, please provide an explanation in the text box below for your decision not to do so. We suggest that you limit your text to about 200 words.","limit":200,"unit":"words","fam":"other"}]},{"name":"University of Cincinnati College of Medicine","state":"OH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-cincinnati-college-of-medicine.1517804/","prompts":[{"p":"Have you ever been subject to any institutional action- such as discipline, probation, suspension, dismissal, or any other sanction- by any college, university or medical school for unacceptable academic performance or a conduct violation, even if the action may did not interrupt your enrollment or require withdrawal? If 'Yes' please explain fully in the space below.","limit":750,"unit":"chars","fam":"other"},{"p":"Have you ever participated in a pre-conviction program, or been convicted of a felony or other criminal offense, or pled guilty or no contest to such an offense? Please include all instances, even if charges were dropped, dismissed, or otherwise resolved. If yes, please explain below.","limit":750,"unit":"chars","fam":"other"},{"p":"Have you ever been convicted of, or pled guilty or no contest to, any moving traffic violation (including speeding violations)? If yes, please explain below. Please include all instances, even if charges were later dropped, dismissed, or otherwise resolved.","limit":750,"unit":"chars","fam":"other"},{"p":"Are you a UCCOM re-applicant? Explain how you and your application have changed since your previous submission, and tell us what you have learned along the way. You may answer N/A if not a re-applicant.","limit":2000,"unit":"chars","fam":"other"},{"p":"Discuss any elements of your application that you feel might be concerning to the Admissions Committee. (This could include explanation of metric trends, institutional actions, legal violations, etc.). You may answer N/A if there are no concerns you would like to discuss.","limit":2000,"unit":"chars","fam":"anything"},{"p":"Describe your interest in the University of Cincinnati College of Medicine. Which opportunities or resources would you pursue as a student, and why are they important to your goals?","limit":2000,"unit":"chars","fam":"why"},{"p":"Do you have any ties to the greater Cincinnati region and/or other areas of Ohio? Please describe. Examples may include personal, academic, professional/service, community, or other meaningful connections","limit":2000,"unit":"chars","fam":"why"},{"p":"Please summarize your past research experience(s). Discuss your role and contributions to the project(s). Explain how these experience(s) have prepared you for a career as a physician-scientist.","limit":4000,"unit":"chars","fam":"career"},{"p":"Please discuss your motivation and goals for joining an MD/PhD program. Elaborate on future career plans and how the University of Cincinnati MSTP will help you achieve those goals.","limit":2000,"unit":"chars","fam":"career"},{"p":"Please discuss your research interests and how these align with the research opportunities provided at the University of Cincinnati/Cincinnati Children’s. Discuss potential MSTP faculty mentors whose research is of interest to you.","limit":2000,"unit":"chars","fam":"career"}]},{"name":"University of Colorado School of Medicine","state":"CO","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-colorado-anschutz-school-of-medicine.1517805/","prompts":[{"p":"The pillars of our curriculum are Leadership, Curiosity, and Commitment. Tell us about how you have embodied one or more of these attributes in your path to medicine thus far. In which of these areas do you see the most opportunity for personal growth and why?","limit":500,"unit":"words","fam":"other"},{"p":"Please describe how your experiences have shaped your approach to creating welcoming, respectful, and collaborative environments for all your future patients.","limit":300,"unit":"words","fam":"diversity"},{"p":"Please explain how you and your application has changed since your previous submission.","limit":1500,"unit":"chars","fam":"other","opt":1},{"p":"Please tell us why you are interested in being a part of the 4-year CUSOM at CSU (Fort Collins Branch campus)? With the background that FCB’s smaller class sizes and unique structure lead to a highly interactive curriculum, please tell us how this campus matches your learning style and personal philosophy.","limit":1500,"unit":"chars","fam":"why","opt":1,"group":"Optional: choose 1 branch/pathway program"},{"p":"The CS LIC Program exists at the intersection of academic and community medicine. CS LIC students experience the myriad of academic, private, corporate, military, non-profit, and public service organizations that come together to care for a community. Clinical, didactic, and project-based learning emphasizes how physician leadership and community engagement can promote the health of communities. Didactic education is based in Colorado Springs with clinical sites spanning small cities along the Southern Front Range including Pueblo, Cañon City, Monument, and Woodland Park. Please describe how participation in the CS LIC would advance your career goals and how your life experiences align with an interest in our program. If applicable, you may also note any ties to Colorado Springs or the Southern Front Range.","limit":1500,"unit":"chars","fam":"why","opt":1,"group":"Optional: choose 1 branch/pathway program"},{"p":"Why are you interested in being a rural physician? How will rural life and work fit your personal and professional goals? You may include your past experiences and ties or interest to rural Colorado.","limit":1500,"unit":"chars","fam":"career","opt":1,"group":"Optional: choose 1 branch/pathway program"},{"p":"What has led you to commit to a career in rural family medicine? Please describe any life experiences that have contributed to this commitment. As a rural family physician, describe the impact you will make on your community.","limit":500,"unit":"words","fam":"career","opt":1,"group":"Optional: choose 1 of 5 accelerated programs (4 posted)"},{"p":"What has led you to commit to a career in urban primary care? Please describe any life experiences that have contributed to this commitment. As an urban primary care physician, describe the impact you will make on your community.","limit":500,"unit":"words","fam":"career","opt":1,"group":"Optional: choose 1 of 5 accelerated programs (4 posted)"},{"p":"What has led you to commit to a career in infectious diseases and public health? Please describe any life experiences that have contributed to this commitment. As an infectious diseases physician, describe the impact you will make on your community.","limit":500,"unit":"words","fam":"career","opt":1,"group":"Optional: choose 1 of 5 accelerated programs (4 posted)"},{"p":"What has led you to commit to a career in pediatrics? Please describe any life experiences that have contributed to this commitment. As a pediatrician, describe the impact you will make on your community.","limit":500,"unit":"words","fam":"career","opt":1,"group":"Optional: choose 1 of 5 accelerated programs (4 posted)"},{"p":"Combined MD-MS (Aerospace Engineering): CUSOM has joined with the Department of Aerospace Engineering Sciences at CU Boulder to offer a combined MD-MS degree program. The goal of this program is to prepare trainees to lead the next generation of human spaceflight in clinical, research, engineering, and programmatic positions. The 5-year curriculum includes spending one year at CU Boulder obtaining an MS in Aerospace Engineering with a focus on bioastronautics. Participants can also elect to complete an MS thesis or develop more hands-on engineering experience via Graduate Projects courses. Describe your career path up to this point and how that has led to your interest in human spaceflight. What is your motivation for seeking a dual degree in Aerospace Engineering and how does this fit into your vision for your career?","limit":1500,"unit":"chars","fam":"career","opt":1},{"p":"CUSOM has partnered with the Leeds School of Business at CU Boulder to offer a combined MD-MBA degree program. The goal of this program is to prepare trainees to lead innovation and progress at the intersection of medicine and business. Please answer the following question with a limit of 750 words. What are your career aspirations and professional development goals for your studies in the MBA program, and why is Leeds your choice? How will your background, values, academics, and leadership skills enhance the experiences of your fellow MBA students during your studies? In what ways do your core values guide your approach to leadership?","limit":750,"unit":"words","fam":"career","opt":1},{"p":"Public health is both a science and a calling, requiring practitioners to bridge the gap between clinical medicine and population-level health improvement. As a medical student applying to the Master of Public Health program, write a statement, reflecting on the following: What inspired you to pursue an MPH degree in addition to your medical training? What public health issue or field (e.g., epidemiology, health systems, management and policy, climate and environmental health, biostatistics, community and behavioral health, etc.) are you most passionate about? How does the chosen public health field align with your personal and professional goals?","limit":5000,"unit":"chars","fam":"career","opt":1}]},{"name":"University of Connecticut School of Medicine","state":"CT","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-connecticut-school-of-medicine.1517806/","prompts":[{"p":"Highlight your experiences in the health care field. What insights have you gained about potential problems you will face as a physician?","limit":1800,"unit":"chars","fam":"other"},{"p":"How will the University of Connecticut School of Medicine best serve your needs of becoming a physician or physician scientist?","limit":1800,"unit":"chars","fam":"why"},{"p":"The Univeristy of Connecticut School Of Medicine realizes that each applicant brings a unique perspective from a broad range of experiences that have been influential in leading to a career in medicine. How will your own life experiences and unique identity enhance the UConn SoM classroom and community?","limit":1800,"unit":"chars","fam":"diversity"},{"p":"Have you participated in any outreach activities or summer programs at UConn Health? If not, how did you learn about the University of Connecticut School of Medicine? Please list any activities/exposure and approximate time of engagement.","limit":1800,"unit":"chars","fam":"other"}]},{"name":"University of Florida College of Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-florida-college-of-medicine.1517807/","prompts":[{"p":"Non-Florida residents, please describe your association with the state of Florida if you selected Other above. For all other selections, feel free to expand your answer here as well.","limit":0,"unit":"words","fam":"why","opt":1},{"p":"If you are not a full-time student during this application cycle, in particular at any time between July 2026 and July 2027, please detail your current and planned activities below. If your plans are not confirmed or if they change, please update us later in the cycle via the User Profile: Updates section.","limit":500,"unit":"words","fam":"gap"},{"p":"Please consider the following optional question: Reflect upon your life experiences and values. Do any or all of these help frame how you envision your future contributions to the health and wellbeing of others as a physician and if so, how?","limit":250,"unit":"words","fam":"diversity","opt":1},{"p":"If you are a reapplicant to UF COM, please briefly describe your approach to preparing for a new application and specific changes from your previous application.","limit":500,"unit":"words","fam":"other"},{"p":"This question is for those who applied via AMCAS (\"Other Special Program\") to the Jacksonville clerkship track only: The Jacksonville regional medical school campus seeks individuals with an interest in practicing in underserved communities. The program aims to supplement UFCOM's core medical education with clinical, research, and other experiences designed to provide in-depth, longitudinal learning opportunities in addressing social determinants of health, engaging community resources, and improving population health outcomes. Please tell us about your interests and experiences that motivate you to apply to this program. Please limit your response to 250-500 words.","limit":500,"unit":"words","fam":"service"},{"p":"The medical profession is frequently described as being both a science and an art. One could summarize this by saying that patients must “be well cared for” (science) but they must also “feel well cared for” (art). … Please download here two such reflections from our third-year students, each describing interactions where they grew and learned while they were caring for patients. Read and reflect on both and then choose one and describe how the writer, in the words of Dr. Griffin, deepened self-understanding and increased their humanity.","limit":525,"unit":"words","fam":"other","group":"Choose 1 of 2 reflections","cut":1},{"p":"What does it mean to be present for the patient? Describe an interaction you've witnessed in which the physician or other health care professional was fully (or not fully) present for the patient. How has this shaped your understanding of what it means to care for another person in medicine?","limit":525,"unit":"words","fam":"other"},{"p":"Optional: If you think there is any additional information that would help the admissions committee in its review of your application, please use the space below.","limit":5000,"unit":"chars","fam":"anything","opt":1}]},{"name":"University of Georgia School of Medicine","state":"GA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-georgia-at-athens.1517810/","prompts":[{"p":"What draws you to the University of Georgia School of Medicine, and in what ways have your experiences prepared you to contribute to and serve communities across Georgia?","limit":300,"unit":"words","fam":"why"},{"p":"Imagine you’ve reached the end of a fulfilling and impactful career. A trusted colleague or mentee is delivering a speech in your honor at a celebration of your professional life. What would you want them to say about the kind of work you did, the values you embodied, the relationships you built, and the legacy you left behind? Take this opportunity to reflect on the career you aspire to build and how you want it to be remembered.","limit":300,"unit":"words","fam":"career"},{"p":"Tell us about the decisions and experiences that have defined your academic journey. This space is for you to provide context for any element of your academic history that you believe would help us better understand your path, persistence, and personal growth. For example, you may want to discuss the reasoning behind a significant change in major or a shift in academic interest, provide context for any course withdrawals or changes in your academic performance, or explain a unique academic timeline like attending multiple institutions or taking a gap year. You can also use this opportunity to describe your approach to improving a standardized test score after an initial attempt.","limit":300,"unit":"words","fam":"other"},{"p":"What are the core values that guide you? Describe a time when those values were challenged, either by circumstances or by encountering someone whose perspectives differed from your own. How did you respond, and what did you learn about yourself in the process? In what ways does this experience reflect how you will contribute to the UGA School of Medicine and the profession of medicine?","limit":300,"unit":"words","fam":"challenge"},{"p":"If you are a reapplicant, use this space to highlight aspects of your application that have changed since your last application.","limit":300,"unit":"words","fam":"other","opt":1}]},{"name":"University of Hawaii John A. Burns School of Medicine","state":"HI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-hawaii-john-a-burns-school-of-medicine.1517812/","prompts":[{"p":"Reflect on a recent instance where you were given personal feedback that was unfavorable or difficult to receive. How did you respond? Elaborate on how this experience has shaped the way in which you interact with others.","limit":600,"unit":"words","fam":"challenge"},{"p":"How are you currently serving your community? Describe the impact that you are making and how this has improved your community.","limit":500,"unit":"words","fam":"service"},{"p":"Professionalism in medicine often requires balancing personal beliefs with the duty of care, or navigating conflicts within a healthcare team. Describe a specific instance where your professional integrity or boundaries were challenged. How did you handle it, what was the outcome and how did this experience shape your definition of what it means to be a professional physician?","limit":500,"unit":"words","fam":"ethics"},{"p":"Describe why you have chosen to apply to JABSOM and if you have any personal connections to the school, Hawaii or the Pacific Basin. If you do not have a personal connection, elaborate on your motivations for applying to JABSOM.","limit":500,"unit":"words","fam":"why"},{"p":"(for reapplicants) If you are a re-applicant to JABSOM, please complete the following additional essay. Elaborate on the specific steps you have taken to enhance your candidacy for the MD program and why you chose to take these steps.","limit":500,"unit":"words","fam":"other","opt":1,"group":"Reapplicants only"}]},{"name":"University of Houston Fertitta Family College of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-houston-fertitta-family-college-of-medicine.1517813/","prompts":[{"p":"Why are you interested in the primary care field(s) and care of the community as a whole?","limit":2500,"unit":"chars","fam":"career"}]},{"name":"University of Illinois College of Medicine","state":"IL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-illinois-college-of-medicine.1517814/","prompts":[{"p":"What characteristics, qualities, or attributes do you possess that have helped you navigate conflict, change, or unfamiliar situations? In your response, reflect on how you demonstrate resiliency and a growth mindset in your approach to personal and professional development.","limit":0,"unit":"words","fam":"challenge"},{"p":"Which characteristics, qualities, or attributes of UI COM attracted you to apply for medical school here?","limit":0,"unit":"words","fam":"why"},{"p":"An important part of UI COM’s identity is the concept of “one college, three campuses.” The curriculum is identical on each campus; however, each campus has unique characteristics. Please describe what you have learned about at least two of our three campuses.","limit":0,"unit":"words","fam":"why"},{"p":"Injustice can take many forms and impact individuals and communities in profound ways. Reflect on some of the causes and consequences of injustice you have observed or learned about. What does an individual's response to injustice reveal about their values and character? How do you see your role—as a future physician and member of society—in recognizing and addressing injustice when you encounter it?","limit":0,"unit":"words","fam":"ethics"},{"p":"UI COM thrives when students bring a variety of perspectives, values, and ways of thinking to the learning environment. Describe an aspect of your perspective, value system, or experience that is especially meaningful to you. How would this shape your contribution to a collaborative and enriching learning environment at our medical school?","limit":0,"unit":"words","fam":"diversity"}]},{"name":"University of Iowa Carver College of Medicine","state":"IA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-iowa-carver-college-of-medicine.1517815/","prompts":[{"p":"We understand you may be applying to multiple medical schools. Please explain your reasons for applying to the Carver College of Medicine.","limit":1500,"unit":"chars","fam":"why"},{"p":"Describe a personal characteristic, challenge, or experience that makes you unique. How will this influence your contribution to a dynamic healthcare system that advocates for all peoples?","limit":1500,"unit":"chars","fam":"diversity"},{"p":"Please list and briefly describe all medically related experiences (paid/volunteer) you have completed during the past 5 years. Do NOT forecast future hours. Please include experiences listed on your AMCAS and also provide any additional experiences NOT listed on your AMCAS.","limit":175,"unit":"chars","fam":"other","group":"Up to 15 entries, 175 characters per description"},{"p":"If you are a reapplicant to the Carver College of Medicine, how have you strengthened your application?","limit":1500,"unit":"chars","fam":"other","opt":1},{"p":"If you are not currently in a degree-seeking program, please indicate what you will be doing from the time you complete this secondary application to the start of medical school.","limit":1500,"unit":"chars","fam":"gap","opt":1}]},{"name":"University of Kansas School of Medicine","state":"KS","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-kansas-school-of-medicine.1517816/","prompts":[{"p":"If you are not a Kansas resident, what is your specific interest in applying to the University of Kansas School of Medicine?","limit":0,"unit":"words","fam":"why"},{"p":"Please describe how your actions and experiences align with the vision statement of the University of Kansas School of Medicine: To improve lives and communities in Kansas through innovation in education, research, and health care.","limit":0,"unit":"words","fam":"why"},{"p":"Describe your health care experiences that involved direct exposure to physicians' clinical duties and how they have shaped your desire to apply to medical school.","limit":0,"unit":"words","fam":"other"},{"p":"Describe examples of leadership experience in which you have significantly influenced others, helped resolve disputes, or contributed to group efforts over time.","limit":0,"unit":"words","fam":"team"},{"p":"Beyond academics (grades and MCATs), describe the most significant challenge you have faced and the steps you have taken to address this challenge.","limit":0,"unit":"words","fam":"challenge"},{"p":"Give an example of what you have done to make your community a better place to live.","limit":0,"unit":"words","fam":"service"},{"p":"If there are academic discrepancies in your application that have not been explained in your application, use this space to clarify. Examples may include unexplained gaps in time, multiple undergraduate institutions attended, multiple course withdrawals, inconsistent academic performance, inconsistency between academic performance and MCAT scores.","limit":0,"unit":"words","fam":"anything"},{"p":"(if you answer \"no\" to the being a full time student question) Briefly describe your current employment, community, medical, and/or educational activities.","limit":0,"unit":"words","fam":"gap"}]},{"name":"University of Kentucky College of Medicine","state":"KY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-kentucky-college-of-medicine.1517825/","prompts":[{"p":"Why have you chosen to apply to the University of Kentucky College of Medicine? The University of Kentucky College of Medicine's (UKCOM) mission statement promotes an environment that encourages excellence in education, access to high-quality health care, and transformative research to improve the health and wellness of Kentuckians and beyond. Please describe how your past experiences or future plans contribute to enriching and enhancing the learning environment at UKCOM.","limit":0,"unit":"words","fam":"why"},{"p":"If you are a non Kentucky resident, you are required to elaborate on your Kentucky ties if applicable (personal, familial e.g.)","limit":0,"unit":"words","fam":"why"},{"p":"Your combination of life experiences make you uniquely you. Talk about one such experience and how it has helped you prepare to be a physician.","limit":0,"unit":"words","fam":"diversity"},{"p":"Describe an experience or situation which made you feel grateful?","limit":0,"unit":"words","fam":"other"},{"p":"Please share unique, personally important, and/or challenging facts in your life and/or work experiences. Please discuss how such factors have influenced your goals and preparation for a career in medicine.","limit":0,"unit":"words","fam":"challenge"},{"p":"Describe a situation where you were not in the majority.","limit":0,"unit":"words","fam":"diversity"},{"p":"Please elaborate on why this is your preferred campus.","limit":0,"unit":"words","fam":"why"}]},{"name":"University of Louisville School of Medicine","state":"KY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-louisville.1518240/","prompts":[{"p":"Why have you chosen to apply to the University of Louisville School of Medicine?","limit":150,"unit":"words","fam":"why"},{"p":"Describe any additional experiences, interests, hobbies, or skills not included in other areas of your application or that you have completed since submitting your AMCAS application.","limit":150,"unit":"words","fam":"anything"},{"p":"If you are a reapplicant, what has changed from your previous application or your approach to this year's admissions cycle?","limit":150,"unit":"words","fam":"other","opt":1},{"p":"What has been your most significant contribution to your community, through service or volunteerism? What was its impact on the community and on you?","limit":150,"unit":"words","fam":"service"},{"p":"The University of Louisville School of Medicine's mission is to improve the health and vitality of our community, our commonwealth, and our world by educating the next generation of physicians and scientists. This mission includes caring for underserved areas of Kentucky. Describe how your experiences and attributes equip you to care for underserved communities.","limit":150,"unit":"words","fam":"service"},{"p":"Which areas of medical practice are you interested in pursuing during residency? How do you see yourself practicing medicine after residency training, including location?","limit":150,"unit":"words","fam":"career"},{"p":"Is there any context for your undergraduate years that would help the committee to understand your academic performance? For example, students who come from rural areas, who worked long hours in paid employment during college, or who are first generation college graduates may not have the same access to opportunities and support as students from other environments.","limit":150,"unit":"words","fam":"challenge"}]},{"name":"University of Maryland School of Medicine","state":"MD","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-maryland-school-of-medicine.1517826/","prompts":[{"p":"Describe here the reason why you are specifically interested in attending the University of Maryland School of Medicine.","limit":1000,"unit":"chars","fam":"why"},{"p":"Please describe what you will be doing during the 2026-2027 academic year. If you graduated/will graduate in 2026, what are your plans for the coming year until you matriculate to medical school?","limit":1000,"unit":"chars","fam":"gap"},{"p":"(Optional) If you’ve experienced academic challenges while in college and/or graduate or professional school, please describe and explain below. Please be sure to include withdrawals, incompletes, poor grades, etc.","limit":1000,"unit":"chars","fam":"challenge","opt":1},{"p":"Briefly describe your most meaningful exposure to clinical medicine.","limit":1500,"unit":"chars","fam":"other"},{"p":"(Optional) Please share any relevant characteristic about your background and/or experiences not already described in AMCAS you feel may positively impact how you practice medicine in the future.","limit":400,"unit":"chars","fam":"diversity","opt":1},{"p":"Briefly describe your most satisfying experience related to community service.","limit":1500,"unit":"chars","fam":"service"},{"p":"How does our School of Medicine mission, vision, and values align with your vision for your future career as a physician?","limit":1500,"unit":"chars","fam":"why"},{"p":"What does it mean to you to enter into a profession?","limit":1500,"unit":"chars","fam":"other"}]},{"name":"University of Miami Miller School of Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-miami-miller-school-of-medicine.1517828/","prompts":[{"p":"If you have submitted an AMCAS application to the University of Miami Miller School of Medicine before we invite you to use this space to provide additional information about your previous application. This can include year(s) applied, outcome of application, and ways you have strengthened your application since your last application. [Leave blank if this does not apply]","limit":0,"unit":"words","fam":"other","opt":1},{"p":"Use the space below if you would like to share information about a family member who is a graduate of one of our Miller SOM educational or residency programs or who is a current faculty or staff member. This information could include the name of the family member, program(s) they are/were affiliated with, (if alumni) graduation year, and how this family member's experience with the University of Miller SOM shaped your career trajectory or has otherwise impacted your decision to apply to our program. [Leave blank if this does not apply]","limit":0,"unit":"words","fam":"other","opt":1},{"p":"Why are you applying to the University of Miami Leonard M. Miller School of Medicine? In your essay, please provide a response that clearly articulates how you believe our program specifically will enhance your education/training, what you feel you will uniquely contribute to our learning community, and/or what features of our medical school prompted you to apply.","limit":0,"unit":"words","fam":"why"},{"p":"In the space below, please discuss any experiences you may have had serving, working, living, and/or learning in broadly diverse environments that you believe would enable you to thrive in and contribute to our Miller SOM and Greater Miami community.","limit":0,"unit":"words","fam":"diversity"},{"p":"In the space below, we invite you to choose one of our #MedCanes values and discuss how you exemplify that value. -Integrity: Demonstrating honesty and fairness in our words and actions -Collaboration: Working together in teams to achieve common goals -Accountability: Taking ownership and responsibility for our actions and outcomes -Respect: Treating others with dignity and compassion -Excellence: Giving of ourselves in a way that exceeds expectations","limit":0,"unit":"words","fam":"other","group":"Choose 1 of 5 values"},{"p":"Use the space below if you would like to briefly discuss anything else that you want the Admissions Committee to know that you feel has not been covered in your primary and secondary applications.","limit":0,"unit":"words","fam":"anything","opt":1}]},{"name":"University of Michigan Medical School","state":"MI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-michigan-medical-school.1517829/","prompts":[{"p":"How do you hope to impact medicine and improve patient care in the future? Why do you need a medical degree to fulfill these goals?","limit":1500,"unit":"chars","fam":"career"},{"p":"Please describe the impact of your identity and experiences on your growth and development, and how it may impact your career as a physician.","limit":1500,"unit":"chars","fam":"diversity"},{"p":"The University of Michigan Medical School strives to be a place of empowerment, advocacy and change in health care. What experiences have you had in empowerment and advocacy for others that would help to advance this mission?","limit":1500,"unit":"chars","fam":"service"},{"p":"Outside of medicine, and beyond what we can read in your application, tell us what you are curious about or what you have chosen to explore.","limit":1500,"unit":"chars","fam":"other"}]},{"name":"University of Minnesota Medical School","state":"MN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-minnesota-medical-school.1517831/","prompts":[{"p":"Please select one of these pillars that resonates most deeply with your journey. Describe a specific experience where you demonstrated this value in action and explain how that experience has prepared you to enhance the health of Minnesotans.","limit":1500,"unit":"chars","fam":"other","group":"General Mission applicants; choose 1 pillar"},{"p":"Please highlight up to 3 experiences that support your application to the Rural Health Mission.","limit":1500,"unit":"chars","fam":"why","group":"Rural Health Mission applicants"},{"p":"Describe an experience where you demonstrated leadership by adapting to a resource-limited or culturally distinct environment.","limit":1500,"unit":"chars","fam":"team","group":"Rural Health Mission applicants"},{"p":"How would you contribute to a learning environment that respects and supports individuals with a wide range of identities, perspectives, and life experiences? Please share specific examples from your professional and/or personal background that demonstrate your ability to work effectively with people from varied communities.","limit":1500,"unit":"chars","fam":"diversity"},{"p":"Describe a time when you received significant constructive feedback or encountered a setback that challenged your perception of your abilities. How did you respond to this situation, and how has this experience changed your approach to learning and self-improvement?","limit":1500,"unit":"chars","fam":"challenge"},{"p":"Considering the University of Minnesota Medical School’s mission and strengths, why is this specific geographic and clinical environment the right place for your medical education?","limit":1500,"unit":"chars","fam":"why"},{"p":"(Optional) Is there any additional information you would like the Admissions Committee to know that was not covered elsewhere in your application or recent experiences not included in your AMCAS submission?","limit":1500,"unit":"chars","fam":"anything","opt":1}]},{"name":"University of Mississippi School of Medicine","state":"MS","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-mississippi-school-of-medicine.1517830/","prompts":[],"none":"No prompts posted yet"},{"name":"University of Missouri School of Medicine, Columbia","state":"MO","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-missouri-columbia.1517832/","prompts":[{"p":"Why are you interested in attending the University of Missouri School of Medicine?","limit":3000,"unit":"chars","fam":"why"},{"p":"Is there anything that was not fully address in your application and/or any additional updates since submitting the AMCAS application?","limit":3000,"unit":"chars","fam":"anything"}]},{"name":"University of Missouri-Kansas City School of Medicine","state":"MO","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-missouri-kansas-city.1517833/","prompts":[],"none":"No prompts posted yet"},{"name":"University of Nebraska College of Medicine","state":"NE","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-nebraska-college-of-medicine.1517834/","prompts":[],"none":"No prompts posted yet"},{"name":"University of Nevada, Reno School of Medicine","state":"NV","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-nevada-reno.1517836/","prompts":[{"p":"Please share why you want to pursue your medical education at the University of Nevada, Reno School of Medicine; describe any connections to Northern Nevada communities; and how you are prepared to contribute to UNR Med’s vision of a Healthy Nevada.","limit":300,"unit":"words","fam":"why"},{"p":"Describe a time when you were part of a team that was struggling to meet objectives. How did you react? What would you do differently? What did you take away from this experience that will influence your approach to working on a team in the future?","limit":300,"unit":"words","fam":"team"},{"p":"Reflect on and describe an experience where you provided care or service to individuals from populations that commonly experience health care disparities. Discuss what you learned about the socio-cultural or economic factors that affect underserved populations and describe how your interactions with these individuals motivated or prepared you for a future in medicine.","limit":300,"unit":"words","fam":"service"},{"p":"Describe a time when you faced a significant life crisis or an academic, personal, or professional failure. How did you respond, what did you learn, and how did the experience influence your future actions?","limit":300,"unit":"words","fam":"challenge"},{"p":"Please share an example of how you have used critical thinking and communication skills to develop a creative or innovative solution to a challenging problem.","limit":300,"unit":"words","fam":"other"},{"p":"You are invited to provide a brief statement regarding anything not previously addressed or disclosed in your application that you would like considered during the review of your application. If you are a re-applicant to UNR Med, we encourage you to outline any significant changes or new experiences from your previous application.","limit":500,"unit":"words","fam":"anything"}]},{"name":"University of New England College of Osteopathic Medicine (UNECOM)","state":"ME","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-new-england-college-of-osteopathic-medicine-unecom.1518504/","prompts":[],"none":"No written essays reported"},{"name":"University of New Mexico School of Medicine","state":"NM","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-new-mexico-school-of-medicine.1517837/","prompts":[{"p":"At the UNM School of Medicine, we are committed to building a community of inclusive learners that will go on to enrich the medical field. Are there any aspects of your experience that you are most proud of or that you feel you have been unable to highlight with your application materials already submitted? If so, please explain how this will contribute to an inclusive learning community and your future medical community.","limit":2000,"unit":"chars","fam":"diversity"},{"p":"What do you see as the most important characteristics of a physician? How do you plan to cultivate them during your training?","limit":2000,"unit":"chars","fam":"other"},{"p":"While providing healthcare as a physician is often a rewarding career, it is also a profession that entails addressing constant challenges. Identify what you think is the most significant issue the medical profession will face in the next 20 years and walk us through the process of solving this problem at a local or national level. Explain your reasoning along the way.","limit":2000,"unit":"chars","fam":"other"},{"p":"Clinical outcomes are often the downstream outcome of broader policies that impact health inequities. What is a public health policy that has impacted the health outcomes of our community for better or worse?","limit":2000,"unit":"chars","fam":"other"},{"p":"Please tell us about a situation in which working with a team was challenging. What was your role? What was challenging? How was it handled? What did you learn?","limit":2000,"unit":"chars","fam":"team"},{"p":"Please describe how COVID-19 has affected your preparation for applying to medical school. Describe any academic, personal, financial, or professional barriers/disruptions that COVID-19 may have triggered.","limit":2000,"unit":"chars","fam":"challenge"}]},{"name":"University of North Dakota School of Medicine","state":"ND","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-north-dakota.1517839/","prompts":[{"p":"The primary purpose of the UND School of Medicine & Health Sciences is to educate physicians and other health professionals for subsequent service in North Dakota and to enhance the quality of life of its people. Please explain how your past medical/clinical and community service experiences and your career goals are consistent with this purpose.","limit":1200,"unit":"chars","fam":"why"},{"p":"Describe an ethical dilemma that presented itself to you. Identify your choices, potential consequences and your resolution of the dilemma. In hindsight, what did you learn about yourself?","limit":1200,"unit":"chars","fam":"ethics"},{"p":"Describe and reflect on a specific experience you have had with people of a different socioeconomic, ethnic, racial, cultural or religious/spiritual background than yourself. What preconceived notions did you have prior to the experience? How did the experience challenge your preconceived notions?","limit":1200,"unit":"chars","fam":"diversity"},{"p":"The UND School of Medicine and Health Sciences invests in the discovery of knowledge that benefits the people of this state and enhances the quality of their lives. Reflect on your personal experience with the process of scientific discovery. What aspect was most frustrating? Most rewarding? How might these lessons be transferable to the practice of medicine?","limit":1200,"unit":"chars","fam":"career"},{"p":"Reflect on an experience in which you demonstrated creativity and innovation where you generated an idea and implemented it to achieve an outcome. Examples may include a musical or theatrical performance, work of art, publication, invention, start-up, public service or any other major production or installation. How did it contribute to your personal growth? What skills did you gain that will help you as a future physician?","limit":1200,"unit":"chars","fam":"other"},{"p":"The UND School of Medicine & Health Sciences is a community-based medical school, and because of the unique circumstances of our regional location, we place special emphasis on the unique skills needed to provide care for patients and populations in rural and Native American communities across all competencies. Reflect on a specific health care disparity affecting rural and/or Native American populations that you may have engaged with or studied and how you, as a future physician, might help to alleviate that disparity.","limit":1200,"unit":"chars","fam":"service"},{"p":"Reflect on your role in a particularly impactful leadership or team experience in which your efforts resulted in a meaningful outcome.","limit":1200,"unit":"chars","fam":"team"},{"p":"UND SMHS REAPPLICANTS ONLY: When was your previous application, and, subsequently, what steps have you taken to strengthen your candidacy? Note any relevant academic, employment, clinical, personal experience, and/or development. If you requested feedback from the Student Affairs & Admissions office regarding a previous application, please list the ways in which you addressed that feedback","limit":0,"unit":"words","fam":"other","opt":1},{"p":"What are your career plans if you do not ever get admitted to medical school?","limit":600,"unit":"chars","fam":"career"},{"p":"If needed, update the information in your AMCAS application (i.e., grades in recent courses, alterations in your proposed coursework or graduation, additions to extracurricular activities, unreported legal and institutional infractions, etc.).","limit":600,"unit":"chars","fam":"anything","opt":1},{"p":"Are you currently enrolled in a grant-funded and/or degree-granting post-baccalaureate program and/or advanced degree? If so, what is your timeline for completion?","limit":600,"unit":"chars","fam":"other","opt":1}]},{"name":"University of North Texas Health Science Center - Texas College of Osteopathic Medicine (UNTHSC-TCOM)","state":"TX","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-unt-health-fort-worth-texas-college-of-osteopathic-medicine-unthsc-tcom.1518505/","prompts":[{"p":"What experiences and/or relationships have motivated you toward a career in osteopathic medicine?","limit":2000,"unit":"chars","fam":"osteo"},{"p":"If you attended more than two colleges/universities, explain why. Community colleges are not needed.","limit":1000,"unit":"chars","fam":"other"},{"p":"If applicable, please update the information contained on your TMDSAS application. Indicate any additional grades earned, alterations in your proposed coursework or graduation date, additions to your extracurricular activities, name change, or anything else you feel the Admissions Committee should know.","limit":1000,"unit":"chars","fam":"other"},{"p":"Do you consider yourself financially disadvantaged? If yes, please explain.","limit":1000,"unit":"chars","fam":"diversity"},{"p":"Do you consider yourself educationally disadvantaged? If yes, please explain.","limit":1000,"unit":"chars","fam":"diversity"},{"p":"One of the values of the University of North Texas System is Courageous Integrity which means one should model exceptional standards and act in the best interest of our community. These behaviors include:\n– Build trust through consistent actions that are honest, transparent, and authentic\n– Provide, accept, and support open and constructive feedback\n– Hold yourself and others accountable for decisions, behaviors, actions, and results\nPlease select a specific instance where you have demonstrated Courageous Integrity and describe how this is indicative of your character","limit":2000,"unit":"chars","fam":"ethics"}]},{"name":"University of Northern Colorado College of Osteopathic Medicine (UNC-COM)","state":"CO","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-northern-colorado-college-of-osteopathic-medicine-unc-com.1518414/","prompts":[],"none":"No prompts posted yet"},{"name":"University of Oklahoma College of Medicine","state":"OK","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-oklahoma-college-of-medicine.1517840/","prompts":[{"p":"What aspects of the OU College of Medicine’s mission, values, curriculum, or community drew you to apply? Describe how your goals, experiences, or interests align with what our institution uniquely offers.","limit":450,"unit":"words","fam":"why"},{"p":"Describe a meaningful experience where you engaged in service, advocacy, community partnership, or work with underserved or marginalized populations. What did you learn about the factors that influence community health, and how will this shape your approach to medicine?","limit":450,"unit":"words","fam":"service"},{"p":"Medical education environments differ in structure, culture, and emphasis. Describe the kind of learning environment in which you believe you will thrive. What combination of experiences, such as community-engaged learning, longitudinal clinical experiences, team-based or interprofessional care, research and scholarly opportunities, population-health initiatives, or exposure to a broad range of clinical settings, will best support your growth as a future physician, and why?","limit":250,"unit":"words","fam":"why"}]},{"name":"University of Pennsylvania Perelman School of Medicine","state":"PA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-pennsylvania-perelman-school-of-medicine.1517841/","prompts":[{"p":"Have you taken or are you planning to take time off between college graduation and medical school matriculation? If yes, please describe your activities during this time.","limit":700,"unit":"chars","fam":"gap"},{"p":"Have you participated in any global activities outside of the U.S. prior to submitting your AMCAS application?","limit":1000,"unit":"chars","fam":"other"},{"p":"How would your life experiences contribute to Perelman? Please explain.","limit":1000,"unit":"chars","fam":"diversity"},{"p":"We all periodically have to make decisions under challenging circumstances. Physicians and physician-scientists sometimes need to proceed and act with limited information. Please describe a time when you faced a situation that was ambiguous, confusing, or uncertain, and how you navigated the matter despite lacking all of the necessary information.","limit":3000,"unit":"chars","fam":"challenge"},{"p":"Have you or your family experienced economic hardships, regardless of current income status?","limit":1000,"unit":"chars","fam":"diversity"},{"p":"Please share your reasons for applying to the Perelman School of Medicine.","limit":1000,"unit":"chars","fam":"why"}]},{"name":"University of Pikeville - Kentucky College of Osteopathic Medicine (KYCOM)","state":"KY","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-pikeville-kentucky-college-of-osteopathic-medicine-kycom.1518506/","prompts":[{"p":"Please describe your experience with osteopathic medicine, such as your care and treatment from a DO and your shadowing experience with a DO (including number of hours). Please describe how your experience has influenced your decision to apply to an osteopathic medical school.","limit":0,"unit":"words","fam":"osteo"}]},{"name":"University of Pittsburgh School of Medicine","state":"PA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-pittsburgh-school-of-medicine.1517842/","prompts":[{"p":"How do you see yourself fitting into our curriculum, given your personality traits and learning style? What aspects do you expect will come naturally to you, and what challenges do you anticipate?","limit":250,"unit":"words","fam":"why"},{"p":"Tell us about a challenging situation in which a belief or assumption you made was challenged by new evidence or experience. How did you respond in the moment, and what did you do afterward?","limit":250,"unit":"words","fam":"challenge"},{"p":"Respect for others and the ability to empathize with people from different backgrounds are integral to the successful practice of medicine. Describe a situation you observed that illustrates the impact of respect and empathy. What did you learn from this experience, and how has it influenced the type of physician you aspire to become?","limit":250,"unit":"words","fam":"diversity"},{"p":"If you wish, use this space to tell the UPSOM Admissions Committee anything else about yourself.","limit":250,"unit":"words","fam":"anything","opt":1}]},{"name":"University of Puerto Rico School of Medicine","state":"PR","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-puerto-rico-school-of-medicine.1517843/","prompts":[],"none":"No prompts posted yet"},{"name":"University of Rochester School of Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-rochester-school-of-medicine.1517844/","prompts":[{"p":"If you previously applied to medical school, briefly describe any experiences you have been part of since your previous application.","limit":200,"unit":"words","fam":"other","opt":1},{"p":"Community involvement is a pillar of medical education at the University of Rochester. Describe a community you identify with, how you are involved in it, and how you will be involved in communities we serve at the University of Rochester School of Medicine.","limit":200,"unit":"words","fam":"service"}]},{"name":"University of South Alabama Whiddon College of Medicine","state":"AL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-south-alabama-whiddon-college-of-medicine.1517791/","prompts":[{"p":"The Whiddon College of Medicine is dedicated to training resilient, adaptable physicians who provide exceptional, patient-centered care to individuals from all walks of life. Please share a significant life experience or aspect of your background that has shaped your ability to effectively communicate with, empathize with, and care for patients with varied healthcare needs, including those in underserved or rural communities.","limit":0,"unit":"words","fam":"diversity"},{"p":"Although interests may change, what areas of medicine are you primarily interested in at the current time?","limit":0,"unit":"words","fam":"career"}]},{"name":"University of South Carolina School of Medicine Columbia","state":"SC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-south-carolina-school-of-medicine-columbia.1517845/","prompts":[],"none":"No prompts posted yet"},{"name":"University of South Carolina School of Medicine Greenville","state":"SC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-south-carolina-school-of-medicine-greenville.1517846/","prompts":[{"p":"At USCSOM Greenville, Lifestyle Medicine is integrated into all four years of our curriculum. Please share how you envision lifestyle medicine affecting your time as a medical student and as a practicing physician.","limit":500,"unit":"words","fam":"why"},{"p":"Service is a stated value in our school's mission and is central to the USCSOM Greenville community. It can take many forms — formal or informal, sustained or brief, recognized or unseen. Share a service experience that has been significant in your journey, and reflect on what motivates your commitment to continue serving others through the field of medicine.","limit":500,"unit":"words","fam":"service"},{"p":"Please consider sharing experiences, challenges, family or personal circumstances, interests, etc. that you believe would bring added value to the learning community at USC School of Medicine Greenville.","limit":0,"unit":"words","fam":"diversity"},{"p":"Please briefly describe any close ties to SC and/or USCSOM Greenville that you indicated in Question 2.","limit":50,"unit":"words","fam":"why"},{"p":"Why have you chosen to apply to USC School of Medicine Greenville and how do you think your education at USCSOM Greenville will prepare you to become a physician in the future?","limit":0,"unit":"words","fam":"why"},{"p":"What areas of medicine are you interested in at this time or what areas do you plan to pursue, and why?","limit":0,"unit":"words","fam":"career"},{"p":"Is there any additional information you would like the Admissions Committee to consider that has not been previously addressed? (If not applicable, please write N/A)","limit":0,"unit":"words","fam":"anything"},{"p":"If you are not accepted to medical school for the 2027 entering class, what are your plans?","limit":0,"unit":"words","fam":"career"},{"p":"Please briefly describe circumstances regarding any courses with a grade less than a B minus, or any course withdrawals. Additionally, please describe the circumstances if you took any required courses as Pass/Fail rather than graded.","limit":0,"unit":"words","fam":"other"},{"p":"If you are NOT currently enrolled in an academic program for this year, do not expect to spend this academic year in school, please explain how you intend to use this time. (If not applicable, please write N/A)","limit":0,"unit":"words","fam":"gap"},{"p":"Sometimes the Admissions Committee has questions about an applicant's MCAT score or GPA. Please use this space to discuss any insight you have into your past performance as well as lessons learned to improve future performance.","limit":0,"unit":"words","fam":"challenge"},{"p":"What best describes your experience in a rural area?How did spending time in a rural area affect your access to healthcare?","limit":0,"unit":"words","fam":"other"},{"p":"How do primary care physicians improve the health of individuals and communities? Can you describe a time—whether through volunteering, shadowing, or personal experience—when you saw these principles in action and the impact they had?","limit":0,"unit":"words","fam":"career","opt":1,"group":"Primary Care Accelerated Track (optional)"},{"p":"The PCAT program accelerates training for scholars committed to the specialty of Family Medicine. Describe the specific experiences that have influenced your decision to pursue this program and demonstrate your commitment to Family Medicine. In your response, consider including clinical experiences, volunteer work, research, personal stories, or other relevant activities that have shaped your interest and dedication to this field.","limit":0,"unit":"words","fam":"career","opt":1,"group":"Primary Care Accelerated Track (optional)"}]},{"name":"University of South Dakota Sanford School of Medicine","state":"SD","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-south-dakota-sanford-school-of-medicine.1517854/","prompts":[],"none":"No prompts posted yet"},{"name":"University of South Florida Morsani College of Medicine","state":"FL","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-south-florida-morsani-college-of-medicine.1517855/","prompts":[{"p":"Do you believe the competitiveness (i.e. course requirements, experiences, academic performance, etc.) of your application for medical school has been impacted by the COVID-19 pandemic? If yes, please provide specifics as to how your competitiveness was impacted. If no, type “N/A”.","limit":1500,"unit":"chars","fam":"challenge"},{"p":"What do you see as the most likely practice scenario for your future medical career? (list of options): Private Practice, Academic Medicine, Public Health, Health Care Administration, Health Policy, Other","limit":0,"unit":"words","fam":"career","group":"Choose 1 of 6 options"},{"p":"Describe the knowledge, skills, and attributes you have developed in preparation for the career path you have chosen in the previous question.","limit":0,"unit":"words","fam":"career"},{"p":"OPTIONAL: The USF Morsani College of Medicine’s Scholarly Concentrations program aims to support the educational development of medical students by providing opportunities for academic endeavors in areas of special interest. This program facilitates self-directed learning, enhances interactions between students and fosters relationships between students and faculty. Scholarly concentrations provide a forum where diversity of ideas and perspectives are valued. Each concentration includes elements of course work, practical application and scholarly presentation. Please review our Scholarly Concentrations website to determine which concentration would be of interest to you and answer the following question: a. How would the USF Morsani College of Medicine’s Scholarly Concentrations Program help your personal career goals?","limit":0,"unit":"words","fam":"career","opt":1},{"p":"If you have experienced academic difficulties, please explain the situation and how it was resolved. (Please explain all grades less than a \"B\", including B-, or any \"withdrawal\" on your transcripts).","limit":0,"unit":"words","fam":"challenge"}]},{"name":"University of Tennessee HSC College of Medicine","state":"TN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-tennessee-hsc-college-of-medicine.1517857/","prompts":[{"p":"List all courses you are taking or planning to take within the current academic year (e.g., Fall 2026 and/or Spring 2027). List course(s), title, and credit hours.","limit":1000,"unit":"chars","fam":"other","opt":1},{"p":"Any additional information not previously provided in the personal comments of your AMCAS primary application.","limit":250,"unit":"chars","fam":"anything","opt":1},{"p":"Imagine you are a medical student in a clinic and encounter a patient whose cultural background and beliefs differ significantly from your own. The patient is hesitant about a treatment plan that is standard practice but conflicts with their personal beliefs. How would you approach this situation to ensure the patient feels heard and respected while also providing the best possible care?","limit":3000,"unit":"chars","fam":"ethics"}]},{"name":"University of the Incarnate Word School of Osteopathic Medicine (UIWSOM)","state":"TX","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-the-incarnate-word-school-of-osteopathic-medicine-uiwsom.1518507/","prompts":[],"none":"No prompts posted yet"},{"name":"University of Toledo College of Medicine","state":"OH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-toledo-college-of-medicine.1517866/","prompts":[{"p":"We invite you to briefly discuss any connections you may have to the region of Northwest Ohio.","limit":400,"unit":"words","fam":"why","opt":1},{"p":"If you feel you have any aspects of your record that may potentially negatively influence your application to our medical school, we encourage you to use this space to discuss them in order to provide the admissions committee with further context about your application. (Examples of possible topics include MCAT scores lower than our class average, low grades, withdrawn course, institutional action/student conduct violation.)","limit":400,"unit":"words","fam":"anything","opt":1},{"p":"The University of Toledo College of Medicine and Life Sciences' mission is to improve health in the communities and region we serve by educating and training excellent clinicians and scientists, providing high-quality patient care and conducting nationally recognized research\nValues contributing to this mission are the Association of American Medical Colleges (AAMC) Premed Competencies of:\nCommitment to Learning and Growth\nScientific Inquiry\nService Orientation\nPlease describe how your past experiences predict your potential to contribute to at least one of these mission areas, and reflect on how the corresponding AAMC Premed Competencies have shaped your personal and professional development.","limit":600,"unit":"words","fam":"why"},{"p":"One of the AAMC Core Competencies for entering medical students involves resilience and adaptability. This competency involves the ability to tolerate stressful or changing environments or situations and adapt effectively to them. Additional characteristics of this competency are persistence and the ability to recover from setbacks. Discuss a specific experience from your life that you feel demonstrates your level of competence in resilience and adaptability as described above. As part of your discussion, explain how you feel this experience will help you meet new challenges you may face in medical school.","limit":600,"unit":"words","fam":"challenge"}]},{"name":"University of Utah School of Medicine","state":"UT","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-utah-school-of-medicine.1517867/","prompts":[{"p":"The Spencer Fox Eccles School of Medicine’s mission guides our work and community. What aspect of our mission stands out most to you, and how have you demonstrated alignment with this mission through your experiences and preparation for medical school? (500 character limit)","limit":500,"unit":"chars","fam":"why"},{"p":"The University of Utah’s “Impact 2030” vision emphasizes collaboration to address society’s most pressing challenges. What healthcare-related “big problem” in your community or in communities you have served concerns you most? How do you see yourself contributing to a solution to this issue in your role as a future physician? (500 character limit)","limit":500,"unit":"chars","fam":"service"}]},{"name":"University of Vermont Larner College of Medicine","state":"VT","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-vermont-robert-larner-college-of-medicine.1517868/","prompts":[{"p":"The Larner College of Medicine curriculum emphasizes active in-person participation and peer co-learning. This relies on individual students preparing for, and being actively involved in, participatory class sessions. Please share your thoughts on the suitability of active learning for you. Consider the points below to guide your response. (Maximum 400 word count).\n- The value of balancing your learning with the teaching of your classmates.\n- Any potential challenges to this approach to learning.\n- Personal contributions to such a learning environment and areas of growth.\n- Examples of navigating a group learning process such as a flipped classroom experience.","limit":400,"unit":"words","fam":"why"},{"p":"The Larner College of Medicine at the University of Vermont recognizes that diversity extends beyond chosen and unchosen identities and encompasses an individual’s entire experiences. Diverse environments can promote growth and provide an opportunity for reflection. Reflect on a time you learned something from someone or a group of people who are unlike yourself and how that challenged your preconceptions or biases. How will this experience influence your behavior in the future? (Maximum 400 word count)","limit":400,"unit":"words","fam":"diversity"},{"p":"The Larner College of Medicine has core values that are reflected in our professionalism statement. How has your understanding of what professionalism means evolved over time? Reflect on a personal experience that contributed to your understanding of your own core values. (Maximum 300 word count).","limit":300,"unit":"words","fam":"other"},{"p":"What unique opportunities at Larner College of Medicine would be meaningful to you in your education and how do these align with your larger goal of becoming a physician? (Maximum 250 word count).","limit":250,"unit":"words","fam":"why"},{"p":"(Optional) Use this space to share any information, not presented elsewhere, that will clarify any aspect of your application. If you are a reapplicant, you may choose to share what you have done since your previous application. (Maximum 250 word count).","limit":250,"unit":"words","fam":"anything","opt":1}]},{"name":"University of Virginia School of Medicine","state":"VA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-virginia-school-of-medicine.1517869/","prompts":[{"p":"Why are you interested in attending the University of Virginia School of Medicine? What factors will be most important to you in choosing a medical school? Please answer the question in 350 words or less.","limit":350,"unit":"words","fam":"why"},{"p":"Tell us about a challenge or obstacle you experienced. How did you manage it? Please answer the question in 350 words or less.","limit":350,"unit":"words","fam":"challenge"},{"p":"Please briefly describe anything that has impacted your college or postgrad experience.","limit":0,"unit":"words","fam":"challenge"},{"p":"Please list any and all future activities in clinical work, shadowing, research, or community service that you plan to pursue in the upcoming year.","limit":0,"unit":"words","fam":"gap"}]},{"name":"University of Washington School of Medicine","state":"WA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-washington-school-of-medicine.1517870/","prompts":[{"p":"Why WWAMI? Describe how your preparation, service, and career goals align with the cohort that you are applying to [i.e., WY, AK, MT, ID, WA (Seattle or Spokane)].","limit":0,"unit":"words","fam":"why"}]},{"name":"University of Wisconsin School of Medicine and Public Health","state":"WI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-wisconsin-school-of-medicine-and-public-health.1517872/","prompts":[{"p":"The Admissions Committee is committed to comprehensive, mission-aligned evaluation of all applicants. Review our institution's mission. Using specific examples, discuss how and why you believe you are a good fit for the University of Wisconsin School of Medicine and Public Health. (500 words max.)","limit":500,"unit":"words","fam":"why"},{"p":"UW SMPH uses the AAMC's Premed Competencies for Entering Medical Students as an applicant evaluation framework. Choose one of the professional competencies from the drop-down list where you have experienced growth. Using specific examples, describe your development in this competency. (250 words max.)\nCommitment to growth and learning, Empathy and compassion, Ethical responsibility to self and others, Interpersonal Skills, Oral communication, Reliability and dependability, Resilience and adaptability, Self-awareness, Service orientation, Teamwork and collaboration, Understanding others.","limit":250,"unit":"words","fam":"other","group":"Choose 1 of 11 competencies"},{"p":"Reflect on a time when a failure, or an apparent failure, set you up for later success. Do you have a favorite failure that you now see as a pivotal moment in your personal or professional growth? (250 words max.)","limit":250,"unit":"words","fam":"challenge"},{"p":"Individual and population health flow from the intersections between healthcare outcomes, sociopolitical factors, economic, historical and other systemic factors. Choose a broader issue or policy that impacts health outcomes where you believe change is needed. Discuss the role you hope to play as a physician in addressing this issue. (250 words max).","limit":250,"unit":"words","fam":"career"},{"p":"Individuals reapplying are required to submit a statement indicating what has changed since the previous application to the UW School of Medicine and Public Health MD or MD/PhD program (e.g., additional academic work, new letters of recommendation, work and volunteer experience, life changes, etc.). If switching application pathway (e.g. to WARM from regular MD or from regular MD to MD/PhD), please explain the decision/change. (500 words max)","limit":500,"unit":"words","fam":"other","group":"Reapplicants only"},{"p":"[Optional] IA/Criminal offense explanation","limit":0,"unit":"words","fam":"anything","opt":1}]},{"name":"USC Keck School of Medicine","state":"CA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-southern-california-keck-school-of-medicine.1517856/","prompts":[{"p":"What is the most fun you’ve had lately?","limit":0,"unit":"words","fam":"other"},{"p":"If you had to give yourself a nickname, what would it be?","limit":0,"unit":"words","fam":"other"},{"p":"What are three things you don't care about at all?","limit":0,"unit":"words","fam":"other"},{"p":"Describe a situation in which you didn’t get something you felt you deserved.","limit":0,"unit":"words","fam":"challenge"},{"p":"What is your special talent?","limit":0,"unit":"words","fam":"other"},{"p":"Is there anything else you would like us to know? Please respond in 200 words or less.","limit":200,"unit":"words","fam":"anything"}]},{"name":"UT Health San Antonio Long School of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-texas-at-san-antonio-long-school-of-medicine.1517860/","prompts":[],"none":"No written essays reported"},{"name":"UT Rio Grande Valley School of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-texas-rio-grande-valley-school-of-medicine.1517859/","prompts":[{"p":"The University of Texas Rio Grande Valley (UTRGV) School of Medicine prepares physicians to serve communities in the Rio Grande Valley and other similarly underserved regions. Describe one significant health challenge affecting communities like those in the RGV. Briefly discuss how your experiences or observations have shaped your understanding of this issue, and how training in this environment may influence the kind of physician you hope to become.","limit":250,"unit":"words","fam":"service"},{"p":"Describe a time when you worked with others to address a challenging problem that affected a group, organization, or community. Please discuss the challenge or situation. What the outcome or impact of your collaboration was. What this experience taught you about collaboration, leadership, and working in healthcare, and how it might influence your future role as a physician.","limit":250,"unit":"words","fam":"team"},{"p":"Describe an experience in which you were required to make a difficult decision. In your response, please discuss • How you approached the decision-making process • The factors you considered • The outcome of your decision • What this experience taught you about responsibility, accountability, or leadership.","limit":250,"unit":"words","fam":"other"},{"p":"Describe a commitment you have maintained over time to a community, organization, or cause. This experience may be related to healthcare, but it does not have to be. In your response, please discuss: • What initially motivated your involvement • What sustained your commitment over time • How this experience has shaped your values, perspective, or approach to serving others. What was the impact of your commitment on the organization/community.","limit":250,"unit":"words","fam":"service"}]},{"name":"UT Southwestern Medical School","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-texas-southwestern-medical-school.1517864/","prompts":[{"p":"Describe a group project or collaborative experience that you are most proud of. What was your role, and how did you contribute to the group’s success? Reflect on how you navigated challenges or differing perspectives.","limit":2500,"unit":"chars","fam":"team"},{"p":"Describe a time that you have witnessed someone acting unethically or dishonestly, or experienced a behavior of harassment or discrimination. What did you do? Describe your reaction. Is there anything you might do differently now in retrospect?","limit":2500,"unit":"chars","fam":"ethics"},{"p":"Describe an experience that deepened your understanding of people whose backgrounds or life experiences differ from your own. How did this experience shape your perspective?","limit":2500,"unit":"chars","fam":"diversity"},{"p":"(OPTIONAL) Tell us about a community service experience that had a significant impact on you. What made it meaningful, and what did you learn through your involvement?","limit":2500,"unit":"chars","fam":"service","opt":1},{"p":"(Optional) Please explain any academic discrepancies or extenuating circumstances that you feel the Admissions Committee should know.","limit":2500,"unit":"chars","fam":"anything","opt":1}]},{"name":"UT Tyler School of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-texas-at-tyler-school-of-medicine.1517865/","prompts":[{"p":"Our mission is to improve the quality of life and reduce health disparities in our rural East Texas region. Please indicate (select one) your connection to East Texas as outlined in our county map and explain below: -I have direct ties to the East Texas region (born, graduated high school, community college, undergraduate, etc.) -I have indirect ties to the East Texas region (family members, in-laws, visited East Texas frequently, attended summer camp in East Texas, etc.) -I have ties to a rural region with similar characteristics to the East Texas region (size, demographics, health disparities, etc.) -I do not have ties to the East Texas region; however, I’m interested in practicing in this area after graduation. -I do not have ties to the East Texas region but am still interested in attending the UT Tyler School of Medicine. Explain","limit":250,"unit":"words","fam":"why","group":"Select 1 of 5 connection options"},{"p":"What have you done between the last application cycle to make your application stronger?","limit":0,"unit":"words","fam":"other"},{"p":"The mission of the UT Tyler SOM is fourfold: Community: Embed the School of Medicine within East Texas, focusing on communication, responsiveness, inclusion, and community. The School of Medicine in East Texas, and everything we do will be in partnership with our communities. Education: Recruit, support and develop a representative healthcare and research workforce from East Texas, focused on reducing health disparities in East Texas. Research: Develop an array of biomedical, clinical, preventive, translational and population-based research programs focused on understanding and eliminating health disparities in East Texas. Clinical: Expand access to top-quality healthcare in the local communities of East Texas by developing and implementing innovative healthcare systems and leveraging existing infrastructure and programs. Why are you interested in applying to UT Tyler's SOM?","limit":500,"unit":"words","fam":"why"},{"p":"Please describe a significant personal challenge you have faced, one which you feel has helped to shape you as a person. Please include how you got through the experience and what you learned about yourself as a result. Examples may include: moral or ethical dilemma, a situation of personal adversity; or a hurdle in your life that you worked hard to overcome.","limit":500,"unit":"words","fam":"challenge"},{"p":"Optional question (highly recommend): Please use this space to share with the committee any additional information that may help us evaluate your candidacy that is not addressed elsewhere in the application.","limit":500,"unit":"words","fam":"anything","opt":1}]},{"name":"UTMB John Sealy School of Medicine","state":"TX","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-university-of-texas-medical-branch-sealy-school-of-medicine.1517862/","prompts":[{"p":"Describe a situation where your team's success depended on your ability to learn a new skill or perspective quickly. How did your contributions specifically alter the group’s outcome?","limit":300,"unit":"words","fam":"team","group":"Choose 2 of 6"},{"p":"Analyze a time that you made an error in a professional or academic setting. Provide your response, how you disclosed it, and any changes you made to prevent it from recurring.","limit":300,"unit":"words","fam":"challenge","group":"Choose 2 of 6"},{"p":"Scientific inquiry is important for being a physician. Describe a time you encountered a claim or piece of information that you initially doubted. How did you verify the truth and how will this skepticism serve you as a physician?","limit":300,"unit":"words","fam":"other","group":"Choose 2 of 6"},{"p":"Identify a specific trait that you look for in your physicians that you currently lack. What is your plan to develop this attribute during your time at John Sealy School of Medicine?","limit":300,"unit":"words","fam":"why","group":"Choose 2 of 6"},{"p":"If you have any work experience, particularly with significant responsibilities, explain how those skills will help you be a better physician.","limit":300,"unit":"words","fam":"other","group":"Choose 2 of 6"},{"p":"John Sealy School of Medicine at the University of Texas Medical Branch serves patients throughout Texas, focusing on Galveston County and the Gulf Coast Region. Are there particular characteristics of our school and/or the Galveston area in terms of location, history, regional mission, or other attributes that make you especially interested in matriculating here?","limit":300,"unit":"words","fam":"why","group":"Choose 2 of 6"}]},{"name":"Vanderbilt University School of Medicine","state":"TN","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-vanderbilt-university-school-of-medicine.1517873/","prompts":[{"p":"Please reflect on the upbringing, background, and experiences in your life that have shaped who you are as a person and will help define the person you want to be in the future. In other words, what makes you who you are?","limit":800,"unit":"words","fam":"diversity"},{"p":"Tell us about a time when you interacted with someone who is different than you. What did you learn? Would you do anything differently and if so, what?","limit":600,"unit":"words","fam":"diversity"},{"p":"It is important to understand that everyone needs help at various times in their lives. Reflecting on the last five years, describe a time you asked for help and what you gained from that experience that has influenced your approach to asking for help.","limit":600,"unit":"words","fam":"challenge"},{"p":"Please briefly summarize your activities since graduating from college. If you are still enrolled in undergraduate studies, please comment on any new projects, roles or initiatives undertaken since submitting your AMCAS application.","limit":200,"unit":"words","fam":"gap","opt":1}]},{"name":"Virginia Commonwealth University School of Medicine","state":"VA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-virginia-commonwealth-university-school-of-medicine.1517874/","prompts":[{"p":"Using specific examples, discuss how your mission and values align with those of VCU School of Medicine.","limit":2000,"unit":"chars","fam":"why"},{"p":"Describe an experience that led you to change your views about an issue for which you previously held a strong opinion.","limit":2000,"unit":"chars","fam":"other"},{"p":"Please briefly explain any lapses in your journey to medicine that are not explained in your application.","limit":2000,"unit":"chars","fam":"gap"},{"p":"Please briefly explain any low GPAs or poor grades.","limit":2000,"unit":"chars","fam":"anything"},{"p":"What will you be doing for the next twelve months during the application cycle?","limit":2000,"unit":"chars","fam":"gap"}]},{"name":"Virginia Tech Carilion School of Medicine","state":"VA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-virginia-tech-carilion-school-of-medicine.1517875/","prompts":[{"p":"Reflect on a trait or characteristic you are proud of that you feel is most vulnerable to being lost on your journey to becoming a physician. How do you plan to protect it?","limit":400,"unit":"words","fam":"other"},{"p":"Describe a time when doing the \"right\" thing conflicted with rules, authority, or expectations. How did you handle it?","limit":400,"unit":"words","fam":"ethics"},{"p":"Beyond the rise of AI, what do you consider the greatest challenge facing your generation, and how do you plan to address it?","limit":400,"unit":"words","fam":"other"},{"p":"Please list any publications in the appropriate citation format using the text box below.","limit":400,"unit":"words","fam":"career","opt":1}]},{"name":"Wake Forest University School of Medicine","state":"NC","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-wake-forest-university-school-of-medicine.1517876/","prompts":[{"p":"The mission of our academic health system is to improve health for all. Consider your abilities, insights, and previous experiences and then tell us about your potential to help improve health for all.","limit":200,"unit":"words","fam":"service"},{"p":"Describe a non-academic challenge you have faced and explain how you overcame it.","limit":200,"unit":"words","fam":"challenge"},{"p":"From your list of \"most meaningful experiences\" on the AMCAS application, choose one that has been the most formative in terms of your desire for a career in medicine. Why did that experience have such meaning for you in your decision-making process?","limit":200,"unit":"words","fam":"other"},{"p":"Please share an experience that demonstrates how you have collaborated with others.","limit":200,"unit":"words","fam":"team"},{"p":"Tell us about a time you have committed yourself to something.","limit":200,"unit":"words","fam":"other"},{"p":"Tell us about any specific reason(s) (personal, educational, etc.) why you see yourself here at the Wake Forest University School of Medicine.","limit":150,"unit":"words","fam":"why"},{"p":"Please tell us an interesting fact about yourself that a casual acquaintance may find surprising or interesting.","limit":50,"unit":"words","fam":"other"}]},{"name":"Washington State University Elson S. Floyd College of Medicine","state":"WA","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-washington-state-university-elson-s-floyd-college-of-medicine.1517877/","prompts":[],"none":"No prompts posted yet"},{"name":"Washington University in St. Louis School of Medicine","state":"MO","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-washington-university-in-st-louis-school-of-medicine.1517878/","prompts":[{"p":"(Only required if you indicate you're not currently an undergrad) Have you already completed your undergraduate education, have you had your college or graduate education interrupted, or do you plan not to be a full-time student during your application year? If yes, describe in chronological order your activities during the time(s) when you were not enrolled as a full-time student.","limit":2000,"unit":"chars","fam":"gap","group":"Conditional: non-undergrads"},{"p":"Describe a time or situation where you have been unsuccessful or failed.","limit":3000,"unit":"chars","fam":"challenge"},{"p":"Is there anything else you would like to share with the Committee on Admissions?","limit":3000,"unit":"chars","fam":"anything"},{"p":"Have you, a family member, or a research mentor had any personal experience or relationship with WashU Medicine? If yes: Please explain.","limit":4000,"unit":"chars","fam":"why"}]},{"name":"Wayne State University School of Medicine","state":"MI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-wayne-state-university-school-of-medicine.1517880/","prompts":[{"p":"When reflecting on the roles and responsibilities of a physician, please discuss what motivated your interest? What are potential challenges to pursuing a career in medicine?","limit":1250,"unit":"chars","fam":"career"},{"p":"What are the healthcare challenges faced by under-resourced communities in the U.S.? Why do these healthcare challenges exist? How would you address them?","limit":1250,"unit":"chars","fam":"service"},{"p":"Which of your experiences and activities align with WSU SOM’s mission? Please discuss how they align.","limit":1250,"unit":"chars","fam":"why"},{"p":"The Wayne State University School of Medicine aims to provide a rich, varied, and inclusive educational experience for all members of the class. How would you advance belonging and contribute to the educational experience of fellow medical students?","limit":1250,"unit":"chars","fam":"diversity"},{"p":"Please answer if you have had a gap or growth year (career change, re-applicant, additional education, etc.). A “growth year” is defined as a period of time between the end of your undergraduate education and a year or more prior to the start of medical school. What activities have you participated in or plan to participate in during this period? How does this relate to your future career in medicine?","limit":0,"unit":"words","fam":"gap","group":"Conditional: gap/growth year"}]},{"name":"Weill Cornell Medicine","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-weill-cornell-medicine.1517881/","prompts":[{"p":"Please write a brief statement giving your reasons for applying to Weill Cornell Medical College.","limit":1525,"unit":"chars","fam":"why"},{"p":"Describe a setback or failure that required you to reassess your approach. How did you respond?","limit":1525,"unit":"chars","fam":"challenge"},{"p":"Please share something you became curious about and chose to explore further. What motivated your interest, and what did you learn through the process? (This does not have to be related to medicine).","limit":1525,"unit":"chars","fam":"other"},{"p":"Describe a time when your perspective was challenged by someone with a different viewpoint. How did you engage with that difference, and what did you take away from the experience?","limit":1525,"unit":"chars","fam":"diversity"},{"p":"If you are NOT attending college full time during the upcoming (2026-2027) academic year, what are your plans?","limit":1525,"unit":"chars","fam":"gap"}]},{"name":"West Virginia School of Osteopathic Medicine (WVSOM)","state":"WV","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-west-virginia-school-of-osteopathic-medicine-wvsom.1518508/","prompts":[{"p":"Why do you want to be an osteopathic physician?","limit":500,"unit":"chars","fam":"osteo"},{"p":"What advantage do you see in attending WVSOM over other medical schools?","limit":500,"unit":"chars","fam":"why"},{"p":"Describe an ethically challenging situation you have been in, and how you responded.","limit":500,"unit":"chars","fam":"ethics"},{"p":"What do you feel it will take for you to succeed in medical school?","limit":500,"unit":"chars","fam":"other"},{"p":"Provide a brief comment about your study habits.","limit":500,"unit":"chars","fam":"other"},{"p":"Describe a situation in work, volunteer activities, or organizations where you demonstrated your ability to work well with others.","limit":500,"unit":"chars","fam":"team"},{"p":"What experiences (living, working, or visiting) have you had in rural areas?","limit":500,"unit":"chars","fam":"service"},{"p":"Briefly comment on how your volunteer experience benefited you.","limit":500,"unit":"chars","fam":"service"}]},{"name":"West Virginia University School of Medicine","state":"WV","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-west-virginia-university-school-of-medicine.1517883/","prompts":[],"none":"No prompts posted yet"},{"name":"Western Michigan University Homer Stryker M.D. School of Medicine","state":"MI","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-western-michigan-university-homer-stryker-m-d-school-of-medicine.1517882/","prompts":[{"p":"1) Please explain both of the following:\na) The specific reason(s) you have chosen to apply to WMed.\nb) How you will utilize the unique features of WMed's mission, vision, and curriculum to achieve your career goals.","limit":2000,"unit":"chars","fam":"why"},{"p":"2) What unique values, skills, talents, and/or life experiences will you bring to WMed and the practice of medicine?","limit":2000,"unit":"chars","fam":"diversity"},{"p":"3) WMed Re-Applicants Only: Describe the changes to your application from previous cycles - include academics, experiences, and/or personal attributes.","limit":2000,"unit":"chars","fam":"other","group":"Reapplicants only"},{"p":"4) Optional: Please explain any connection you have to Southwest Michigan.","limit":2000,"unit":"chars","fam":"why","opt":1},{"p":"5) Optional: Is there any additional information not included elsewhere in your application you would like the Admissions Committee to know?","limit":2000,"unit":"chars","fam":"anything","opt":1}]},{"name":"Western University of Health Sciences College of Osteopathic Medicine of the Pacific (WesternU-COMP)","state":"CA","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-western-university-of-health-sciences-college-of-osteopathic-medicine-of-the-pacific-westernu-comp.1518509/","prompts":[{"p":"What is your purpose of pursuing medical education, and why COMP Pomona?","limit":0,"unit":"words","fam":"why"},{"p":"Briefly discuss any extenuating circumstances which you feel are pertinent to your application (poor grades, course withdrawals, lapse in your education, etc.).","limit":0,"unit":"words","fam":"other"},{"p":"If you have not taken any coursework for over 3 years, please explain why and what you have been doing during that period of time.","limit":0,"unit":"words","fam":"gap"}]},{"name":"Western University of Health Sciences College of Osteopathic Medicine of the Pacific - Northwest (WesternU-COMP-Northwest)","state":"OR","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-western-university-of-health-sciences-college-of-osteopathic-medicine-of-the-pacific-westernu-comp.1518509/","prompts":[{"p":"What experience observing a DO solidified your desire/ambition to become an osteopathic physician? (This could be a formal shadowing experience (one-on-one with a physician), scribing, observing your own physician, friend, or family member who is a DO).","limit":0,"unit":"words","fam":"osteo"},{"p":"If you have not had the opportunity to shadow/observe a DO why is it important to you to become an osteopathic physician?","limit":0,"unit":"words","fam":"osteo"},{"p":"Describe how you would approach a clinical situation in which a patient's values, preferences, or healthcare decisions differ from your own perspective. What professional principles would guide your actions, and how would you ensure the patient receives respectful and patient-centered care?","limit":0,"unit":"words","fam":"ethics"},{"p":"How does the COMP Northwest Mission statement align with your values?","limit":0,"unit":"words","fam":"why"},{"p":"Why do you want to attend COMP Northwest in Lebanon, Oregon?","limit":0,"unit":"words","fam":"why"},{"p":"If yes, briefly describe your role and what skills you gained from participation in the research.","limit":0,"unit":"words","fam":"other"},{"p":"Briefly discuss any extenuating circumstances which you feel are pertinent to your application (poor grades, course withdrawals, lapse in your education, etc.).","limit":0,"unit":"words","fam":"other"},{"p":"If you have not taken any coursework for over 3 years, please explain why and what you have been doing during that period of time.","limit":0,"unit":"words","fam":"gap"}]},{"name":"William Carey University College of Osteopathic Medicine (WCUCOM)","state":"MS","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-william-carey-university-college-of-osteopathic-medicine-wcucom.1518511/","prompts":[{"p":"In the space below (not to exceed 500 words), please explain how your ambitions and career plans will help WCUCOM fulfill this mission.","limit":500,"unit":"words","fam":"career"}]},{"name":"Wright State University Boonshoft School of Medicine","state":"OH","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-wright-state-university-boonshoft-school-of-medicine.1517884/","prompts":[{"p":"If you earned a medically related certificate/license, how many hours have you worked in that role since earning your certificate/license? If not, please enter N/A.","limit":100,"unit":"chars","fam":"other"},{"p":"If there has been a significant economic hardship, please explain the circumstances. If none, please enter N/A.","limit":750,"unit":"chars","fam":"challenge"},{"p":"If your parents are Wright State University or Boonshoft School of Medicine graduates, please list their name(s), indicate if WSU or BSOM, and graduation year(s). If not, please enter N/A.","limit":100,"unit":"chars","fam":"other"},{"p":"If you have relatives who are Wright State University or Boonshoft School of Medicine alumni, current students, faculty, or staff, please indicate if WSU or BSOM and list their name(s). If not, please enter N/A.","limit":100,"unit":"chars","fam":"other"},{"p":"If you have applied to Wright State University Boonshoft School of Medicine in a previous cycle, please indicate the year(s) of your previous application(s). If not, please enter N/A.","limit":100,"unit":"chars","fam":"other"},{"p":"If you are a re-applicant, how has your application changed since the previous cycle? If not, please enter N/A.","limit":750,"unit":"chars","fam":"other","group":"Reapplicants only"},{"p":"What is the primary reason that you have chosen to apply to the Wright State University Boonshoft School of Medicine, and how do you see yourself contributing to the mission and community of the Boonshoft School of Medicine?","limit":750,"unit":"chars","fam":"why"},{"p":"(Optional) Are there any specific patient populations that you desire to serve as a physician? If so how do you envision yourself serving those populations?","limit":750,"unit":"chars","fam":"service","opt":1},{"p":"Please describe any experiences you have had in rural communities or rural health care settings. How have these experiences influenced your understanding of health care delivery and patient needs in rural areas? If none, please enter N/A.","limit":0,"unit":"words","fam":"service"},{"p":"If there has been or will be a gap in your education, please describe how you have/will use this time. If not, please enter N/A.","limit":750,"unit":"chars","fam":"gap"},{"p":"If you consider yourself a non-traditional candidate, please explain. If not, please enter N/A.","limit":750,"unit":"chars","fam":"diversity"},{"p":"Briefly describe any extenuating circumstances which you believe are pertinent to your application (i.e., poor grades, withdrawn courses, life events). If none, please enter N/A.","limit":750,"unit":"chars","fam":"anything"},{"p":"If you have attended any allopathic or osteopathic medical school, as a candidate for an M.D. or D.O., please list the name of the school and explain the reason for separation. If not, please enter N/A.","limit":750,"unit":"chars","fam":"other"},{"p":"If you are not a current resident of the state of Ohio, please describe your connection to Ohio. If not, please enter N/A.","limit":750,"unit":"chars","fam":"why"},{"p":"If you have a non-familial connection to Wright State University or the Boonshoft School of Medicine, please describe your connection. If none, please enter N/A.","limit":750,"unit":"chars","fam":"why"},{"p":"If you participated in the Wright State University Horizons in Medicine program, please list the year(s) you participated and briefly describe your experience in the program. If not, enter N/A.","limit":0,"unit":"words","fam":"other"}]},{"name":"Xavier University College of Osteopathic Medicine (XUCOM)","state":"OH","deg":"DO","url":"https://forums.studentdoctor.net/threads/2026-2027-xavier-college-of-osteopathic-medicine.1520535/","prompts":[{"p":"The Jesuit tradition at Xavier University emphasizes the Magis, the call to do more for others in the pursuit of justice, compassion, and excellence. Describe how one of your lived experiences aligns with this value and how this has informed your desire to pursue medicine at the Xavier University College of Osteopathic Medicine.","limit":250,"unit":"words","fam":"why"},{"p":"The Osteopathic philosophy and the Jesuit principle of cura personalis both emphasize treating the whole person-- mind, body, and spirit. Describe a concrete example of how your experience aligns with this value, and how has this informed your desire to pursue Osteopathic Medicine.","limit":250,"unit":"words","fam":"osteo"},{"p":"The path to medicine often demands careful discernment in the face of adversity. Share a significant challenge you have faced, how you reflected on that experience, and how it strengthened your resilience and commitment to becoming a physician.","limit":250,"unit":"words","fam":"challenge"}]},{"name":"Yale School of Medicine","state":"CT","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-yale-school-of-medicine.1517885/","prompts":[{"p":"Have there been any updates regarding your activities / achievements / distinctions since completing your AMCAS application, or do you have any important accomplishments you have not yet shared with us here or in your AMCAS application? The Office of Admissions will review your activities / achievements / distinctions in the Experiences section of the AMCAS Application, so you do not need to restate anything included there.","limit":0,"unit":"words","fam":"anything","opt":1},{"p":"Yale School of Medicine is committed to improving the health of all people. How have your experiences prepared you to care for all individuals regardless of background, education, or viewpoint?","limit":500,"unit":"words","fam":"diversity"},{"p":"While there is great emphasis on the physician-patient relationship, Yale School of Medicine also emphasizes the importance of training future physicians to care for communities and populations. Describe how your experiences would contribute to this aspect of the mission of the Yale School of Medicine.","limit":500,"unit":"words","fam":"service","group":"Required Essay 2: choose 1 of 2 (MD applicants)"},{"p":"Research is essential to patient care, and all students at Yale School of Medicine complete a research thesis. Tell us how your research interests, skills and experiences would contribute to scholarship at Yale School of Medicine.","limit":500,"unit":"words","fam":"career","group":"Required Essay 2: choose 1 of 2 (MD applicants)"},{"p":"If you are not enrolled in college or graduate school classes for the duration of the current academic year, please tell us how you are spending your time. Include both your current and any planned activities prior to enrolling in medical school.","limit":0,"unit":"words","fam":"gap"},{"p":"It should be used to bring to the attention of the Admissions Committee any important information relevant to your qualifications not discussed in other sections of your Yale Secondary Application. (500 words, optional)","limit":500,"unit":"words","fam":"anything","opt":1}]},{"name":"Zucker School of Medicine at Hofstra/Northwell","state":"NY","deg":"MD","url":"https://forums.studentdoctor.net/threads/2026-2027-hofstra-zucker.1518237/","prompts":[{"p":"Please indicate what you have been doing since the time of graduation until now.","limit":250,"unit":"words","fam":"gap"},{"p":"Explain why the Zucker School of Medicine at Hofstra/Northwell is a good fit for your medical education journey?","limit":250,"unit":"words","fam":"why"},{"p":"“The School of Medicine, in a culture of community, scholarship and innovation, is dedicated to inspiring promising students to lead and transform medicine for the betterment of humanity.” How do you feel you would contribute to the Zucker School of Medicine’s mission and values and where do you see this taking you in the future?","limit":250,"unit":"words","fam":"why"},{"p":"If yes, what year(s)? and what was the outcome?","limit":250,"unit":"words","fam":"other","cut":1}]}]};
